const a={id:"s05",unidad:1,semana:5,kind:"aprendizaje",temaGenerador:"Una escuela que todas las personas pueden recorrer",title:"Una escuela que todas las personas pueden recorrer",subtitle:"Coordenadas, texturas, participación y trabajo seguro para identificar y reducir barreras",icon:"Accessibility",color:"var(--area-art)",contexto:"La accesibilidad se construye con las personas, no para ellas sin preguntar. Esta semana usamos coordenadas para ubicar espacios, texturas y contraste para comunicar, participación para escuchar y decidir, y herramientas con procedimientos seguros. Trabajaremos con criterios publicados y un caso ficticio; haremos una prueba de claridad entre pares con los ojos abiertos. La consulta especializada con personas con discapacidad o especialistas queda pendiente hasta que la escuela pueda acordarla. Un mapa táctil puede orientar, pero no garantiza acceso para todas las personas ni elimina todas las barreras: también existen barreras físicas, de comunicación, sensoriales y actitudinales que la escuela debe identificar y atender.",ejes:["equidad","vida-ciudadana","seguridad","tecnologia"],media:{id:"s05-portada",kind:"image",title:"Recorrido accesible por la escuela",aspect:"16:9",alt:"Estudiantes y una persona adulta revisan un plano táctil de la escuela; una ruta con relieve conecta la entrada, la dirección, un aula y los baños.",brief:'Ilustración editorial conceptual de una escuela pública guatemalteca. En una mesa, estudiantes revisan entre pares un plano táctil con los ojos abiertos; una tarjeta visible dice "consulta especializada pendiente". El plano muestra cuadrícula, coordenadas grandes, una clave de tres texturas y una ruta continua en relieve. Al fondo se ven una rampa, pasamanos, señalización de alto contraste y un pasillo despejado. No presentar la escena como evidencia de una consulta local ya realizada; todas las personas mantienen los ojos abiertos y participan como ellas mismas. Evitar ayuda condescendiente y promesas de accesibilidad universal. Dimensiones: 1600x900.'},badge:{id:"cartografo-accesible",name:"Cartógrafo que escucha",icon:"Map",desc:"Ubicas espacios, pruebas la claridad entre pares y registras la consulta especializada como pendiente."},bank:[{fase:"comprobar",areas:["mat"],cnb:["mat:2.1.1"],prompt:"La serie **6, 16, 36, 76, …** sigue “×2, luego +4”. ¿Qué número sigue?",type:"number-input",props:{answer:156},id:"s05-banco-1"},{fase:"comprobar",areas:["l1"],cnb:["l1:5.2.2"],prompt:"Toca solo las palabras que caracterizan la señal.",type:"highlight",props:{target:"palabras connotativas",text:"Esta puerta {ancha} tiene una manija {lisa} y un rótulo {visible}."},id:"s05-banco-2"},{fase:"comprobar",areas:["cnt"],cnb:["cnt:4.2.1"],prompt:"¿Qué evidencia ilustra mejor cómo una actividad social puede proteger una vida sana?",type:"choice",props:{options:[{id:"a",text:"Un registro muestra asistencia voluntaria a un club de teatro, nuevas amistades y estrategias para manejar el estrés"},{id:"b",text:"Un anuncio repite una promesa sin mostrar actividad ni resultados"},{id:"c",text:"Una lista enumera sustancias sin relacionarlas con decisiones saludables"}],correct:["a"]},id:"s05-banco-3"},{fase:"comprobar",areas:["ccss"],cnb:["ccss:6.4.4"],prompt:"En un puerto europeo circulan mapas impresos, crece el comercio y se usan instrumentos para orientarse. ¿Qué conclusión explica mejor los viajes de larga distancia?",type:"choice",props:{options:[{id:"a",text:"La difusión de información, los intereses comerciales y las técnicas de navegación actuaron de manera combinada"},{id:"b",text:"Los mapas impresos hicieron innecesaria toda experiencia de navegación"},{id:"c",text:"El comercio impidió buscar rutas marítimas"}],correct:["a"]},id:"s05-banco-4"},{fase:"comprobar",areas:["l2"],cnb:["l2:3.3.4"],prompt:"Clasifica la intención principal de cada mensaje escolar.",type:"sort",props:{buckets:[{id:"i",label:"Informar",icon:"Info"},{id:"e",label:"Explicar",icon:"ListOrdered"},{id:"a",label:"Argumentar",icon:"MessageSquareText"}],items:[{id:"a",text:"La biblioteca abre a las siete.",bucket:"i"},{id:"b",text:"Primero gira la manija y luego empuja la puerta.",bucket:"e"},{id:"c",text:"Conviene despejar el corredor porque la observación halló tres obstáculos.",bucket:"a"}]},id:"s05-banco-5"},{fase:"comprobar",areas:["l3"],cnb:["l3:2.2.3"],prompt:"Choose the sentence with correct order.",type:"choice",props:{options:[{id:"a",text:"She opens the wide door slowly."},{id:"b",text:"She the wide door slowly opens."},{id:"c",text:"Slowly wide she door opens."}],correct:["a"]},id:"s05-banco-6"},{fase:"comprobar",areas:["fc"],cnb:["fc:3.2.1"],prompt:"Ordena un proceso participativo para mejorar el patio.",type:"order",props:{items:[{id:"a",text:"Preguntar a quienes usan el patio"},{id:"b",text:"Acordar una mejora posible"},{id:"c",text:"Realizar la acción acordada"},{id:"d",text:"Revisar el resultado con las personas participantes"}]},id:"s05-banco-7"},{fase:"comprobar",areas:["art"],cnb:["art:3.2.1"],prompt:"¿Qué par ofrece mayor contraste táctil para dos símbolos vecinos?",type:"choice",props:{options:[{id:"a",text:"Fieltro suave y cartón corrugado"},{id:"b",text:"Dos retazos del mismo fieltro"},{id:"c",text:"Dos hojas de papel liso"}],correct:["a"]},id:"s05-banco-8"},{fase:"comprobar",areas:["ef"],cnb:["ef:2.1.9"],prompt:"En una ejecución observada sin narración, Mateo hace un pase por arriba del hombro con salto usando la mano izquierda hacia una altura media. Suelta la pelota en el aire, pero se impulsa con el mismo pie izquierdo. ¿Qué falla observable y qué corrección corresponden?",type:"choice",props:{options:[{id:"a",text:"El apoyo es del mismo lado; debe impulsarse con el pie derecho, contrario a la mano izquierda, y conservar el pase medio"},{id:"b",text:"La liberación es tardía; debe esperar hasta tocar el suelo y luego pasar al pecho"},{id:"c",text:"La mano izquierda es la falla; debe usar siempre la derecha para cualquier altura"}],correct:["a"]},id:"s05-banco-9"},{fase:"comprobar",areas:["pyd"],cnb:["pyd:3.2.4"],prompt:"Una polea escolar tiene la cuerda deshilachada. ¿Qué haces antes de usarla?",type:"choice",props:{options:[{id:"a",text:"No usarla y reportar el daño para que una persona responsable la repare"},{id:"b",text:"Jalar más fuerte para terminar rápido"},{id:"c",text:"Pedir a alguien que se coloque debajo de la carga"}],correct:["a"]},id:"s05-banco-10"}]},e=JSON.parse('[{"missionId":"s05","version":"cnb-sexto-e397ce78b72e5452","lesson":{"id":"s05-art-1","title":"Texturas que se tocan y texturas que se ven","icon":"Hand","minutes":14,"gancho":"Compara al tacto tu mesa, tu ropa, una hoja de árbol y una piedra. ¿Qué palabras distinguen mejor sus superficies?","objetivos":["Comunicar diferencias entre texturas táctiles y visuales con vocabulario preciso"],"resumen":["La textura es cómo se siente o cómo parece que se siente una superficie.","Textura táctil: la que se percibe al tocar (la corteza de un árbol, un petate). Textura visual: la que se ve en una imagen plana pero no se siente al tocarla (una foto de una piedra).","Palabras para describir texturas: rugosa, áspera, lisa, suave, esponjosa, dura, blanda, ondulada, granulosa, pegajosa.","Las texturas pueden ser naturales (hojas, piedras, cortezas) o artificiales, hechas por las personas (tejidos, petates, ladrillos, telas).","Frotado: se pone una hoja delgada sobre una superficie con relieve y se frota con crayón acostado; la textura aparece dibujada."],"media":{"id":"s05-art-1-texturas","kind":"image","title":"Un mosaico de texturas de Guatemala","aspect":"4:3","alt":"Nueve fotografías cercanas en cuadrícula: corteza de pino, petate de palma, tejido de güipil, piedra de río, hoja de maíz, arena volcánica, ladrillo, algodón y tapa de olla de barro.","brief":"Mosaico fotográfico 3×3, fotos macro con luz lateral que resalte el relieve: corteza de pino, petate de palma o tule, tejido de güipil (detalle de hilos, sin identificar comunidad concreta), piedra de río lisa, hoja de milpa seca, arena volcánica negra, ladrillo, mota de algodón, barro cocido. Cada foto con una etiqueta pequeña con su nombre. Sin personas ni marcas. Dimensiones: 1200x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["art"],"cnb":["art:3.2.1"],"ambito":"conocer","prompt":"Compara textura real y textura visual antes de crear un registro.","type":"explain","props":{"icon":"Hand","body":"La textura táctil se percibe al tocar una superficie; la visual se representa con líneas, puntos y contraste. Un frotado transfiere al papel el relieve de una superficie segura."},"id":"s05-art-1-1"},{"fase":"construir","areas":["art"],"cnb":["art:3.2.1"],"ambito":"conocer","prompt":"Observa el mosaico. Si pasaras la mano por cada foto **impresa en papel**, ¿qué sentirías?","explain":"En el papel todo se siente **liso**: la foto solo **muestra** la textura. A eso le llamamos **textura visual**. La textura que se siente de verdad al tocar es **táctil**.","type":"choice","props":{"options":[{"id":"a","text":"La aspereza de la corteza y la suavidad del algodón","icon":"Hand","feedback":"Eso lo sentirías tocando los objetos reales. La foto impresa es plana."},{"id":"b","text":"Todas se sentirían lisas, como el papel","icon":"FileText"},{"id":"c","text":"Solo la arena se sentiría rugosa","icon":"Mountain","feedback":"Aunque la arena se vea rugosa, en la foto impresa no hay granos reales."}],"correct":["b"]},"id":"s05-art-1-2"},{"fase":"construir","areas":["art"],"cnb":["art:3.2.1"],"ambito":"conocer","title":"¿Qué es la textura?","prompt":"La **textura** es **cómo se siente, o cómo parece que se siente, una superficie**. Es uno de los elementos básicos del arte, junto con la línea, la forma y el color. Toca cada tarjeta.","type":"explain","props":{"icon":"Hand","body":"Los artistas usan la textura para que sus obras despierten el sentido del **tacto**, aunque solo las veamos.","reveal":[{"icon":"Hand","front":"Textura táctil","back":"Se percibe **al tocar**: la corteza de un árbol, un petate, un tejido, la arena. Tiene **relieve** real."},{"icon":"Eye","front":"Textura visual","back":"Se **ve** pero no se siente: una foto o un dibujo de madera, de piedra o de pelo. Al tocarla, el papel es liso."},{"icon":"Leaf","front":"Natural","back":"Creada por la naturaleza: hojas, piedras, cortezas, plumas, conchas, tierra."},{"icon":"Home","front":"Artificial","back":"Hecha por las personas: tejidos, petates, canastos, ladrillos, telas, cerámica."}]},"id":"s05-art-1-3"},{"fase":"construir","areas":["art"],"cnb":["art:3.2.1"],"ambito":"conocer","prompt":"Aprende palabras para **describir texturas**. Lee el frente, piensa en un ejemplo y voltea la tarjeta.","type":"flashcards","props":{"cards":[{"front":"Rugosa","back":"Con arrugas o bultos irregulares. Ej.: corteza de pino, piel del güisquil.","icon":"Mountain"},{"front":"Lisa","back":"Sin bultos ni asperezas. Ej.: piedra de río, vidrio, hoja de plátano.","icon":"Circle"},{"front":"Granulosa","back":"Formada por granitos. Ej.: arena volcánica, azúcar, tierra seca.","icon":"Sparkles"},{"front":"Ondulada","back":"Con ondas que suben y bajan. Ej.: lámina, cartón corrugado.","icon":"Waves"}]},"id":"s05-art-1-4"},{"fase":"construir","areas":["art"],"cnb":["art:3.2.1"],"ambito":"hacer","title":"Ejemplo resuelto: capturar una textura con frotado","prompt":"El **frotado** es una técnica para \\"copiar\\" texturas táctiles en papel. Mira cómo lo hace Marta.","media":{"id":"s05-art-1-frotado","kind":"video","title":"La técnica del frotado","aspect":"9:16","duration":40,"alt":"Manos de niña colocan una hoja de papel sobre una hoja de árbol y la frotan con un crayón acostado; poco a poco aparecen las nervaduras.","brief":"Video vertical de 40 s, plano cenital. (1) Una hoja de árbol con nervaduras marcadas sobre la mesa, con la cara rugosa hacia arriba. (2) Encima, una hoja de papel bond delgado sujetada con una mano. (3) Un crayón sin envoltura, acostado, frota con suavidad en una sola dirección: aparecen las nervaduras. (4) Repite sobre una moneda, un petate y una corteza, con otros colores. Rótulos: \\"crayón acostado\\", \\"suave y en una dirección\\". Sin marcas visibles. Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"type":"worked-example","props":{"icon":"Brush","problem":"Marta quiere llevar a su cuaderno la textura de una **hoja de aguacate** y de un **petate**.","steps":[{"text":"Pone la hoja de aguacate sobre la mesa con las **nervaduras hacia arriba** (el lado con más relieve)."},{"text":"Coloca encima una **hoja de papel delgado** y la sujeta firme con una mano para que no se mueva.","why":"Si el papel se mueve, la textura sale doble y borrosa."},{"text":"Quita el papel de envoltura al crayón y lo frota **acostado**, con suavidad y **en una sola dirección**.","why":"Con el crayón acostado solo se pinta lo que sobresale: así aparece el relieve."},{"text":"Repite en otra parte de la hoja sobre el petate, con otro color, y rotula cada muestra."}],"answer":"Con el **frotado**, la textura **táctil** de la hoja y del petate queda convertida en una textura **visual** en su cuaderno.","tip":"Busca superficies con relieve marcado: cortezas, monedas, tejidos, rejillas, suelas de zapato."},"id":"s05-art-1-5"},{"fase":"construir","areas":["art"],"cnb":["art:3.2.1"],"ambito":"conocer","prompt":"Clasifica cada ejemplo: ¿textura **táctil** o **visual**?","hint":"Pregúntate: si lo toco, ¿siento el relieve o solo papel o pantalla lisa?","explain":"Los objetos reales tienen textura táctil. Las fotos, dibujos y frotados muestran texturas visuales.","type":"sort","props":{"buckets":[{"id":"t","label":"Táctil","icon":"Hand","color":"var(--area-art)"},{"id":"v","label":"Visual","icon":"Eye","color":"var(--area-l1)"}],"items":[{"id":"x1","text":"Un canasto de palma","bucket":"t"},{"id":"x2","text":"La foto de un volcán en un libro","bucket":"v"},{"id":"x3","text":"El frotado de una moneda en mi cuaderno","bucket":"v","feedback":"La moneda es táctil, pero el frotado en el papel es una textura visual."},{"id":"x4","text":"Un güipil tejido","bucket":"t"}]},"id":"s05-art-1-6"},{"fase":"aplicar","areas":["art"],"cnb":["art:3.2.1"],"ambito":"conocer","prompt":"Une cada elemento de tu entorno con la palabra que mejor describe su textura.","explain":"Describir con precisión es el primer paso para usar las texturas en una obra.","type":"match","props":{"leftTitle":"Elemento","rightTitle":"Textura","pairs":[{"id":"p","left":"Piedra de río","leftIcon":"Circle","right":"Lisa"},{"id":"a","left":"Arena volcánica","leftIcon":"Mountain","right":"Granulosa"},{"id":"c","left":"Corteza de pino","leftIcon":"TreePine","right":"Rugosa"}]},"id":"s05-art-1-7"},{"fase":"aplicar","areas":["art"],"cnb":["art:3.2.1"],"ambito":"hacer","prompt":"Pedro hizo un frotado sobre una corteza, pero le salió una mancha pareja sin ninguna textura. ¿Qué error pudo cometer?","explain":"Si se frota con la **punta** o apretando mucho, se pinta todo por igual. El crayón **acostado** y con presión suave solo marca lo que sobresale.","type":"choice","props":{"options":[{"id":"a","text":"Frotó con la punta del crayón y apretando muy fuerte"},{"id":"b","text":"Usó un papel delgado","feedback":"El papel delgado es lo correcto: deja sentir el relieve."},{"id":"c","text":"Eligió una corteza con mucho relieve","feedback":"Mientras más relieve, mejor sale el frotado."}],"correct":["a"]},"id":"s05-art-1-8"},{"fase":"aplicar","areas":["art"],"cnb":["art:3.2.1"],"ambito":"hacer","prompt":"Realiza en clase un ensayo breve con **tres superficies preparadas y seguras**: cartón corrugado, un retazo limpio de petate y una placa de hojas con nervaduras.","type":"project","props":{"goal":"Producir tres frotados y comparar la textura visual que registra cada superficie.","steps":[{"title":"Prepara la hoja","detail":"Divide una hoja delgada en tres espacios y coloca el primero sobre una superficie preparada."},{"title":"Haz tres frotados","detail":"Sujeta el papel y pasa el crayón acostado con presión suave una vez sobre cada superficie."},{"title":"Compara y rotula","detail":"Debajo de los tres frotados escribe una comparación concisa, por ejemplo: “El corrugado deja líneas; el petate, una trama; la placa de hojas, nervaduras”."}],"evidence":"Una hoja con tres frotados y un rótulo comparativo.","rubric":["Los tres registros muestran diferencias visibles","El rótulo compara las huellas con vocabulario preciso"]},"id":"s05-art-1-9"},{"fase":"comprobar","areas":["art"],"cnb":["art:3.2.1"],"prompt":"Un dibujo muy realista de la piel de un lagarto, en una hoja de papel, tiene textura…","type":"choice","props":{"options":[{"id":"a","text":"Táctil, porque se ve rugosa"},{"id":"b","text":"Visual, porque se ve rugosa pero al tocarla es lisa"},{"id":"c","text":"No tiene textura"}],"correct":["b"]},"id":"s05-art-1-10"},{"fase":"comprobar","areas":["art"],"cnb":["art:3.2.1"],"prompt":"Clasifica cada textura según su origen.","type":"sort","props":{"buckets":[{"id":"n","label":"Natural","icon":"Leaf","color":"var(--c-ok)"},{"id":"a","label":"Artificial","icon":"Home","color":"var(--area-art)"}],"items":[{"id":"y1","text":"Concha de playa","bucket":"n"},{"id":"y2","text":"Petate","bucket":"a"},{"id":"y3","text":"Hoja de milpa","bucket":"n"},{"id":"y4","text":"Ladrillo","bucket":"a"}]},"id":"s05-art-1-11"}],"kind":"materia","area":"art","day":1}},{"missionId":"s05","version":"cnb-sexto-0abcdb60a0edcc57","lesson":{"id":"s05-cnt-1","title":"Tipos de drogas y sus efectos","icon":"Brain","minutes":14,"gancho":"¿Por que una sustancia legal tambien puede alterar el sistema nervioso?","objetivos":["Diferenciar tipos de drogas segun sus efectos en el sistema nervioso"],"resumen":["Una droga altera funciones del organismo y puede causar dependencia.","Por su efecto, puede clasificarse como depresora, estimulante o perturbadora.","La clasificacion por efecto no indica que una sustancia sea segura ni coincide siempre con su situacion legal."],"media":{"id":"s05-cnt-1-defensas","kind":"diagram","title":"Tres efectos en el sistema nervioso","aspect":"16:9","alt":"Tres paneles muestran actividad mas lenta, mas rapida y percepcion alterada, sin representar consumo.","brief":"Diagrama educativo 1600x900 con tres paneles rotulados DEPRESORAS, ESTIMULANTES y PERTURBADORAS. Usar un cerebro esquematico y flechas de ritmo; incluir ejemplos escritos y la advertencia \\"legal no significa inocua\\". No mostrar personas consumiendo, marcas ni envases reconocibles. Texto grande, contraste alto y patrones ademas de color."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:4.1.1"],"prompt":"Diferencia los tipos de drogas por el efecto que producen, no por si son legales o ilegales.","type":"explain","props":{"icon":"Brain","body":"Una **droga** altera funciones del organismo. Por su efecto nervioso se clasifica como **depresora, estimulante o perturbadora**."},"id":"s05-cnt-1-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:4.1.1"],"title":"Tres tipos por efecto","prompt":"Clasifica sustancias por su efecto principal en el sistema nervioso.","type":"explain","props":{"icon":"ListTree","body":"Las **depresoras** vuelven mas lenta la actividad; las **estimulantes** la aceleran; las **perturbadoras o alucinogenas** alteran percepcion y pensamiento. Alcohol: depresora; cafeina y nicotina: estimulantes; algunos alucinogenos: perturbadores. Ningun tipo es inocuo por ser legal."},"id":"s05-cnt-1-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:4.1.1"],"title":"Modelo: clasificar por evidencia","prompt":"Observa como diferenciar depresora, estimulante y perturbadora por el efecto descrito.","type":"worked-example","props":{"icon":"SearchCheck","problem":"Tres fichas dicen: A enlentece reflejos; B aumenta alerta; C altera la percepcion.","steps":[{"text":"A corresponde a una droga depresora."},{"text":"B corresponde a una droga estimulante."},{"text":"C corresponde a una droga perturbadora o alucinogena."}],"answer":"El efecto descrito, no la legalidad, determina esta clasificacion."},"id":"s05-cnt-1-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:4.1.1"],"prompt":"Clasifica cada droga o sustancia como depresora, estimulante o perturbadora segun el efecto indicado.","hint":"Lento = depresora; rapido o alerta = estimulante; percepcion alterada = perturbadora.","explain":"La clasificacion describe el efecto principal y no afirma que una sustancia sea segura.","type":"sort","props":{"buckets":[{"id":"d","label":"Depresora","icon":"Gauge","color":"var(--area-cnt)"},{"id":"e","label":"Estimulante","icon":"Zap","color":"var(--c-maiz-strong)"},{"id":"p","label":"Perturbadora","icon":"Waves","color":"var(--area-art)"}],"items":[{"id":"a","text":"Alcohol: enlentece reflejos","bucket":"d"},{"id":"b","text":"Cafeina: aumenta alerta","bucket":"e"},{"id":"c","text":"Alucinogeno: altera percepcion","bucket":"p"}]},"id":"s05-cnt-1-4"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:4.1.1"],"prompt":"Caso nuevo: una ficha describe una droga que acelera la actividad nerviosa. Al diferenciar depresoras, estimulantes y perturbadoras, ¿que tipo corresponde?","type":"choice","props":{"options":[{"id":"a","text":"Estimulante"},{"id":"b","text":"Depresora"},{"id":"c","text":"Perturbadora"}],"correct":["a"]},"id":"s05-cnt-1-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:4.1.1"],"prompt":"Diferencia los tres tipos de drogas: depresora, estimulante y perturbadora. Describe el efecto que permite clasificar cada una.","type":"short-answer","props":{"minWords":18,"placeholder":"Depresora... Estimulante... Perturbadora...","model":"Una sustancia depresora enlentece funciones; una estimulante las acelera; una perturbadora altera la percepcion. Ninguna clasificacion significa que su consumo sea seguro.","rubric":["Nombre los tres tipos","Use el efecto para diferenciarlos","No confundi legalidad con seguridad"]},"id":"s05-cnt-1-6"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:4.1.1"],"prompt":"Al clasificar drogas como depresoras, estimulantes y perturbadoras, ¿que criterio las diferencia?","type":"choice","props":{"options":[{"id":"a","text":"Su efecto principal en el sistema nervioso"},{"id":"b","text":"El color del envase"},{"id":"c","text":"Que todas producen el mismo efecto"}],"correct":["a"]},"id":"s05-cnt-1-7"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:4.1.1"],"prompt":"Diferencia drogas depresoras, estimulantes y perturbadoras por sus efectos.","type":"true-false","props":{"statements":[{"text":"Una depresora puede enlentecer reflejos.","answer":true},{"text":"Una estimulante y una perturbadora siempre producen el mismo efecto.","answer":false},{"text":"Una perturbadora puede alterar la percepcion.","answer":true}]},"id":"s05-cnt-1-8"},{"fase":"reflexionar","areas":["cnt"],"cnb":["cnt:4.1.1"],"prompt":"Revisa como clasificaste las sustancias.","type":"reflection","props":{"statements":["Use evidencia del efecto","Diferencie los tres tipos","No trate legal como sinonimo de seguro"],"commitments":["Pedire informacion confiable a una persona adulta responsable"]},"id":"s05-cnt-1-9"}],"kind":"materia","area":"cnt","day":1}},{"missionId":"s05","version":"cnb-sexto-1d91662d1fb916c4","lesson":{"id":"s05-ccss-1","title":"Tecnologia y aportes de Egipto y Mesopotamia","icon":"Landmark","minutes":15,"gancho":"¿Como ayudaron los rios, el riego y la organizacion a sostener ciudades antiguas?","objetivos":["Organizar el desarrollo y los aportes de Egipto y Mesopotamia en un esquema"],"resumen":["Egipto se desarrollo junto al Nilo y Mesopotamia entre el Tigris y el Eufrates.","Canales, diques, arado y calendarios apoyaron la agricultura y requirieron organizacion.","Sus aportes pueden organizarse como politicos, economicos y culturales sin suponer que surgieron de una sola persona."],"media":{"id":"s05-ccss-1-kit","kind":"diagram","title":"Dos civilizaciones fluviales","aspect":"16:9","alt":"Mapa esquematico ubica Egipto y Mesopotamia junto a una matriz de tecnologia agricola y aportes politicos, economicos y culturales.","brief":"Diagrama historico 1600x900. Ubicar Nilo, Tigris y Eufrates sin fronteras modernas. Incluir canales, diques y arado como desarrollo tecnologico/agricola. Agregar una matriz vacia con columnas POLITICO, ECONOMICO y CULTURAL para organizar aportes. Texto grande, alto contraste, flechas con etiquetas y nota \\"sintesis didactica; procesos desarrollados durante siglos\\"."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:6.3.1","ccss:6.3.5"],"prompt":"Relaciona el desarrollo tecnologico y agricola de Egipto y Mesopotamia con aportes politicos, economicos y culturales organizados en un esquema.","type":"explain","props":{"icon":"Map","body":"**Egipto**, junto al Nilo, y **Mesopotamia**, entre Tigris y Eufrates, desarrollaron riego y agricultura. Su organizacion produjo aportes **politicos, economicos y culturales** que pueden esquematizarse."},"id":"s05-ccss-1-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:6.3.1","ccss:6.3.5"],"title":"Agua, agricultura y organizacion","prompt":"Compara tecnologia agricola y organiza aportes de Egipto y Mesopotamia en dimensiones politicas, economicas y culturales.","type":"explain","props":{"icon":"TableProperties","body":"Ambas sociedades usaron **canales, diques, arados y calendarios** para apoyar agricultura y almacenamiento. **Politico:** reyes, faraones, leyes y administracion. **Economico:** riego, excedentes, oficios y comercio. **Cultural:** escritura, matematicas, calendarios y arquitectura."},"id":"s05-ccss-1-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:6.3.1","ccss:6.3.5"],"title":"Modelo: esquema comparativo","prompt":"Observa como organizar tecnologia agricola y aportes politicos, economicos y culturales de Egipto y Mesopotamia.","type":"worked-example","props":{"icon":"Workflow","problem":"¿Donde colocar cada evidencia?","steps":[{"text":"Egipto y Mesopotamia: canales y diques → desarrollo tecnologico y agricola."},{"text":"Administracion de obras y leyes → aporte politico."},{"text":"Excedentes, oficios y comercio → aporte economico."},{"text":"Jeroglificos, cuneiforme, calendarios y arquitectura → aporte cultural."}],"answer":"El esquema relaciona tecnologia agricola con organizacion y clasifica aportes sin mezclar dimensiones."},"id":"s05-ccss-1-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:6.3.1","ccss:6.3.5"],"prompt":"Guia: organiza el desarrollo agricola de Egipto y Mesopotamia y sus aportes politicos, economicos y culturales.","hint":"Pregunta si la evidencia trata poder y leyes, produccion e intercambio, o conocimientos y expresiones.","explain":"Canales y arados apoyaron agricultura; la administracion, los excedentes y la escritura muestran dimensiones distintas.","type":"sort","props":{"buckets":[{"id":"p","label":"Politico","icon":"Scale","color":"var(--area-ccss)"},{"id":"e","label":"Economico","icon":"Store","color":"var(--c-maiz-strong)"},{"id":"c","label":"Cultural","icon":"BookOpen","color":"var(--area-l1)"}],"items":[{"id":"a","text":"Administracion de canales y leyes","bucket":"p"},{"id":"b","text":"Excedentes agricolas y comercio","bucket":"e"},{"id":"c","text":"Escritura cuneiforme y jeroglifica","bucket":"c"}]},"id":"s05-ccss-1-4"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:6.3.1","ccss:6.3.5"],"prompt":"¿Que esquema relaciona tecnologia y agricultura de Egipto y Mesopotamia con aportes politicos, economicos y culturales?","type":"choice","props":{"options":[{"id":"a","text":"Canales y arados-agricultura; administracion-politico; excedentes-economico; escrituras-cultural"},{"id":"b","text":"Pirámide-politico; todos los demas aportes-cultural"},{"id":"c","text":"Los rios realizaron por si solos toda la organizacion"}],"correct":["a"]},"id":"s05-ccss-1-5"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:6.3.1","ccss:6.3.5"],"prompt":"Organiza un esquema textual: desarrollo tecnologico/agricola de Egipto y Mesopotamia y un aporte politico, economico y cultural de cada civilizacion.","type":"short-answer","props":{"minWords":28,"placeholder":"Egipto → agricultura... Politico... Mesopotamia →...","model":"Egipto y Mesopotamia desarrollaron sistemas de riego para apoyar la agricultura. En lo politico organizaron administraciones; en lo economico produjeron excedentes; y en lo cultural crearon escrituras, calendarios y conocimientos matematicos.","rubric":["Inclui ambas civilizaciones","Relacione tecnologia y agricultura","Organice aportes en tres dimensiones"]},"id":"s05-ccss-1-6"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:6.3.1","ccss:6.3.5"],"prompt":"En un esquema de Egipto y Mesopotamia, ¿como se organizan tecnologia agricola y aportes politicos, economicos y culturales?","type":"choice","props":{"options":[{"id":"a","text":"Riego y arado apoyan agricultura; administracion es politica, excedentes son economicos y escritura es cultural"},{"id":"b","text":"Toda evidencia pertenece solo a cultura"},{"id":"c","text":"Agricultura y tecnologia no se relacionaron con organizacion"}],"correct":["a"]},"id":"s05-ccss-1-7"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:6.3.1","ccss:6.3.5"],"prompt":"Comprueba el esquema de tecnologia agricola y aportes politicos, economicos y culturales de Egipto y Mesopotamia.","type":"true-false","props":{"statements":[{"text":"Canales y diques apoyaron la agricultura y exigieron organizacion.","answer":true},{"text":"Excedentes y comercio son aportes economicos.","answer":true},{"text":"Escritura y calendarios fueron tecnologias agricolas sin dimension cultural.","answer":false}]},"id":"s05-ccss-1-8"},{"fase":"reflexionar","areas":["ccss"],"cnb":["ccss:6.3.1","ccss:6.3.5"],"prompt":"Revisa las relaciones de tu esquema.","type":"reflection","props":{"statements":["Diferencie ambas civilizaciones","Relacione agricultura y tecnologia","Clasifique aportes en tres dimensiones"],"commitments":["Evitare atribuir procesos largos a una sola causa"]},"id":"s05-ccss-1-9"}],"kind":"materia","area":"ccss","day":1}},{"missionId":"s05","version":"cnb-sexto-1e2ee3c7ee87f0e7","lesson":{"id":"s05-cnt-2","title":"Tiempo libre saludable y libre de drogas","icon":"Activity","minutes":14,"gancho":"¿Como puede un plan de tiempo libre reunir movimiento, diversion y convivencia?","objetivos":["Ilustrar practicas saludables de tiempo libre libres del consumo de drogas"],"resumen":["Deportes, juegos, actividades sociales y recreacion pueden formar parte de una vida saludable.","Una practica protectora es voluntaria, segura, inclusiva y libre del consumo de drogas.","Tener opciones y apoyo no elimina todos los riesgos, pero fortalece decisiones de cuidado."],"media":{"id":"s05-cnt-2-cerebro","kind":"image","title":"Cuatro formas de tiempo libre saludable","aspect":"16:9","alt":"Estudiantes practican un deporte, un juego de mesa, una actividad social y una actividad recreativa artistica.","brief":"Ilustracion escolar 1600x900 dividida en cuatro escenas: deporte adaptado, juego cooperativo, conversacion social respetuosa y recreacion artistica. Mostrar diversidad corporal y participacion voluntaria. Incluir el rotulo \\"actividades seguras y libres del consumo de drogas\\". Sin marcas, sustancias ni mensajes que culpabilicen. Alto contraste y texto legible."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:4.2.1"],"prompt":"Ilustra como deporte, juego, actividad social y recreacion pueden apoyar practicas saludables libres del consumo de drogas.","type":"explain","props":{"icon":"HeartPulse","body":"Un plan saludable puede combinar **deporte, juego, actividad social y recreacion**, con seguridad, inclusion, eleccion voluntaria y **sin consumo de drogas**."},"id":"s05-cnt-2-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:4.2.1"],"title":"Cuatro opciones protectoras","prompt":"Usa e ilustra deporte, juego, actividad social y recreacion en un plan libre de drogas.","type":"explain","props":{"icon":"CalendarRange","body":"**Deporte:** movimiento con reglas adaptadas. **Juego:** reto cooperativo. **Actividad social:** convivencia con apoyo. **Recreacion:** arte, lectura, musica o paseo seguro. Las cuatro se realizan sin consumo de drogas."},"id":"s05-cnt-2-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:4.2.1"],"title":"Modelo: una tarde con opciones","prompt":"Observa como ilustrar las cuatro practicas saludables en un plan libre de drogas.","type":"worked-example","props":{"icon":"PanelsTopLeft","problem":"Un centro juvenil prepara cuatro estaciones.","steps":[{"text":"Deporte: pases suaves con pelota."},{"text":"Juego: rompecabezas cooperativo."},{"text":"Actividad social: circulo de conversacion."},{"text":"Recreacion: dibujo o lectura."},{"text":"Acuerdo: participacion voluntaria, segura y sin consumo de drogas."}],"answer":"El plan ofrece cuatro maneras concretas de cuidar el tiempo libre."},"id":"s05-cnt-2-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:4.2.1"],"prompt":"Relaciona cada practica saludable libre de drogas con deporte, juego, actividad social o recreacion.","hint":"Pregunta si predomina ejercicio, reglas ludicas, convivencia o disfrute creativo.","explain":"Las categorias pueden relacionarse, pero el ejemplo destaca una funcion principal.","type":"match","props":{"pairs":[{"id":"a","left":"Caminata con ritmo adaptable","right":"Deporte"},{"id":"b","left":"Memoria cooperativa","right":"Juego"},{"id":"c","left":"Conversatorio entre amistades","right":"Actividad social"},{"id":"d","left":"Taller breve de dibujo","right":"Recreacion"}]},"id":"s05-cnt-2-4"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:4.2.1"],"prompt":"¿Que plan ilustra deporte, juego, actividad social y recreacion como practicas saludables libres del consumo de drogas?","type":"choice","props":{"options":[{"id":"a","text":"Caminata adaptada, loteria cooperativa, conversacion y dibujo, con acuerdo de seguridad y sin consumo"},{"id":"b","text":"Una sola competencia obligatoria sin descansos"},{"id":"c","text":"Una reunion que ofrece sustancias para integrarse"}],"correct":["a"]},"id":"s05-cnt-2-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:4.2.1"],"prompt":"Ilustra con palabras un plan breve que use deporte, juego, actividad social y recreacion como practicas saludables libres de drogas.","type":"short-answer","props":{"minWords":22,"placeholder":"Deporte... Juego... Actividad social... Recreacion...","model":"Deporte: caminata acompanada. Juego: domino. Actividad social: charla. Recreacion: dibujo. Cada opcion es voluntaria, segura, accesible y se realiza sin consumo de sustancias.","rubric":["Inclui las cuatro practicas","Indique seguridad e inclusion","Declare que es libre del consumo de drogas"]},"id":"s05-cnt-2-6"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:4.2.1"],"prompt":"Un plan combina deporte, juego, actividad social y recreacion. ¿Que condicion lo presenta como practica saludable libre de drogas?","type":"choice","props":{"options":[{"id":"a","text":"Es seguro, inclusivo, voluntario y no incluye consumo"},{"id":"b","text":"Obliga a todas las personas a competir"},{"id":"c","text":"Usa una sustancia para aumentar energia"}],"correct":["a"]},"id":"s05-cnt-2-7"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:4.2.1"],"prompt":"Evalua el uso de deporte, juego, actividad social y recreacion como practicas saludables sin consumo de drogas.","type":"true-false","props":{"statements":[{"text":"Las cuatro practicas pueden adaptarse a intereses y capacidades.","answer":true},{"text":"Una actividad debe incluir consumo para ser social.","answer":false},{"text":"Ofrecer opciones seguras puede apoyar decisiones de cuidado.","answer":true}]},"id":"s05-cnt-2-8"},{"fase":"reflexionar","areas":["cnt"],"cnb":["cnt:4.2.1"],"prompt":"Revisa la variedad y seguridad de tu plan.","type":"reflection","props":{"statements":["Inclui movimiento y convivencia","Respete la participacion voluntaria","Mantuve el plan libre de drogas"],"commitments":["Propondre una opcion inclusiva para el recreo"]},"id":"s05-cnt-2-9"}],"kind":"materia","area":"cnt","day":3}},{"missionId":"s05","version":"cnb-sexto-b5ab61c2a41928f7","lesson":{"id":"s05-ccss-2","title":"Factores de los viajes europeos","icon":"Compass","minutes":14,"gancho":"¿Por que los viajes europeos por el Atlantico aumentaron durante los siglos XV y XVI?","objetivos":["Explicar factores combinados que favorecieron la llegada europea a America y otros pueblos"],"resumen":["El Renacimiento estimulo estudio y recuperacion de conocimientos; la imprenta amplio la circulacion de informacion.","La expansion comercial y maritima impulso la busqueda de rutas y recursos.","Brujula, astrolabio, cartografia y carabelas facilitaron navegacion; ningun factor explica por si solo la llegada ni sus consecuencias para otros pueblos."],"media":{"id":"s05-ccss-2-cambio","kind":"diagram","title":"Factores conectados de los viajes","aspect":"16:9","alt":"Red causal conecta Renacimiento, imprenta, expansion comercial y tecnologia de navegacion con viajes europeos y llegada a pueblos de America.","brief":"Diagrama historico 1600x900 en forma de red. Cuatro nodos: RENACIMIENTO, IMPRENTA, EXPANSION MARITIMA Y COMERCIAL, y NAVEGACION (brujula, astrolabio, cartografia, carabela). Flechas convergen en VIAJES EUROPEOS y CONTACTO/LLEGADA A AMERICA Y OTROS PUEBLOS. Incluir nota \\"factores combinados; no justifica conquista ni violencia\\". Alto contraste, texto legible y sin imagen heroica de conquistadores."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:6.4.4"],"prompt":"Explica como Renacimiento, imprenta, expansion maritima y comercial, y tecnologia de navegacion favorecieron viajes y llegada europea a America y otros pueblos.","type":"explain","props":{"icon":"Compass","body":"La llegada europea no tuvo una sola causa. Se combinaron **Renacimiento, imprenta, expansion maritima y comercial**, y herramientas de **navegacion** como brujula, astrolabio, mapas y carabelas."},"id":"s05-ccss-2-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:6.4.4"],"title":"Una red de factores","prompt":"Relaciona ideas, informacion, comercio y navegacion con la llegada europea a America y otros pueblos.","type":"explain","props":{"icon":"Network","body":"El **Renacimiento** estimulo estudio; la **imprenta** difundio informacion; la expansion **comercial y maritima** motivo buscar rutas; la tecnologia de **navegacion** facilito travesias. Juntas favorecieron viajes europeos que llegaron a America y a otros pueblos, con contactos, conquistas y efectos desiguales."},"id":"s05-ccss-2-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:6.4.4"],"title":"Modelo: factores que se conectan","prompt":"Observa como explicar Renacimiento, imprenta, comercio y navegacion sin elegir una causa unica.","type":"worked-example","props":{"icon":"GitBranch","problem":"¿Como se construye una explicacion multifactorial de la llegada europea?","steps":[{"text":"Renacimiento → interes por estudiar el mundo."},{"text":"Imprenta → mayor circulacion de mapas y conocimientos."},{"text":"Expansion comercial y maritima → busqueda de rutas."},{"text":"Brujula, astrolabio, cartografia y carabelas → navegacion de larga distancia."},{"text":"Factores combinados → viajes y llegada a America y otros pueblos."}],"answer":"Ningun elemento explica por si solo el proceso."},"id":"s05-ccss-2-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:6.4.4"],"prompt":"Guia: relaciona Renacimiento, imprenta, expansion comercial/maritima y tecnologia de navegacion con los viajes y la llegada europea a America y otros pueblos.","hint":"Ideas, difusion, motivacion comercial y capacidad tecnica cumplen funciones distintas.","explain":"Los cuatro factores se complementaron; no conviertas uno en causa unica.","type":"match","props":{"pairs":[{"id":"a","left":"Renacimiento","right":"Estudio y recuperacion de conocimientos"},{"id":"b","left":"Imprenta","right":"Circulacion mas amplia de informacion"},{"id":"c","left":"Expansion comercial y maritima","right":"Busqueda de rutas y recursos"},{"id":"d","left":"Tecnologia de navegacion","right":"Facilito travesias largas"}]},"id":"s05-ccss-2-4"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:6.4.4"],"prompt":"¿Que explicacion combina Renacimiento, imprenta, expansion maritima/comercial y navegacion para explicar viajes y llegada europea a America y otros pueblos?","type":"choice","props":{"options":[{"id":"a","text":"Ideas y conocimientos circularon, crecieron intereses comerciales y nuevas tecnicas facilitaron travesias"},{"id":"b","text":"La brujula causo por si sola todos los viajes"},{"id":"c","text":"Los pueblos de America solicitaron la conquista europea"}],"correct":["a"]},"id":"s05-ccss-2-5"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:6.4.4"],"prompt":"Explica en una red breve como Renacimiento, imprenta, expansion maritima y comercial, y tecnologia de navegacion favorecieron la llegada europea a America y otros pueblos.","type":"short-answer","props":{"minWords":26,"placeholder":"Renacimiento... Imprenta... Comercio... Navegacion...","model":"El Renacimiento impulso nuevos estudios, la imprenta difundio informacion, el comercio motivo la busqueda de rutas y los avances de navegacion facilitaron viajes europeos hacia America y otros pueblos.","rubric":["Inclui los cuatro factores","Explique su relacion","Evite una causa unica o una justificacion de la conquista"]},"id":"s05-ccss-2-6"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:6.4.4"],"prompt":"Para explicar la llegada europea a America y otros pueblos, ¿que relacion integra Renacimiento, imprenta, expansion comercial/maritima y navegacion?","type":"choice","props":{"options":[{"id":"a","text":"Estudio + difusion de informacion + busqueda de rutas + tecnicas para travesias"},{"id":"b","text":"Una sola invencion produjo todo el proceso"},{"id":"c","text":"No hubo intereses comerciales"}],"correct":["a"]},"id":"s05-ccss-2-7"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:6.4.4"],"prompt":"Evalua los factores Renacimiento, imprenta, expansion maritima/comercial y navegacion en los viajes y la llegada europea a America y otros pueblos.","type":"true-false","props":{"statements":[{"text":"La imprenta pudo ampliar la circulacion de informacion.","answer":true},{"text":"La expansion comercial motivo buscar rutas.","answer":true},{"text":"El Renacimiento fue la unica causa de la llegada.","answer":false}]},"id":"s05-ccss-2-8"},{"fase":"reflexionar","areas":["ccss"],"cnb":["ccss:6.4.4"],"prompt":"Revisa tu explicacion de factores historicos.","type":"reflection","props":{"statements":["Inclui ideas, informacion, comercio y tecnologia","Relacione factores sin aislarlos","No presente la conquista como logro neutral"],"commitments":["Distinguire explicacion historica de justificacion"]},"id":"s05-ccss-2-9"}],"kind":"materia","area":"ccss","day":3}},{"missionId":"s05","version":"cnb-sexto-60f622e212e18766","lesson":{"id":"s05-pyd-1","title":"Herramientas y máquinas simples: usarlas bien y con seguridad","icon":"Wrench","minutes":15,"gancho":"Un costal de abono pesa mucho. ¿Cómo lo moverías hasta el huerto sin lastimarte la espalda?","objetivos":["Aplicar técnica y criterios preventivos al usar herramientas con máquinas simples"],"resumen":["Una herramienta es un objeto que ayuda a hacer un trabajo. Las máquinas simples (palanca, plano inclinado, cuña, rueda y eje, polea y tornillo) reducen la fuerza necesaria o cambian su dirección. Muchas culturas las usan desde hace siglos.","El rodillo manual redondeado es una rueda y eje de baja fuerza: permite presionar cierres y tiras reutilizables con presión controlada sobre una mesa estable.","Criterios preventivos: ANTES revisar su estado y usar equipo de protección (zapatos cerrados, guantes); DURANTE mantener distancia y el espacio despejado; DESPUÉS limpiarla, guardarla y reportar daños.","Para usar el rodillo: revisar mango, rueda y eje; mantener los dedos fuera de la trayectoria; detenerse si está flojo, dañado o trabado."],"media":{"id":"s05-pyd-1-maquinas-huerto","kind":"image","title":"Máquinas simples en el huerto escolar","aspect":"16:9","alt":"Mesa estable con un rodillo manual redondeado, una carretilla, una rampa, una polea, un azadón y un molino, cada objeto rotulado por su máquina simple.","brief":"Ilustración didáctica de herramientas y máquinas simples. En primer plano, estudiante usa un rodillo manual redondeado de goma sobre una mesa estable: etiqueta \\"rueda y eje\\", dedos fuera de la trayectoria y flecha de presión controlada. Al fondo: carretilla (palanca + rueda), tabla inclinada, polea de pozo, azadón apoyado y molino de mano. Recuadro de seguridad del rodillo: revisar mango, rueda y eje; detenerse si está flojo, dañado o trabado. Sin filos en uso ni marcas comerciales. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["pyd"],"cnb":["pyd:3.2.3"],"ambito":"conocer","prompt":"Relaciona cada herramienta con su función y sus cuidados.","type":"explain","props":{"icon":"Wrench","body":"Una herramienta adecuada facilita una tarea solo si está en buen estado y se usa con técnica segura. Antes se inspecciona; durante se mantiene el área despejada; después se limpia y guarda."},"id":"s05-pyd-1-1"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:3.2.3"],"ambito":"hacer","prompt":"Debes llevar un costal de abono de 25 libras desde la entrada hasta el huerto. ¿Qué harías?","explain":"La **carretilla** es una máquina simple: con ella el peso se reparte entre la rueda y tus brazos, y haces **mucha menos fuerza**. Hoy aprenderás cómo funcionan estas máquinas y cómo usarlas con seguridad.","type":"choice","props":{"options":[{"id":"a","text":"Usar una carretilla","icon":"Truck"},{"id":"b","text":"Cargarlo solo en la espalda doblándome","icon":"User","feedback":"Doblar la espalda con peso puede lastimarla. Es mejor usar una herramienta o pedir ayuda."},{"id":"c","text":"Arrastrarlo por el suelo","icon":"Route","feedback":"El costal se puede romper y cuesta más fuerza. Hay una forma más fácil."}],"correct":["a"]},"id":"s05-pyd-1-2"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:3.2.3"],"ambito":"conocer","title":"Las seis máquinas simples","prompt":"Una **máquina simple** es un invento sencillo que **reduce la fuerza** que hacemos o **cambia su dirección**. Hay seis. Toca cada una.","type":"explain","props":{"icon":"Wrench","body":"Muchos pueblos las usan desde hace siglos: son una **herencia tecnológica** de la humanidad.","reveal":[{"icon":"Scale","front":"Palanca","back":"Una barra que gira sobre un punto de apoyo. Ejemplos: **carretilla**, pinzas, **tijeras**, un palo para mover una piedra."},{"icon":"Triangle","front":"Plano inclinado","back":"Una **rampa**: subir por ella cuesta menos fuerza que levantar directo. Ejemplo: una tabla para subir costales al pick-up."},{"icon":"Pickaxe","front":"Cuña","back":"Un borde afilado que **separa o corta**. Ejemplos: el filo del **hacha**, del **machete** y del **azadón**."},{"icon":"RotateCw","front":"Rueda y eje","back":"Una rueda unida a un eje que gira. Ejemplos: la carreta, la manivela del molino y el **rodillo manual** que presiona cierres reutilizables."},{"icon":"Anchor","front":"Polea","back":"Una rueda con una cuerda que **cambia la dirección** de la fuerza: jalas hacia abajo y la cubeta sube. Ejemplo: el **pozo**."},{"icon":"Hammer","front":"Tornillo","back":"Un plano inclinado enrollado. Sujeta y aprieta con poca fuerza. Ejemplos: tornillos, tapas de frascos, la prensa."}]},"id":"s05-pyd-1-3"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:3.2.3"],"prompt":"Une cada herramienta con la **máquina simple** que tiene.","hint":"Piensa qué hace: ¿gira?, ¿corta?, ¿es una rampa?, ¿sube algo jalando una cuerda?","explain":"Reconocer la máquina simple te ayuda a entender cómo usar la herramienta con menos esfuerzo.","type":"match","props":{"leftTitle":"Herramienta","rightTitle":"Máquina simple","pairs":[{"id":"h1","left":"Pozo con cubeta y cuerda","leftIcon":"Droplet","right":"Polea"},{"id":"h2","left":"Filo del hacha","leftIcon":"Pickaxe","right":"Cuña"},{"id":"h3","left":"Tabla para subir costales","leftIcon":"Triangle","right":"Plano inclinado"},{"id":"h4","left":"Manivela del molino de maíz","leftIcon":"RotateCw","right":"Rueda y eje"},{"id":"h5","left":"Tijeras","leftIcon":"Scissors","right":"Palanca"}]},"id":"s05-pyd-1-4"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:3.2.3","pyd:3.2.4"],"ambito":"conocer","title":"Técnica del rodillo manual","prompt":"El rodillo manual de goma es una rueda y eje de baja fuerza. Toca cada regla antes de usarlo.","type":"explain","props":{"icon":"RotateCw","body":"El rodillo sirve para presionar tiras o cierres sobre una **mesa estable**, no para golpear ni jugar.","reveal":[{"icon":"Search","front":"Revisar","back":"Comprueba que el mango, la rueda y el eje estén firmes y giren sin trabarse."},{"icon":"PanelTop","front":"Superficie estable","back":"Coloca la pieza plana sobre una mesa estable y despejada."},{"icon":"Hand","front":"Dedos fuera","back":"Sujeta el mango y mantén los dedos fuera de la trayectoria del rodillo."},{"icon":"Gauge","front":"Presión controlada","back":"Haz una pasada lenta con presión controlada; no inclines ni aplastes la herramienta."},{"icon":"OctagonX","front":"Detenerse","back":"No uses el rodillo y reporta el daño si el mango está flojo o la rueda está dañada o trabada."}]},"id":"s05-pyd-1-5"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:3.2.4"],"ambito":"conocer","title":"Criterios preventivos: antes, durante y después","prompt":"**Prevenir** es actuar **antes** de que ocurra un accidente. Toca cada momento.","type":"explain","props":{"icon":"ShieldCheck","body":"Las herramientas con **filo** (machete, hacha, tijeras de podar) las usan **personas adultas**, o se usan solo con su **supervisión**.","reveal":[{"icon":"Search","front":"Antes","back":"**Revisa** que el mango no esté rajado ni flojo y que la rueda tenga aire. Ponte **zapatos cerrados** y **guantes**. Pide permiso y supervisión."},{"icon":"Users","front":"Durante","back":"Mantén **distancia** de otras personas (al menos dos brazos). Despeja el lugar. Al transportar, lleva filos o puntas hacia abajo y camina. **Nunca** apuntes una herramienta hacia alguien ni juegues con ella."},{"icon":"Archive","front":"Después","back":"**Limpia** la herramienta, guárdala en **su lugar** con el filo protegido y **reporta** si algo se dañó."}]},"id":"s05-pyd-1-6"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:3.2.3","pyd:3.2.4"],"ambito":"hacer","title":"Ejemplo resuelto: fijar una tira reutilizable","prompt":"Mira cómo Keyla usa el rodillo manual para fijar una tira con cierre removible.","type":"worked-example","props":{"icon":"RotateCw","problem":"Una tira táctil ya está alineada sobre su cierre de gancho y felpa. Keyla debe presionarla sin desplazarla.","steps":[{"text":"**Antes:** revisa mango, rueda y eje; el rodillo gira libremente."},{"text":"Coloca la base sobre una **mesa estable** y alinea la tira."},{"text":"Toma el mango y mantiene los **dedos fuera de la trayectoria**."},{"text":"Hace una pasada lenta con **presión controlada**.","why":"La rueda distribuye la presión sobre la tira."},{"text":"Comprueba que la tira quedó firme; limpia y guarda el rodillo."}],"answer":"La tira queda firme mediante una pasada controlada y una comprobación final segura.","tip":"Revisar → estabilizar → alejar dedos → rodar → comprobar y guardar."},"id":"s05-pyd-1-7"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:3.2.3","pyd:3.2.4"],"ambito":"hacer","prompt":"Ordena el uso seguro del **rodillo manual** para fijar una tira reutilizable.","explain":"Revisar → apoyar en superficie estable → mantener dedos fuera → aplicar presión controlada → comprobar y guardar.","type":"order","props":{"labels":{"start":"Primero","end":"Al final"},"items":[{"id":"z1","text":"Revisar mango, rueda y eje","icon":"Search"},{"id":"z2","text":"Apoyar la base en una mesa estable","icon":"PanelTop"},{"id":"z3","text":"Mantener los dedos fuera de la trayectoria","icon":"Hand"},{"id":"z4","text":"Hacer una pasada con presión controlada","icon":"Gauge"},{"id":"z5","text":"Comprobar la tira, limpiar y guardar","icon":"Archive"}]},"id":"s05-pyd-1-8"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:3.2.3","pyd:3.2.4"],"ambito":"hacer","prompt":"El rodillo manual se traba a mitad de la pasada. ¿Qué acción aplica el criterio preventivo?","explain":"Detente, no fuerces el eje y reporta el daño para usar un rodillo seguro.","type":"choice","props":{"options":[{"id":"a","text":"Detenerse y reportar que el eje está trabado"},{"id":"b","text":"Presionar con más fuerza","feedback":"Forzar una herramienta trabada puede dañarla o desplazar la pieza."},{"id":"c","text":"Poner los dedos frente a la rueda para destrabarla","feedback":"Los dedos siempre permanecen fuera de la trayectoria."}],"correct":["a"]},"id":"s05-pyd-1-9"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:3.2.4"],"prompt":"Antes de usar un rodillo manual, ¿qué criterio preventivo aplicas?","type":"choice","props":{"options":[{"id":"a","text":"Revisar que mango, rueda y eje estén firmes"},{"id":"b","text":"Usarlo aunque la rueda esté dañada"},{"id":"c","text":"Probarlo sobre una superficie inestable"}],"correct":["a"]},"id":"s05-pyd-1-10"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:3.2.3","pyd:3.2.4"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"La polea del pozo cambia la dirección de la fuerza: jalas hacia abajo y la cubeta sube.","answer":true},{"text":"El filo del machete es un ejemplo de cuña.","answer":true},{"text":"Para levantar algo pesado conviene doblar la espalda y dejar las piernas rectas.","answer":false,"why":"Se doblan las rodillas y se mantiene la espalda recta."},{"text":"Después de usar una herramienta basta con dejarla donde se terminó el trabajo.","answer":false,"why":"Hay que limpiarla, guardarla en su lugar y reportar daños."}]},"id":"s05-pyd-1-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["pyd"],"cnb":["pyd:3.2.3","pyd:3.2.4"],"type":"reflection","props":{"statements":["Reconozco las seis máquinas simples en herramientas cotidianas","Uso las herramientas con la técnica adecuada","Aplico criterios preventivos antes, durante y después"],"commitments":["Revisaré las herramientas antes de usarlas","Guardaré cada herramienta en su lugar después de usarla"]},"id":"s05-pyd-1-12"}],"kind":"materia","area":"pyd","day":3}},{"missionId":"s05","version":"cnb-sexto-777241588b2bb40a","lesson":{"id":"s05-ccss-3","title":"Causas y consecuencias de las guerras mundiales","icon":"History","minutes":15,"gancho":"¿Por que una guerra mundial no puede explicarse con una sola causa?","objetivos":["Relacionar causas y consecuencias de la Primera y Segunda Guerra Mundial"],"resumen":["La Primera Guerra Mundial surgio de varios factores: rivalidades imperialistas, militarismo, nacionalismos, alianzas y una crisis detonante.","La Segunda Guerra Mundial tuvo factores como consecuencias no resueltas de la primera guerra, expansionismo, fascismo y nazismo, crisis y fracaso de la seguridad colectiva.","Ambas produjeron millones de muertes, desplazamiento y destruccion; la segunda incluyo el Holocausto y fue seguida por la ONU y un nuevo orden internacional."],"media":{"id":"s05-ccss-3-mapa","kind":"diagram","title":"Dos guerras, multiples factores e impactos","aspect":"16:9","alt":"Linea de tiempo compara causas multiples y consecuencias humanas y politicas de la Primera y Segunda Guerra Mundial.","brief":"Linea de tiempo historica 1600x900 con dos tramos: PRIMERA GUERRA MUNDIAL (1914-1918) y SEGUNDA GUERRA MUNDIAL (1939-1945). En cada tramo mostrar varios factores y consecuencias humanas, economicas, territoriales y politicas. Incluir Holocausto como persecucion y asesinato sistematico de seis millones de judios y millones de otras victimas, con lenguaje sobrio y sin imagenes violentas. Texto grande, alto contraste y nota \\"sintesis; ninguna guerra se explica por una sola causa\\"."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:6.5.1"],"prompt":"Relaciona multiples factores y consecuencias de la Primera Guerra Mundial y la Segunda Guerra Mundial; ninguna se explica por una sola causa.","type":"explain","props":{"icon":"History","body":"En ambas guerras hubo **multiples factores**. Distinguir condiciones de largo plazo, decisiones, detonantes y consecuencias evita una explicacion de causa unica."},"id":"s05-ccss-3-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:6.5.1"],"title":"Dos redes historicas","prompt":"Compara causas y consecuencias de la Primera y Segunda Guerra Mundial mediante multiples factores.","type":"explain","props":{"icon":"Network","body":"**Primera Guerra Mundial:** imperialismo, militarismo, nacionalismos, alianzas y crisis de 1914; consecuencias: muertes, desplazamiento, destruccion y cambios territoriales. **Segunda Guerra Mundial:** tensiones no resueltas, crisis, expansionismo, fascismo y nazismo; consecuencias: muertes masivas, Holocausto, desplazamiento, destruccion, ONU y nuevo orden internacional. No se explica ninguna por una sola causa."},"id":"s05-ccss-3-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:6.5.1"],"title":"Modelo: factor, detonante y consecuencia","prompt":"Observa como relacionar multiples factores y consecuencias en la Primera y Segunda Guerra Mundial.","type":"worked-example","props":{"icon":"Workflow","problem":"¿Como evitar decir que un solo hecho causo todo?","steps":[{"text":"Primera: alianzas y militarismo ya creaban tension; el asesinato de Sarajevo fue un detonante, no la unica causa."},{"text":"Segunda: expansionismo nazi, fascismo, crisis y tensiones posteriores a 1918 se combinaron."},{"text":"Consecuencias comunes: muertes, desplazamiento y destruccion."},{"text":"Consecuencias especificas: cambios territoriales tras la primera; Holocausto y creacion de la ONU tras la segunda."}],"answer":"La relacion usa multiples factores, detonantes y consecuencias."},"id":"s05-ccss-3-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:6.5.1"],"prompt":"Guia: organiza multiples factores y consecuencias de la Primera y Segunda Guerra Mundial.","hint":"Distingue el proceso de 1914-1918 del de 1939-1945 y separa causa de consecuencia.","explain":"Un detonante acelera una crisis; no reemplaza los demas factores.","type":"sort","props":{"buckets":[{"id":"p","label":"Primera Guerra Mundial","icon":"Calendar","color":"var(--area-ccss)"},{"id":"s","label":"Segunda Guerra Mundial","icon":"CalendarDays","color":"var(--c-maiz-strong)"}],"items":[{"id":"a","text":"Sistema de alianzas y crisis de 1914","bucket":"p"},{"id":"b","text":"Expansionismo nazi e invasion de Polonia","bucket":"s"},{"id":"c","text":"Tratados y cambios territoriales posteriores a 1918","bucket":"p"},{"id":"d","text":"Holocausto y creacion posterior de la ONU","bucket":"s"}]},"id":"s05-ccss-3-4"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:6.5.1"],"prompt":"¿Que analisis relaciona multiples factores y consecuencias de la Primera Guerra Mundial y la Segunda Guerra Mundial sin afirmar una sola causa?","type":"choice","props":{"options":[{"id":"a","text":"La primera combino rivalidades, alianzas y militarismo; la segunda, tensiones no resueltas, expansionismo y fascismo; ambas causaron muerte, desplazamiento y destruccion"},{"id":"b","text":"Cada guerra tuvo exactamente una causa y ninguna consecuencia social"},{"id":"c","text":"Las dos guerras fueron el mismo conflicto sin diferencias"}],"correct":["a"]},"id":"s05-ccss-3-5"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:6.5.1"],"prompt":"Compara multiples factores y dos consecuencias de la Primera Guerra Mundial y la Segunda Guerra Mundial. Explica por que ninguna tuvo una sola causa.","type":"short-answer","props":{"minWords":30,"placeholder":"Primera: factores... consecuencias... Segunda...","model":"La Primera Guerra Mundial combino alianzas, rivalidades y militarismo. La Segunda combino expansionismo, fascismo y tensiones previas. Ambas causaron muerte y desplazamiento; ninguna se explica por una sola causa aislada.","rubric":["Inclui ambas guerras","Nombre multiples factores","Relacione consecuencias con cuidado historico"]},"id":"s05-ccss-3-6"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:6.5.1"],"prompt":"¿Que opcion compara multiples factores y consecuencias de la Primera Guerra Mundial y la Segunda Guerra Mundial, pues ninguna se explica por una sola causa?","type":"choice","props":{"options":[{"id":"a","text":"Alianzas y rivalidades influyeron en la primera; expansionismo y fascismo en la segunda; ambas dejaron muertes, desplazamiento y destruccion"},{"id":"b","text":"Sarajevo explica por si solo ambas guerras"},{"id":"c","text":"Las guerras no cambiaron fronteras ni sociedades"}],"correct":["a"]},"id":"s05-ccss-3-7"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:6.5.1"],"prompt":"Comprueba multiples factores y consecuencias de la Primera Guerra Mundial y la Segunda Guerra Mundial; ninguna se explica por una sola causa.","type":"true-false","props":{"statements":[{"text":"El asesinato de Sarajevo fue detonante dentro de tensiones previas.","answer":true},{"text":"Expansionismo, fascismo y tensiones no resueltas influyeron en la segunda guerra.","answer":true},{"text":"Las dos guerras tuvieron una sola causa y no produjeron desplazamientos.","answer":false}]},"id":"s05-ccss-3-8"},{"fase":"reflexionar","areas":["ccss"],"cnb":["ccss:6.5.1"],"prompt":"Revisa tu comparacion historica.","type":"reflection","props":{"statements":["Diferencie factor, detonante y consecuencia","Inclui ambas guerras","Evite una causa unica"],"commitments":["Usare lenguaje sobrio al tratar violencia historica"]},"id":"s05-ccss-3-9"}],"kind":"materia","area":"ccss","day":4}},{"missionId":"s05","version":"cnb-sexto-113b4b5c257d59a9","lesson":{"id":"s05-art-2","title":"Arte para leer con las manos: el mapa táctil","icon":"Map","minutes":15,"gancho":"Un caso ficticio propone un mapa de la escuela. ¿Cómo pueden el relieve, la textura y el contraste comunicar con claridad sin inventar una consulta?","objetivos":["Diseñar una clave táctil mediante tres texturas seguras y claramente contrastantes"],"resumen":["Las personas ciegas y con baja visión usan estrategias, formatos y apoyos diversos. Algunas personas ciegas pueden preferir información táctil; otras pueden elegir audio, texto digital u orientación personal.","Una clave táctil sencilla puede usar tres texturas no braille claramente distintas: EVA lisa, plástico corrugado y corcho rugoso.","Las muestras preparadas y reutilizables se fijan con cierre de gancho y felpa removible; llegan listas para comparar, ordenar y volver a guardar.","La clase usa símbolos táctiles que no son braille. No se debe imitar, inventar ni copiar braille sin transcripción profesional y revisión de una persona competente."],"media":{"id":"s05-art-2-mapa","kind":"image","title":"Muestrario táctil reutilizable","aspect":"4:3","alt":"Tres muestras grandes y separadas de EVA lisa, plástico corrugado y corcho rugoso, junto a una clave breve de alto contraste.","brief":"Mock durable para aula: tablero pequeño con tres muestras preparadas y reutilizables, grandes y separadas: EVA lisa, plástico corrugado y corcho rugoso. Cada muestra usa cierre de gancho y felpa removible con esquinas redondeadas. A la derecha, clave concisa con una muestra y un nombre grande por textura. Mostrar símbolos táctiles no braille y una bandeja rotulada; no imitar braille. Todas las piezas quedan firmes y listas para reutilizar. Dimensiones: 1200x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["art"],"cnb":["art:3.2.1"],"ambito":"conocer","prompt":"Compara cómo tres texturas preparadas pueden comunicar diferencias.","type":"explain","props":{"icon":"Map","body":"Una clave táctil asigna un significado estable a cada textura. El contraste visual puede apoyar a algunas personas con baja visión, mientras que cada persona elige los formatos y apoyos que le resultan útiles."},"id":"s05-art-2-1"},{"fase":"construir","areas":["art"],"cnb":["art:3.2.1"],"ambito":"hacer","prompt":"¿Qué par del muestrario se distingue con mayor claridad al tacto?","explain":"La EVA **lisa** y el plástico **corrugado** ofrecen un contraste claro y estable.","type":"choice","props":{"options":[{"id":"a","text":"EVA lisa y plástico corrugado","icon":"Contrast"},{"id":"b","text":"Dos piezas de EVA lisa","icon":"Layers","feedback":"Tienen la misma textura y no crean contraste táctil."},{"id":"c","text":"Dos piezas de plástico corrugado","icon":"Layers","feedback":"Repetir una textura no permite distinguir significados."}],"correct":["a"]},"id":"s05-art-2-2"},{"fase":"construir","areas":["art"],"cnb":["art:3.2.1"],"ambito":"conocer","title":"Tres texturas, tres cualidades","prompt":"Recorre cada muestra preparada con dos dedos y nombra su cualidad principal.","type":"explain","props":{"icon":"Hand","body":"El muestrario reutilizable limita la comparación a **tres texturas** claramente distintas.","reveal":[{"icon":"Waves","front":"EVA lisa","back":"La superficie es continua y sin canales."},{"icon":"Rows3","front":"Plástico corrugado","back":"Los canales paralelos producen una sensación acanalada."},{"icon":"Mountain","front":"Corcho rugoso","back":"Los granos firmes producen una superficie irregular."}]},"id":"s05-art-2-3"},{"fase":"construir","areas":["art"],"cnb":["art:3.2.1"],"ambito":"hacer","title":"Una clave breve y consistente","prompt":"Una clave comunica cuando cada textura conserva un solo significado.","type":"explain","props":{"icon":"ListChecks","body":"La clave concisa usa una muestra, un nombre grande y un significado por fila.","reveal":[{"icon":"Contrast","front":"Contraste","back":"Las tres texturas deben distinguirse sin depender solo del color."},{"icon":"List","front":"Consistencia","back":"Si el corcho significa oficina, conserva ese significado en todo el plano."},{"icon":"ShieldCheck","front":"Seguridad","back":"Las muestras tienen esquinas redondeadas y cierres removibles firmes."},{"icon":"Shapes","front":"No es braille","back":"Son texturas y símbolos táctiles no braille. No imites, inventes ni copies braille."}]},"id":"s05-art-2-4"},{"fase":"construir","areas":["art"],"cnb":["art:3.2.1"],"ambito":"hacer","title":"Ejemplo resuelto: una clave de tres filas","prompt":"Mira cómo se construye una clave táctil breve con el kit preparado.","type":"worked-example","props":{"icon":"Map","problem":"La clave debe distinguir aula, corredor y oficina mediante las tres muestras reutilizables.","steps":[{"text":"**Aula → EVA lisa**."},{"text":"**Corredor → plástico corrugado**.","why":"Los canales contrastan con la EVA lisa."},{"text":"**Oficina → corcho rugoso**.","why":"La superficie irregular se diferencia de las otras dos."},{"text":"Cada muestra se fija con **gancho y felpa removible** junto a su nombre."}],"answer":"Tres texturas contrastantes y una **clave concisa** de tres filas.","tip":"Recorre dos muestras seguidas para comprobar el contraste táctil."},"id":"s05-art-2-5"},{"fase":"construir","areas":["art"],"cnb":["art:3.2.1"],"ambito":"hacer","prompt":"Haz una discriminación táctil breve: clasifica cada descripción según la muestra preparada.","hint":"Compara los rasgos: sin canales, canales paralelos o granos irregulares.","explain":"La comparación táctil distingue EVA lisa, plástico corrugado y corcho rugoso.","type":"sort","props":{"buckets":[{"id":"lis","label":"EVA lisa","icon":"Waves","color":"var(--area-l1)"},{"id":"cor","label":"Plástico corrugado","icon":"Rows3","color":"var(--area-ef)"},{"id":"rug","label":"Corcho rugoso","icon":"Mountain","color":"var(--area-art)"}],"items":[{"id":"t1","text":"Superficie continua, sin canales","bucket":"lis"},{"id":"t2","text":"Canales paralelos y firmes","bucket":"cor"},{"id":"t3","text":"Granos irregulares que se sienten al recorrer","bucket":"rug"}]},"id":"s05-art-2-6"},{"fase":"aplicar","areas":["art"],"cnb":["art:3.2.1"],"ambito":"hacer","prompt":"Una clave ya usa EVA lisa para las aulas. ¿Qué muestra preparada conviene para un corredor vecino?","explain":"El plástico corrugado ofrece un contraste táctil claro frente a la EVA lisa.","type":"choice","props":{"options":[{"id":"a","text":"Otra pieza de EVA lisa","feedback":"Repetir la textura no distingue los espacios vecinos."},{"id":"b","text":"Plástico corrugado"},{"id":"c","text":"Una etiqueta impresa sin relieve","feedback":"El texto impreso no crea contraste táctil."}],"correct":["b"]},"id":"s05-art-2-7"},{"fase":"aplicar","areas":["art"],"cnb":["art:3.2.1"],"ambito":"hacer","prompt":"Arma una clave breve con el muestrario reutilizable.","type":"project","props":{"goal":"Organizar tres texturas claramente distintas en una clave concisa.","steps":[{"title":"Ordena","detail":"Coloca EVA lisa, plástico corrugado y corcho rugoso en tres filas separadas."},{"title":"Fija","detail":"Usa los cierres de gancho y felpa removibles ya instalados."},{"title":"Rotula","detail":"Asigna un significado y un nombre grande a cada muestra."}],"evidence":"Clave concisa de tres filas con cierres removibles.","rubric":["Usé exactamente tres texturas","Cada muestra tiene un significado","Las tres texturas se distinguen al tacto"]},"id":"s05-art-2-8"},{"fase":"comprobar","areas":["art"],"cnb":["art:3.2.1"],"prompt":"Comprueba la clave táctil de tres texturas.","type":"true-false","props":{"statements":[{"text":"La EVA lisa y el plástico corrugado ofrecen cualidades táctiles distintas.","answer":true},{"text":"Una textura puede cambiar de significado en cada parte del mismo plano.","answer":false,"why":"La clave debe conservar un código consistente."},{"text":"Estas muestras son símbolos táctiles no braille.","answer":true}]},"id":"s05-art-2-9"},{"fase":"comprobar","areas":["art"],"cnb":["art:3.2.1"],"prompt":"¿Cuál clave comunica con mayor claridad mediante textura?","type":"choice","props":{"options":[{"id":"a","text":"Tres muestras contrastantes, separadas y con significado estable"},{"id":"b","text":"Tres muestras iguales con nombres diferentes"},{"id":"c","text":"Texturas sin clave ni significado acordado"}],"correct":["a"]},"id":"s05-art-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["art"],"cnb":["art:3.2.1"],"type":"reflection","props":{"statements":["Distingo EVA lisa, plástico corrugado y corcho rugoso","Mantengo una clave táctil breve y consistente"],"commitments":["Guardaré el muestrario reutilizable completo","No imitaré braille con símbolos inventados"]},"id":"s05-art-2-11"}],"kind":"materia","area":"art","day":4}},{"missionId":"s05","version":"cnb-sexto-9625b030890594f9","lesson":{"id":"s05-mat-5","title":"Invento mis propias series","icon":"Sparkles","minutes":14,"gancho":"Si tú eres quien pone la regla, ¿qué serie inventarías para retar a tu familia?","objetivos":["Crear series numéricas con reglas combinadas verificables"],"resumen":["Para crear una serie: elige un número inicial, elige una regla de dos o tres operaciones, aplícala varias veces y comprueba cada cálculo.","Describe la regla en orden: \\"×2, luego −3\\" no es lo mismo que \\"−3, luego ×2\\".","Si usas división, elige números que se dividan exacto.","Las series también pueden tener números negativos, por ejemplo una temperatura que baja 3 grados cada hora."],"media":{"id":"s05-mat-5-reto","kind":"image","title":"Reto de series en familia","aspect":"4:3","alt":"Una niña escribe una serie numérica en un pizarrón pequeño en la cocina mientras su abuelo y su hermano piensan qué número sigue.","brief":"Ilustración cálida de una cocina guatemalteca con poyo y comal. Una niña de 11 años escribe en un pizarrón pequeño \\"4, 5, 7, 11, 19, ?\\" y esconde la regla en un papelito doblado. Su abuelo y su hermano menor piensan con expresión divertida. Estilo plano, colores cálidos, sin marcas. Dimensiones: 1200x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:2.1.2"],"ambito":"conocer","prompt":"Diseña una serie cuya regla pueda comprobar otra persona.","type":"explain","props":{"icon":"ListPlus","body":"Una serie bien construida tiene un inicio, una regla explícita y suficientes términos para verificarla. Si alterna operaciones, conviene escribir el ciclo completo antes de calcular."},"id":"s05-mat-5-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:2.1.2"],"ambito":"conocer","prompt":"Empiezas en **2** y tu regla es \\"**×3, luego −1**\\". ¿Cuál es el **segundo** número de tu serie?","explain":"2 × 3 = 6 y 6 − 1 = **5**. Tu serie empieza 2, 5, … ¡Ya estás creando!","type":"choice","props":{"options":[{"id":"a","text":"5"},{"id":"b","text":"6","feedback":"Multiplicaste, pero faltó restar 1."},{"id":"c","text":"4","feedback":"Revisa: primero ×3 (da 6), luego −1."}],"correct":["a"]},"id":"s05-mat-5-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:2.1.2"],"ambito":"conocer","title":"Receta para crear una serie","prompt":"Crear una serie es como seguir una receta. Toca cada paso.","type":"explain","props":{"icon":"ListChecks","body":"Una buena serie tiene una regla clara que se puede descubrir.","reveal":[{"icon":"Play","front":"1. Número inicial","back":"Elige un número pequeño para que los cálculos no se vuelvan enormes."},{"icon":"Cog","front":"2. La regla","back":"Elige 2 o 3 operaciones y su **orden**. \\"×2, luego −3\\" no es lo mismo que \\"−3, luego ×2\\"."},{"icon":"Repeat","front":"3. Aplica y anota","back":"Aplica la regla al último número para obtener el siguiente. Escribe al menos 5 números."},{"icon":"CheckCheck","front":"4. Revisa","back":"Revisa cada cálculo. Si usas división, cuida que el resultado sea exacto."}]},"id":"s05-mat-5-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:2.1.2"],"ambito":"hacer","title":"Ejemplo resuelto: la serie de Ana","prompt":"Ana crea una serie para retar a su abuelo.","type":"worked-example","props":{"icon":"Sparkles","problem":"Ana empieza en **4** con la regla \\"**×2, luego −3**\\". Escribe los primeros 6 números.","steps":[{"text":"4 × 2 = 8; 8 − 3 = **5**."},{"text":"5 × 2 = 10; 10 − 3 = **7**."},{"text":"7 × 2 − 3 = **11**; 11 × 2 − 3 = **19**; 19 × 2 − 3 = **35**.","why":"Siempre se aplica la regla al número anterior."}],"answer":"La serie es **4, 5, 7, 11, 19, 35**.","tip":"Para retar a alguien, muestra solo los primeros números y guarda la regla en secreto."},"id":"s05-mat-5-4"},{"fase":"construir","areas":["mat"],"cnb":["mat:2.1.2"],"prompt":"Crea una serie que empiece en **3** con la regla \\"**×3, luego −4**\\". ¿Cuál es el **cuarto** número?","hint":"El primero es 3. Calcula el segundo, luego el tercero y luego el cuarto.","explain":"3 → 3 × 3 − 4 = 5 → 5 × 3 − 4 = 11 → 11 × 3 − 4 = 29. El cuarto número es 29.","type":"number-input","props":{"answer":29,"misconceptions":[{"value":11,"msg":"Ese es el tercero. Aplica la regla una vez más."},{"value":83,"msg":"Ese sería el quinto. Cuenta el 3 como el primero."}]},"id":"s05-mat-5-5"},{"fase":"construir","areas":["mat"],"cnb":["mat:2.1.2"],"ambito":"conocer","title":"Series con tres operaciones","prompt":"También puedes turnar tres operaciones. Toca cada tarjeta.","type":"explain","props":{"icon":"Layers","body":"En una regla alternada, las operaciones se aplican una a la vez, en orden, y luego se repiten.","reveal":[{"icon":"RefreshCw","front":"\\"+3, ×2, −4\\" desde 2","back":"2, **5** (+3), **10** (×2), **6** (−4), **9** (+3), **18** (×2), **14** (−4)…"},{"icon":"Thermometer","front":"Con negativos","back":"Supongamos que desde 7 °C la temperatura baja 3 grados cada hora: 7, 4, 1, **−2**, **−5**…"},{"icon":"PenLine","front":"Escribe la regla","back":"Una regla clara: \\"Empieza en 2. Suma 3, multiplica por 2, resta 4 y repite.\\""}]},"id":"s05-mat-5-6"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:2.1.2"],"ambito":"hacer","prompt":"¡Ahora eres tú quien inventa! **Crea una serie numérica** de al menos 5 números con una regla que **combine dos o tres operaciones**. Escribe la serie y, aparte, explica la regla. Luego rétale a alguien de tu familia a descubrirla.","type":"short-answer","props":{"minWords":15,"placeholder":"Mi serie es… Mi regla es…","model":"Mi serie es 2, 5, 11, 23, 47. Mi regla es: empieza en 2, multiplica por 2 y luego suma 1. Mi hermano la descubrió al ver que los saltos se duplicaban.","rubric":["Mi serie tiene al menos 5 números","Mi regla combina dos o tres operaciones","Revisé que todos los cálculos estén correctos","Expliqué la regla en orden"]},"id":"s05-mat-5-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:2.1.2"],"prompt":"Luis empieza en **1** con la regla \\"**×2, luego +3**\\". ¿Cuál es su serie?","explain":"1 × 2 + 3 = 5; 5 × 2 + 3 = 13; 13 × 2 + 3 = 29.","type":"choice","props":{"options":[{"id":"a","text":"1, 5, 13, 29"},{"id":"b","text":"1, 8, 22, 50","feedback":"Aplicaste las operaciones al revés: primero +3 y luego ×2."},{"id":"c","text":"1, 5, 9, 13","feedback":"Eso es sumar 4 cada vez."}],"correct":["a"]},"id":"s05-mat-5-8"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:2.1.2"],"prompt":"Crea la serie que empieza en **2** con la regla alternada \\"**+3, ×2, −4**\\". ¿Cuál es el **séptimo** número?","explain":"2, 5, 10, 6, 9, 18, 14. El séptimo es 14.","type":"number-input","props":{"answer":14,"misconceptions":[{"value":18,"msg":"Ese es el sexto. Falta aplicar −4."},{"value":17,"msg":"Revisa el turno: después de ×2 toca −4, no +3."}]},"id":"s05-mat-5-9"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:2.1.2","mat:1.5.1"],"prompt":"Repaso con enteros: supongamos que a medianoche hay **7 °C** y la temperatura **baja 3 grados cada hora**. Serie: 7, 4, 1, … ¿Qué temperatura habrá en la **cuarta** medición?","explain":"7, 4, 1, −2. La cuarta medición es −2 °C.","type":"number-input","props":{"answer":-2,"unit":"°C","allowNegative":true,"misconceptions":[{"value":2,"msg":"Al bajar de 1 tres grados cruzas el cero: queda −2."}]},"id":"s05-mat-5-10"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:2.1.2"],"prompt":"Lucía creó la serie **5, 8, 14, 26, 50**. ¿Qué regla usó?","type":"choice","props":{"options":[{"id":"a","text":"+3 cada vez"},{"id":"b","text":"×2, luego −2"},{"id":"c","text":"×2, luego +2"}],"correct":["b"]},"id":"s05-mat-5-11"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:2.1.2"],"prompt":"Una serie empieza en **4** con la regla \\"**×2, luego +1**\\". ¿Cuál es el **tercer** número?","type":"number-input","props":{"answer":19},"id":"s05-mat-5-12"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["mat"],"cnb":[],"type":"reflection","props":{"statements":["Uso números negativos en situaciones reales","Ubico y comparo enteros en la recta","Ubico puntos en el plano cartesiano","Completo y creo series con operaciones combinadas"],"commitments":["Anotaré la temperatura de mi comunidad varios días","Retaré a mi familia con una serie inventada","Dibujaré un mapa de mi casa con coordenadas"]},"id":"s05-mat-5-13"}],"kind":"materia","area":"mat","day":5}},{"missionId":"s05","version":"cnb-sexto-5e347af8b11cbaec","lesson":{"id":"s05-cnt-3","title":"Nutricion desde los primeros meses","icon":"Baby","minutes":15,"gancho":"¿Que tienen en comun los nutrientes de los alimentos y la leche materna durante el crecimiento?","objetivos":["Explicar la nutricion desde los primeros meses mediante nutrientes y beneficios de la lactancia"],"resumen":["Los alimentos aportan carbohidratos, proteinas, grasas, vitaminas y minerales con funciones distintas.","La leche materna aporta nutricion, componentes inmunitarios y apoyo al crecimiento y desarrollo del bebe.","La lactancia tambien puede favorecer el vinculo; cada familia merece informacion respetuosa y orientacion sanitaria individual cuando la necesite."],"media":{"id":"s05-cnt-3-tiempo-libre","kind":"diagram","title":"Nutricion desde el inicio","aspect":"16:9","alt":"Diagrama respetuoso con una tarjeta sobre lactancia y cinco tarjetas de nutrientes presentes en alimentos.","brief":"Diagrama educativo 1600x900. A la izquierda, una escena respetuosa de lactancia o extraccion de leche sin mostrar anatomia explicita; rotulos: nutricion, componentes inmunitarios, crecimiento/desarrollo y vinculo. A la derecha, alimentos reconocibles vinculados con carbohidratos, proteinas, grasas, vitaminas y minerales. Incluir nota: \\"Informacion general; las situaciones individuales requieren orientacion sanitaria\\". Alto contraste, texto grande y sin juicios sobre familias."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:5.1.1","cnt:5.2.1"],"prompt":"Relaciona la clasificacion de nutrientes en alimentos con los beneficios humanos de la lactancia.","type":"explain","props":{"icon":"Sprout","body":"Clasificamos nutrientes de alimentos en **carbohidratos, proteinas, grasas, vitaminas y minerales**; la **lactancia** aporta nutricion y componentes inmunitarios, y favorece crecimiento, desarrollo y vinculo."},"id":"s05-cnt-3-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:5.1.1","cnt:5.2.1"],"title":"Nutrientes y lactancia","prompt":"Clasifica nutrientes nombrados y describe beneficios suministrados de la leche materna.","type":"explain","props":{"icon":"TableProperties","body":"**Carbohidratos** aportan energia; **proteinas**, materiales para tejidos; **grasas**, energia y componentes celulares; **vitaminas y minerales**, apoyo a procesos corporales. La **leche materna** contiene nutrientes y componentes inmunitarios; apoya crecimiento y desarrollo y puede favorecer el vinculo. Son beneficios generales, no una promesa sobre cada caso."},"id":"s05-cnt-3-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:5.1.1","cnt:5.2.1"],"title":"Modelo: dos etapas de nutricion","prompt":"Observa como clasificar nutrientes nombrados y explicar beneficios de la lactancia.","type":"worked-example","props":{"icon":"GitCompare","problem":"Ficha A: tortilla, frijol y aguacate. Ficha B: leche materna durante los primeros meses.","steps":[{"text":"Tortilla: principalmente carbohidratos; frijol: proteinas, carbohidratos, vitaminas y minerales; aguacate: grasas y vitaminas."},{"text":"La leche materna aporta nutricion y componentes inmunitarios."},{"text":"Tambien apoya crecimiento y desarrollo y puede favorecer el vinculo."}],"answer":"La explicacion clasifica nutrientes y describe beneficios sin convertirlos en garantias individuales."},"id":"s05-cnt-3-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:5.1.1","cnt:5.2.1"],"prompt":"Guia: clasifica nutrientes en alimentos y relaciona beneficios de la lactancia con nutricion, defensas, desarrollo y vinculo.","hint":"Usa la funcion nombrada en cada tarjeta.","explain":"Los alimentos pueden aportar varios nutrientes; la actividad destaca uno. Los beneficios de la lactancia son generales y respetan situaciones individuales.","type":"match","props":{"pairs":[{"id":"a","left":"Arroz: energia","right":"Carbohidratos"},{"id":"b","left":"Huevo: formacion de tejidos","right":"Proteinas"},{"id":"c","left":"Semillas: energia concentrada","right":"Grasas"},{"id":"d","left":"Leche materna","right":"Nutricion, componentes inmunitarios, desarrollo y vinculo"}]},"id":"s05-cnt-3-4"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:5.1.1","cnt:5.2.1"],"prompt":"Caso nuevo: clasifica carbohidratos, proteinas, grasas, vitaminas y minerales en alimentos nombrados, y explica que la lactancia aporta nutricion, componentes inmunitarios, desarrollo y vinculo. ¿Que respuesta cumple ambas tareas?","type":"choice","props":{"options":[{"id":"a","text":"Papa: carbohidratos; lenteja: proteinas y minerales; aceite: grasas; fruta: vitaminas. La leche materna nutre, aporta componentes inmunitarios, apoya desarrollo y puede favorecer el vinculo."},{"id":"b","text":"Todos los alimentos contienen exactamente el mismo nutriente y la lactancia solo aporta agua."},{"id":"c","text":"La clasificacion depende del color y la lactancia garantiza que nunca habra enfermedad."}],"correct":["a"]},"id":"s05-cnt-3-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:5.1.1","cnt:5.2.1"],"prompt":"Clasifica en alimentos nombrados carbohidratos, proteinas, grasas, vitaminas y minerales; luego explica beneficios suministrados de la lactancia: nutricion, componentes inmunitarios, crecimiento o desarrollo y vinculo.","type":"short-answer","props":{"minWords":28,"placeholder":"Alimento y nutriente... Lactancia y beneficios...","model":"Maiz: carbohidratos; frijol: proteinas y minerales; aguacate: grasas; fruta: vitaminas. La lactancia aporta nutricion y componentes inmunitarios, apoya el desarrollo y puede favorecer el vinculo, segun cada situacion familiar.","rubric":["Clasifique nutrientes nombrados","Explique beneficios de la lactancia","Use lenguaje respetuoso y no absoluto"]},"id":"s05-cnt-3-6"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:5.1.1","cnt:5.2.1"],"prompt":"¿Que opcion clasifica carbohidratos, proteinas, grasas, vitaminas y minerales en alimentos y explica beneficios de la lactancia para nutricion, defensas, desarrollo y vinculo?","type":"choice","props":{"options":[{"id":"a","text":"Cereal-carbohidrato, frijol-proteina/mineral, semilla-grasa y fruta-vitamina; la leche materna nutre, aporta componentes inmunitarios, apoya desarrollo y puede favorecer vinculo"},{"id":"b","text":"Todo alimento es solo vitamina; la lactancia no aporta nutrientes"},{"id":"c","text":"Los nutrientes se clasifican por tamano; la lactancia garantiza salud perfecta"}],"correct":["a"]},"id":"s05-cnt-3-7"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:5.1.1","cnt:5.2.1"],"prompt":"Comprueba la clasificacion de carbohidratos, proteinas, grasas, vitaminas y minerales en alimentos y los beneficios de lactancia para nutricion, defensas, desarrollo y vinculo.","type":"true-false","props":{"statements":[{"text":"Un alimento puede aportar mas de un nutriente.","answer":true},{"text":"La leche materna aporta nutrientes y componentes inmunitarios.","answer":true},{"text":"Los beneficios generales de la lactancia garantizan el mismo resultado en toda situacion individual.","answer":false}]},"id":"s05-cnt-3-8"},{"fase":"reflexionar","areas":["cnt"],"cnb":["cnt:5.1.1","cnt:5.2.1"],"prompt":"Revisa tu explicacion de nutricion desde los primeros meses.","type":"reflection","props":{"statements":["Clasifique nutrientes por funcion","Describi beneficios sin prometer resultados","Use lenguaje respetuoso con las familias"],"commitments":["Consultare a personal de salud ante una situacion individual"]},"id":"s05-cnt-3-9"}],"kind":"materia","area":"cnt","day":5}},{"missionId":"s05","version":"cnb-sexto-e6cda5cb6e817b9a","lesson":{"id":"s05-fc-2","title":"El gobierno escolar: elegir, proponer y servir","icon":"Vote","minutes":15,"gancho":"Imagina que tu escuela va a elegir a su gobierno escolar mañana. ¿Por quién votarías: por el más popular o por quien tenga las mejores propuestas?","objetivos":["Evaluar la participación y las propuestas del gobierno escolar"],"resumen":["El gobierno escolar es una organización de estudiantes elegida por voto que representa a sus compañeros, organiza proyectos y trabaja con docentes y dirección. En cada grado también puede haber una directiva de aula.","Cargos frecuentes: presidencia, vicepresidencia, secretaría, tesorería y vocales. Las comisiones (limpieza, deporte, cultura, lectura, huerto) organizan el trabajo.","Una elección democrática sigue pasos: convocatoria, inscripción de planillas, campaña con propuestas, votación secreta, conteo público, toma de posesión y rendición de cuentas.","Una buena propuesta responde a un problema real, es posible con los recursos de la escuela, dice cómo se hará y se puede comprobar si se cumplió."],"media":{"id":"s05-fc-2-eleccion","kind":"video","title":"Así elegimos a nuestro gobierno escolar","aspect":"16:9","duration":75,"alt":"Video animado que muestra una elección en una escuela guatemalteca: planillas con carteles, estudiantes votando detrás de una mampara, conteo en voz alta y juramentación.","brief":"Video animado de 75 s. Escenas: (1) Cartel de convocatoria en el corredor. (2) Tres planillas mixtas (niñas y niños) presentan propuestas en carteles: \\"Rincón de lectura\\", \\"Torneo con equipos mixtos\\", \\"Huerto escolar\\". (3) Día de votación: mesa electoral con estudiantes, papeleta sencilla, mampara de cartón, urna transparente, dedo marcado con tinta. (4) Conteo en voz alta frente a todos, rayitas en el pizarrón. (5) Toma de posesión y, meses después, la planilla ganadora presenta su informe en el periódico mural. Narración en español, subtítulos. Sin logotipos de partidos ni nombres reales."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":["fc:3.2.2"],"ambito":"conocer","prompt":"Relaciona representación estudiantil, propuestas y bien común.","type":"explain","props":{"icon":"Vote","body":"El gobierno escolar representa al estudiantado mediante elección y servicio. Una propuesta responsable parte de una necesidad comprobada, consulta a las personas afectadas y plantea acciones posibles."},"id":"s05-fc-2-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.2"],"ambito":"convivir","prompt":"Hay elección de gobierno escolar. ¿En qué te fijarías **más** para decidir tu voto?","explain":"Lo más importante son las **propuestas**: ¿resuelven un problema real? ¿se pueden cumplir? Un voto responsable mira ideas, no popularidad ni regalos.","type":"choice","props":{"options":[{"id":"a","text":"En sus propuestas y en si se pueden cumplir","icon":"ClipboardList"},{"id":"b","text":"En quién regala más dulces","icon":"Gift","feedback":"Un regalo dura un momento; un mal gobierno escolar dura todo el año. Fíjate en las propuestas."},{"id":"c","text":"En quién es mi mejor amigo","icon":"Heart","feedback":"La amistad es valiosa, pero para gobernar importan las ideas y la responsabilidad."}],"correct":["a"]},"id":"s05-fc-2-2"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.2"],"ambito":"conocer","title":"¿Qué es el gobierno escolar?","prompt":"El **gobierno escolar** es una organización de estudiantes **elegida por voto** que representa a sus compañeros y organiza proyectos para mejorar la escuela. Toca cada tarjeta.","type":"explain","props":{"icon":"School","body":"Gobernar la escuela es **servir**: escuchar a los compañeros, trabajar con docentes y dirección, y rendir cuentas.","reveal":[{"icon":"Users","front":"Cargos","back":"**Presidencia** (coordina), **vicepresidencia** (apoya y reemplaza), **secretaría** (escribe actas), **tesorería** (cuida y reporta el dinero) y **vocales** (apoyan comisiones)."},{"icon":"ClipboardList","front":"Comisiones","back":"Grupos de trabajo: limpieza y ambiente, deporte, cultura, lectura, huerto, disciplina y convivencia."},{"icon":"LayoutGrid","front":"Gobierno del aula","back":"En cada grado, una **directiva de aula** organiza tareas, turnos y acuerdos del grado."},{"icon":"FileText","front":"Actas","back":"Documento donde la secretaría anota lo que se **acordó** en cada reunión, con fecha y firmas."}]},"id":"s05-fc-2-3"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.2"],"prompt":"Une cada cargo con su función principal.","hint":"Recuerda las tarjetas: la secretaría escribe las actas y la tesorería cuida el dinero (el \\"tesoro\\") del grupo.","explain":"Cada cargo tiene una responsabilidad clara; así el trabajo se reparte y nadie decide solo.","type":"match","props":{"leftTitle":"Cargo","rightTitle":"Función","pairs":[{"id":"c1","left":"Presidencia","leftIcon":"Crown","right":"Coordina las reuniones y representa al grupo"},{"id":"c2","left":"Secretaría","leftIcon":"PenLine","right":"Escribe las actas de los acuerdos"},{"id":"c3","left":"Tesorería","leftIcon":"Coins","right":"Cuida el dinero e informa cómo se usa"},{"id":"c4","left":"Vocales","leftIcon":"Users","right":"Apoyan y coordinan las comisiones"}]},"id":"s05-fc-2-4"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.2"],"prompt":"Ordena los pasos de una **elección escolar democrática**.","hint":"Primero se anuncia la elección; lo último es informar lo que se hizo en el año.","explain":"Convocatoria → planillas → campaña → votación secreta → conteo público → toma de posesión → rendición de cuentas.","type":"order","props":{"labels":{"start":"Inicio","end":"Final"},"items":[{"id":"o1","text":"Se publica la convocatoria con fechas y reglas","icon":"Megaphone"},{"id":"o2","text":"Se inscriben las planillas con sus candidatos","icon":"Users"},{"id":"o3","text":"Cada planilla presenta sus propuestas en la campaña","icon":"ClipboardList"},{"id":"o4","text":"Los estudiantes votan en secreto","icon":"Vote"},{"id":"o5","text":"Se cuentan los votos frente a todos","icon":"ListOrdered"},{"id":"o6","text":"La planilla ganadora toma posesión","icon":"Award"},{"id":"o7","text":"El gobierno escolar rinde cuentas de su trabajo","icon":"FileText"}]},"id":"s05-fc-2-5"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.2"],"ambito":"hacer","title":"Ejemplo resuelto: ¿es una buena propuesta?","prompt":"Las propuestas se evalúan con **cuatro preguntas**. Mira cómo se comparan dos propuestas.","type":"worked-example","props":{"icon":"Lightbulb","problem":"Planilla Verde propone: **\\"Vamos a construir una piscina.\\"** Planilla Azul propone: **\\"Crearemos un rincón de lectura en el corredor con libros donados y cajas recicladas, abierto en el recreo; cada mes contaremos cuántos libros se prestaron.\\"**","steps":[{"text":"**¿Responde a un problema real?** Verde: no dice qué problema resuelve. Azul: sí, la biblioteca está cerrada en el recreo."},{"text":"**¿Es posible con los recursos de la escuela?** Verde: no, una piscina cuesta muchísimo. Azul: sí, usa donaciones y material reciclado.","why":"Prometer lo imposible engaña a los votantes."},{"text":"**¿Dice cómo se hará?** Verde: no. Azul: sí (libros donados, cajas, horario de recreo)."},{"text":"**¿Se puede comprobar si se cumplió?** Verde: no dice cómo. Azul: sí, contarán los préstamos cada mes."}],"answer":"La propuesta de la **Planilla Azul** es buena: real, posible, explica cómo y se puede comprobar. La de la Verde es una **promesa imposible**.","tip":"Problema real → posible → cómo → se puede comprobar."},"id":"s05-fc-2-6"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.2"],"prompt":"Clasifica estas propuestas de campaña: ¿**realista y útil** o **promesa vacía**?","hint":"Usa las cuatro preguntas: problema real, posible, cómo, comprobable.","explain":"Las propuestas realistas se pueden cumplir con los recursos de la escuela y dicen cómo; las promesas vacías suenan bonito pero no se pueden cumplir o no dicen nada concreto.","type":"sort","props":{"buckets":[{"id":"ok","label":"Realista y útil","icon":"Check","color":"var(--c-ok)"},{"id":"va","label":"Promesa vacía","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"q1","text":"Organizar turnos por grado para limpiar el patio cada viernes","bucket":"ok"},{"id":"q2","text":"\\"Haremos la mejor escuela del mundo\\"","bucket":"va","feedback":"Suena bonito, pero no dice qué problema resuelve ni cómo."},{"id":"q3","text":"Quitar todas las tareas para siempre","bucket":"va"},{"id":"q4","text":"Un torneo de fútbol y básquetbol con equipos mixtos en el recreo","bucket":"ok"},{"id":"q5","text":"Sembrar un huerto con semillas donadas por las familias","bucket":"ok"}]},"id":"s05-fc-2-7"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:3.2.2"],"ambito":"convivir","prompt":"Un candidato te ofrece una bolsa de dulces a cambio de tu voto. ¿Qué decisión permite evaluar las propuestas y proteger una elección libre?","type":"choice","props":{"options":[{"id":"a","text":"Aceptar los dulces y votar por quien los regaló"},{"id":"b","text":"Rechazar el regalo, comparar las propuestas y reportar la oferta a la comisión electoral"},{"id":"c","text":"Aceptar los dulces y votar al azar para que nadie se entere"}],"correct":["b"]},"id":"s05-fc-2-8"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:3.2.2"],"ambito":"emprender","prompt":"Imagina que te postulas al gobierno escolar. Escribe **una propuesta** que pase las cuatro preguntas: ¿qué problema real resuelve?, ¿con qué recursos?, ¿cómo lo harás? y ¿cómo se comprobará que cumpliste?","type":"short-answer","props":{"minWords":40,"placeholder":"Mi propuesta es… porque en mi escuela…","model":"Mi propuesta es poner dos toneles para recolectar agua de lluvia junto al huerto, porque en época seca las plantas se mueren y el chorro de la escuela no alcanza. Pediremos los toneles usados a las familias y la comisión de ambiente los limpiará y pondrá una canaleta del techo. Cada viernes anotaremos cuántas cubetas de agua usamos del tonel; así todos podrán comprobar si funciona.","rubric":["Nombré un problema real de mi escuela","Mi propuesta es posible con recursos de la escuela o la comunidad","Expliqué cómo se hará y quién lo hará","Dije cómo se comprobará que se cumplió"]},"id":"s05-fc-2-9"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:3.2.2"],"prompt":"¿Qué oración describe una **participación democrática** en el gobierno escolar?","type":"choice","props":{"options":[{"id":"a","text":"Las planillas presentaron propuestas y los estudiantes votaron en secreto."},{"id":"b","text":"El director eligió solo al presidente, sin votación."},{"id":"c","text":"Ganó la planilla que regaló más refacciones."}],"correct":["a"]},"id":"s05-fc-2-10"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:3.2.2"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"La tesorería del gobierno escolar cuida el dinero e informa cómo se usa.","answer":true},{"text":"Los votos se deben contar frente a todos para que haya transparencia.","answer":true},{"text":"\\"Construiremos un estadio\\" es una propuesta realista para un gobierno escolar.","answer":false,"why":"Es una promesa imposible con los recursos de una escuela."},{"text":"Después de ganar, el gobierno escolar ya no tiene que informar nada.","answer":false,"why":"Debe rendir cuentas de su trabajo a todos los estudiantes."}]},"id":"s05-fc-2-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["fc"],"cnb":["fc:3.2.1","fc:3.2.2"],"type":"reflection","props":{"statements":["Explico qué es participar y dónde puedo hacerlo","Conozco los cargos y los pasos de la elección del gobierno escolar","Distingo una propuesta realista de una promesa vacía"],"commitments":["Votaré por propuestas y no por regalos","Me uniré a una comisión de mi grado o escuela","Propondré en casa repartir las tareas del hogar entre todos"]},"id":"s05-fc-2-12"}],"kind":"materia","area":"fc","day":5}},{"missionId":"s05","version":"cnb-sexto-e0b18a116211479d","lesson":{"id":"s05-ef-2","title":"Balonmano: avanzar, pasar y finalizar con control","icon":"Goal","minutes":15,"gancho":"Recibes la pelota y la meta está adelante. ¿Cómo enlazas el avance, el pase y la finalización sin romper la regla de los tres pasos?","objetivos":["Ejecutar una secuencia reglada de avance, pase bilateral y finalización en balonmano"],"resumen":["La secuencia central integra avance, pase y finalización: se dan como máximo tres pasos con la pelota y, para seguir avanzando, se bota antes del paso siguiente.","En el pase por arriba del hombro con salto, el pie contrario impulsa y la pelota se suelta en el punto más alto antes de caer.","El pase se practica con mano izquierda y derecha, a altura media o alta según la posición de quien recibe.","La secuencia termina con una de tres finalizaciones: directa con apoyo, en suspensión durante el salto o con pique antes de la meta."],"media":{"id":"s05-ef-2-balonmano","kind":"video","title":"Pase bilateral con salto","aspect":"16:9","duration":35,"alt":"Dos secuencias laterales muestran tres pasos, un bote controlado, un pase con salto bilateral y una finalización segura.","brief":"Video breve de 35 s en cancha escolar. Mostrar una secuencia integrada a velocidad normal y lenta: recibir, dar tres pasos, botar antes de continuar, reunir la pelota y pasar por arriba del hombro con salto; repetir el pase con la otra mano. Cerrar con tres fotogramas rotulados: finalización directa con apoyo, en suspensión durante el salto y con pique antes de la meta. Pelota suave, distancia corta, sin defensa ni partido. Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:2.1.13"],"ambito":"conocer","prompt":"Observa cómo una jugada enlaza avance, pase y finalización.","type":"explain","props":{"icon":"Route","body":"Quien lleva la pelota avanza con control; quien recibe muestra una zona segura para el pase y completa una finalización acordada sin defensa ni portero."},"id":"s05-ef-2-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.9","ef:2.1.13"],"ambito":"conocer","title":"La secuencia reglada","prompt":"La jugada combina avance reglado, pase con salto y finalización.","type":"explain","props":{"icon":"Route","body":"La técnica se practica primero sin oposición, con pelota suave y una pareja preparada para recibir.","reveal":[{"icon":"Footprints","front":"Avance y bote","back":"Da como máximo **3 pasos** con la pelota. Si continúas avanzando, **bota antes del paso siguiente**; reúne la pelota con control para pasar o finalizar."},{"icon":"ArrowUp","front":"Impulso contrario","back":"Mano derecha con pie izquierdo; mano izquierda con pie derecho."},{"icon":"Hand","front":"Brazo","back":"Lleva el balón por arriba del hombro con el codo alto."},{"icon":"Target","front":"Liberación","back":"Suelta en el punto más alto hacia la altura que muestran las manos de tu pareja."},{"icon":"ShieldCheck","front":"Seguridad","back":"Mantén distancia, usa pelota suave y nunca dirijas el pase a la cara."}]},"id":"s05-ef-2-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.13"],"ambito":"conocer","title":"Una muestra de cada finalización","prompt":"Después de la entrada controlada, compara tres maneras de terminar una jugada. Hoy se realiza solo una prueba de cada tipo, sin portero ni partido.","type":"flashcards","props":{"cards":[{"icon":"Target","front":"Directa","back":"Se suelta con apoyo en el suelo."},{"icon":"ArrowUp","front":"En suspensión","back":"Se suelta durante el salto, antes de caer."},{"icon":"CircleDot","front":"Con pique","back":"La pelota bota una vez antes de la meta."}]},"id":"s05-ef-2-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.13","ef:2.1.9"],"ambito":"hacer","title":"Ejemplo resuelto: una secuencia completa","prompt":"Mira cómo Ixchel y Rosa enlazan avance, pase y finalización.","type":"worked-example","props":{"icon":"Users","problem":"Ixchel recibe lejos de la meta. Rosa está libre, muestra las manos altas y tiene espacio para terminar la jugada.","steps":[{"text":"Ixchel avanza **3 pasos** y **bota la pelota antes del paso siguiente**."},{"text":"Reúne la pelota con control y observa las manos altas de Rosa."},{"text":"Elige la **mano derecha** y se impulsa con el **pie izquierdo**.","why":"El apoyo es contrario al brazo ejecutor."},{"text":"Pasa por arriba del hombro y suelta en el **punto más alto** hacia Rosa."},{"text":"Rosa recibe y realiza una finalización **con pique**: la pelota bota una vez antes de la meta."},{"text":"En las variantes, Rosa finaliza **directa** con apoyo o **en suspensión** soltando durante el salto."}],"answer":"Secuencia: **3 pasos → bote → pase bilateral con salto → finalización directa, en suspensión o con pique**.","tip":"Alternen la mano del pase y la variante de finalización, siempre sin defensa."},"id":"s05-ef-2-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.9","ef:2.1.13"],"ambito":"hacer","prompt":"Ordena una secuencia reglada de avance, pase y finalización.","hint":"Primero controla el avance y el bote; después pasa y termina la jugada.","explain":"Recibir → avanzar hasta 3 pasos → botar antes de continuar → pasar con salto → finalizar.","type":"order","props":{"items":[{"id":"x1","text":"Recibir la pelota con control"},{"id":"x2","text":"Avanzar como máximo 3 pasos"},{"id":"x3","text":"Botar antes del paso siguiente si se continúa"},{"id":"x4","text":"Reunir y pasar por arriba del hombro con salto"},{"id":"x5","text":"Completar la finalización asignada"}],"labels":{"start":"Inicio","end":"Final"}},"id":"s05-ef-2-5"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:2.1.9","ef:2.1.13"],"ambito":"hacer","prompt":"Práctica breve en parejas con pelota suave. Realicen **6 secuencias totales**, no series separadas: en cada una, quien inicia avanza hasta **3 pasos**, hace un **bote** antes de continuar, reúne la pelota y completa un pase por arriba del hombro con salto; su pareja recibe y finaliza. Alternen **3 pases con la izquierda y 3 con la derecha**. Usen dos veces cada finalización: **directa, en suspensión y con pique**. Lleven un **registro de una fila por secuencia**: regla de pasos y bote, mano y pie contrario, pase a zona segura y variante terminada. Sin defensa ni portero; mantengan distancia y nunca apunten a la cara. La secuencia puede hacerse caminando y sin salto desde una posición estable. Al final, caminen y relajen hombros.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después de 3 secuencias","exercise":{"name":"Avance, bote, pase y finalización","icon":"Route","seconds":90}},{"label":"Después de 6 secuencias","exercise":{"name":"Secuencias bilaterales completas","icon":"Goal","seconds":90}}]},"id":"s05-ef-2-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:2.1.13"],"ambito":"hacer","prompt":"En una secuencia nueva, Rosa avanza 3 pasos y empieza un cuarto sin botar antes de realizar una finalización directa. ¿Qué ajuste conserva la secuencia reglada?","explain":"Si continúa después de 3 pasos, debe botar antes del paso siguiente; la finalización directa puede mantenerse.","type":"choice","props":{"options":[{"id":"a","text":"Botar antes del cuarto paso y conservar la finalización directa"},{"id":"b","text":"Dar el cuarto paso sin botar porque la meta está cerca","feedback":"La cercanía de la meta no elimina la regla de pasos."},{"id":"c","text":"Lanzar la pelota a la cara para terminar rápido","feedback":"La seguridad se mantiene durante toda la secuencia."}],"correct":["a"]},"id":"s05-ef-2-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:2.1.13"],"ambito":"hacer","prompt":"Tras una entrada controlada, relaciona cada forma de finalizar con la evidencia que la distingue.","explain":"La directa conserva apoyo, la suspensión libera en el aire y el pique bota antes de la meta.","type":"match","props":{"pairs":[{"id":"a","left":"Directa","right":"Liberación con apoyo en el suelo"},{"id":"b","left":"En suspensión","right":"Liberación durante el salto"},{"id":"c","left":"Con pique","right":"Un bote antes de la meta"}]},"id":"s05-ef-2-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:2.1.9"],"prompt":"Las manos de la pareja están altas. ¿Qué evidencia corresponde a un pase con salto controlado?","type":"choice","props":{"options":[{"id":"a","text":"Pie contrario, balón por arriba del hombro y liberación en el punto más alto hacia las manos"},{"id":"b","text":"Mismo pie que la mano y pelota soltada después de caer"},{"id":"c","text":"Pelota dirigida a la cara con fuerza máxima"}],"correct":["a"]},"id":"s05-ef-2-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:2.1.9","ef:2.1.13"],"prompt":"Comprueba la regla de 3 pasos y bote y las tres finalizaciones de la secuencia.","type":"true-false","props":{"statements":[{"text":"Si se continúa avanzando después de 3 pasos, se bota antes del paso siguiente.","answer":true},{"text":"La finalización directa se libera con apoyo en el suelo.","answer":true},{"text":"En suspensión se suelta la pelota después de caer.","answer":false,"why":"Se suelta durante el salto, antes de caer."},{"text":"En la finalización con pique, la pelota bota una vez antes de la meta.","answer":true}]},"id":"s05-ef-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["ef"],"cnb":["ef:2.1.9","ef:2.1.13"],"type":"reflection","props":{"statements":["Respeto 3 pasos y bote antes de continuar","Uso ambas manos con pie contrario","Completo seis secuencias con las tres finalizaciones"],"commitments":["Practicaré con ambas manos a distancia segura","Detendré la práctica si el espacio no está despejado"]},"id":"s05-ef-2-11"}],"kind":"materia","area":"ef","day":5}},{"missionId":"s05","version":"cnb-sexto-a329c1c58357ead2","lesson":{"id":"s05-d5-reto","kind":"reto","day":5,"title":"Reto de la semana 5","icon":"Trophy","minutes":14,"objetivos":["Transferir lo aprendido en las diez áreas a situaciones nuevas"],"resumen":["Resolví situaciones nuevas de las diez áreas sin pistas ni respuestas reutilizadas."],"media":{"id":"s05-d5-reto","kind":"image","title":"Mesa de revisión del plano escolar","aspect":"16:9","alt":"Mesa con un plano táctil, una hoja de coordenadas, muestras de textura, un registro de prueba entre pares y herramientas escolares guardadas de forma segura.","brief":"Mock de producción para una imagen cenital clara, legible en celular. Mostrar el producto real de la semana: plano táctil cuadriculado con cuatro destinos, ruta continua, clave de tres texturas y coordenadas visibles. Alrededor, una ficha rotulada \\"prueba entre pares, ojos abiertos\\", una tarjeta \\"consulta especializada pendiente\\", una lista de revisión y una bandeja con un rodillo manual redondeado guardado. No mostrar evidencia atribuida a personas con discapacidad, piezas filosas sueltas, personas con los ojos cubiertos ni mensajes que prometan accesibilidad universal. Dimensiones: 1600x900."},"steps":[{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.5.3"],"prompt":"En un plano nuevo, coloca la biblioteca en **(−1, 5)**.","type":"coordinate-map","props":{"range":{"xmin":-5,"xmax":5,"ymin":-5,"ymax":5},"task":{"kind":"place","x":-1,"y":5,"emoji":"📚","label":"Biblioteca"}},"id":"s05-d5-reto-1"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:7.1.2"],"prompt":"Completa la concordancia del aviso escolar.","type":"fill-blank","props":{"text":"Las entradas [[amplias]] permanecen [[despejadas]].","distractors":["amplia","despejado","amplios"]},"id":"s05-d5-reto-2"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:4.2.1"],"prompt":"Un grupo busca una actividad protectora para el recreo. ¿Cuál cumple mejor ese propósito?","type":"choice","props":{"options":[{"id":"a","text":"Organizar juegos cooperativos voluntarios con acompañamiento adulto"},{"id":"b","text":"Dejar a cada estudiante sin opciones ni espacios compartidos"},{"id":"c","text":"Ofrecer sustancias para soportar el cansancio"}],"correct":["a"]},"id":"s05-d5-reto-3"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:6.5.1"],"prompt":"Relaciona cada ficha temporal con su interpretación histórica.","type":"match","props":{"pairs":[{"id":"a","left":"1914: una crisis activa compromisos entre alianzas rivales","right":"Una tensión localizada puede extenderse entre varios Estados"},{"id":"b","left":"1945: representantes redactan la carta de una nueva organización internacional","right":"Respuesta institucional orientada a la cooperación posterior"}]},"id":"s05-d5-reto-4"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:3.3.4"],"prompt":"¿Qué mensaje argumenta con una razón comprobable?","type":"choice","props":{"options":[{"id":"a","text":"Propongo reparar el pasamanos porque la inspección registró dos soportes flojos"},{"id":"b","text":"El pasamanos está junto a la pared"},{"id":"c","text":"Repárenlo porque sí"}],"correct":["a"]},"id":"s05-d5-reto-5"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:2.2.3"],"prompt":"Complete: Ellos rotulan el mapa cuidadosamente. (They label the map carefully.)","type":"fill-blank","props":{"text":"[[They]] [[label]] the map [[carefully]].","distractors":["Labels","careful","He"]},"id":"s05-d5-reto-6"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:3.2.2"],"prompt":"¿Qué propuesta permite rendir cuentas al gobierno escolar?","type":"choice","props":{"options":[{"id":"a","text":"Publicar el acuerdo, la persona responsable, la fecha y el resultado de la revisión"},{"id":"b","text":"Prometer cambios sin responsables ni fecha"},{"id":"c","text":"Decidir en secreto y evitar preguntas"}],"correct":["a"]},"id":"s05-d5-reto-7"},{"fase":"comprobar","areas":["art"],"cnb":["art:3.2.1"],"prompt":"Une cada muestra nueva con la sensación táctil que comunica.","type":"match","props":{"pairs":[{"id":"a","left":"Goma EVA sin relieve","right":"Lisa"},{"id":"b","left":"Cartón corrugado","right":"Acanalada"},{"id":"c","left":"Esponja firme","right":"Porosa"}]},"id":"s05-d5-reto-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:2.1.9"],"prompt":"Una secuencia nueva de fotogramas muestra un pase por arriba del hombro con salto: Julia usa la mano derecha hacia una altura alta, se impulsa con el pie izquierdo, pero conserva la pelota durante la fase aérea y la suelta después de aterrizar. ¿Qué error observable y qué corrección corresponden?","type":"choice","props":{"options":[{"id":"a","text":"La liberación es tardía; debe soltar la pelota en el punto más alto de la fase aérea"},{"id":"b","text":"La mano ejecutora es incorrecta; debe cambiar a la izquierda y mantener la liberación después de caer"},{"id":"c","text":"La altura es incorrecta; debe dirigir el pase al suelo antes de saltar"}],"correct":["a"]},"id":"s05-d5-reto-9"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:3.2.3","pyd:3.2.4"],"prompt":"Clasifica acciones al usar una perforadora de papel escolar.","type":"sort","props":{"buckets":[{"id":"antes","label":"Antes","icon":"ClipboardCheck"},{"id":"durante","label":"Durante","icon":"Hand"},{"id":"despues","label":"Después","icon":"PackageCheck"}],"items":[{"id":"a","text":"Comprobar que la base esté estable","bucket":"antes"},{"id":"b","text":"Mantener los dedos fuera del mecanismo","bucket":"durante"},{"id":"c","text":"Vaciar los círculos de papel y guardarla","bucket":"despues"}]},"id":"s05-d5-reto-10"}]}},{"missionId":"s05","version":"cnb-sexto-a11101b3264c2e69","lesson":{"id":"s05-mat-3","title":"El plano cartesiano y los pares ordenados","icon":"MapPin","minutes":14,"gancho":"Para decirle a un amigo dónde enterraste un \\"tesoro\\" en el patio, ¿cuántos números necesitas?","objetivos":["Ubicar puntos con pares ordenados en los cuatro cuadrantes del plano cartesiano"],"resumen":["El plano cartesiano tiene dos rectas numéricas: el eje x (horizontal) y el eje y (vertical). Se cruzan en el origen (0, 0).","Un par ordenado (x, y) indica: primero cuánto moverse a la derecha (+) o a la izquierda (−); después, cuánto subir (+) o bajar (−).","El orden importa: (2, 5) y (5, 2) son puntos diferentes.","Los ejes dividen el plano en 4 cuadrantes: I (+, +), II (−, +), III (−, −) y IV (+, −)."],"media":{"id":"s05-mat-3-mapa","kind":"image","title":"Un mapa con coordenadas","aspect":"4:3","alt":"Mapa ilustrado de una aldea sobre una cuadrícula con ejes numerados de −5 a 5: la escuela, el mercado, la iglesia, la cancha y el pozo están en distintos cuadrantes.","brief":"Ilustración cenital de una aldea guatemalteca sobre una cuadrícula con ejes x e y numerados de −5 a 5 y el origen (0, 0) en la plaza central. Íconos grandes: escuela en (2, 3), mercado en (−3, 2), iglesia en (−2, −3), cancha en (4, −1), pozo en (0, −2). Caminos de tierra, árboles, colores suaves. Los cuatro cuadrantes rotulados con números romanos pequeños. Sin texto adicional. Dimensiones: 1200x900."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:1.5.3"],"ambito":"conocer","prompt":"Aprende a leer un lugar mediante un par ordenado.","type":"explain","props":{"icon":"MapPin","body":"Un punto se escribe (x, y): primero se avanza sobre el eje horizontal y luego sobre el vertical. El origen (0, 0) sirve como referencia común para ubicar espacios de la escuela."},"id":"s05-mat-3-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.5.3"],"ambito":"conocer","prompt":"Para decir exactamente dónde está tu escritorio en el aula, ¿qué información necesitas?","explain":"Necesitas **dos datos**: la fila y la columna. En matemáticas, un punto del plano también se ubica con **dos números**.","type":"choice","props":{"options":[{"id":"a","text":"Solo el número de la fila","icon":"AlignJustify","feedback":"En una misma fila hay varios escritorios."},{"id":"b","text":"La fila y la columna","icon":"Grid3x3"},{"id":"c","text":"El color del escritorio","icon":"Palette","feedback":"Varios escritorios pueden ser del mismo color."}],"correct":["b"]},"id":"s05-mat-3-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.5.3"],"ambito":"conocer","title":"Partes del plano cartesiano","prompt":"El **plano cartesiano** está formado por dos rectas numéricas que se cruzan en ángulo recto. Toca cada tarjeta.","media":{"id":"s05-mat-3-plano","kind":"diagram","title":"Ejes, origen y cuadrantes","aspect":"1:1","alt":"Plano cartesiano de −5 a 5 con el eje x horizontal, el eje y vertical, el origen marcado y los cuadrantes I, II, III y IV con sus signos.","brief":"Diagrama cuadrado de un plano cartesiano de −5 a 5 en ambos ejes. Eje x en azul (rotulado \\"x\\"), eje y en rojo (\\"y\\"), origen (0, 0) con punto negro. Cuadrantes rotulados: I (+, +) arriba a la derecha, II (−, +) arriba a la izquierda, III (−, −) abajo a la izquierda, IV (+, −) abajo a la derecha. Un punto ejemplo (3, 2) con flechas punteadas: 3 a la derecha, 2 arriba. Fondo blanco con cuadrícula suave. Dimensiones: 1200x1200. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"type":"explain","props":{"icon":"Grid3x3","body":"Un punto se nombra con un **par ordenado (x, y)**.","reveal":[{"icon":"MoveHorizontal","front":"Eje x","back":"La recta **horizontal**. Negativos a la izquierda, positivos a la derecha."},{"icon":"MoveVertical","front":"Eje y","back":"La recta **vertical**. Negativos abajo, positivos arriba."},{"icon":"CircleDot","front":"Origen (0, 0)","back":"El punto donde se cruzan los ejes. De ahí partes siempre."},{"icon":"ListOrdered","front":"(x, y)","back":"**Primero x** (derecha o izquierda), **después y** (arriba o abajo). Como decimos: \\"primero caminas, luego subes\\"."}]},"id":"s05-mat-3-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.5.3"],"ambito":"hacer","title":"Ubicar puntos","prompt":"Así se ubican tres puntos desde el origen.","type":"worked-example","props":{"icon":"MapPin","problem":"Ubica los puntos **(3, 2)**, **(−2, 4)** y **(4, −3)**.","steps":[{"text":"(3, 2): desde el origen, **3 a la derecha** y **2 hacia arriba**."},{"text":"(−2, 4): **2 a la izquierda** (porque x es negativo) y **4 hacia arriba**.","why":"El signo menos en x indica izquierda."},{"text":"(4, −3): **4 a la derecha** y **3 hacia abajo**.","why":"El signo menos en y indica abajo."}],"answer":"Cada punto queda en un lugar único del plano.","tip":"Error frecuente: invertir el orden. (2, 5) no es lo mismo que (5, 2)."},"id":"s05-mat-3-4"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.5.3"],"ambito":"hacer","prompt":"Coloca la estrella en el punto **(2, 3)**.","hint":"Desde el origen: 2 a la derecha y luego 3 hacia arriba.","explain":"x = 2 (derecha), y = 3 (arriba).","type":"coordinate-map","props":{"range":{"xmin":-5,"xmax":5,"ymin":-5,"ymax":5},"task":{"kind":"place","x":2,"y":3,"emoji":"⭐","label":"Estrella"}},"id":"s05-mat-3-5"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.5.3"],"ambito":"conocer","title":"Los cuatro cuadrantes","prompt":"Los signos del par te dicen en qué **cuadrante** está un punto. Toca cada tarjeta.","type":"explain","props":{"icon":"LayoutGrid","body":"Los cuadrantes se numeran I, II, III y IV, empezando arriba a la derecha y girando en sentido contrario a las manecillas del reloj.","reveal":[{"icon":"ArrowUpRight","front":"I (+, +)","back":"Derecha y arriba. Ejemplo: (3, 2)."},{"icon":"ArrowUpLeft","front":"II (−, +)","back":"Izquierda y arriba. Ejemplo: (−2, 4)."},{"icon":"ArrowDownLeft","front":"III (−, −)","back":"Izquierda y abajo. Ejemplo: (−3, −1)."},{"icon":"ArrowDownRight","front":"IV (+, −)","back":"Derecha y abajo. Ejemplo: (4, −3). Si una coordenada es 0, el punto está sobre un eje."}]},"id":"s05-mat-3-6"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.5.3"],"ambito":"hacer","prompt":"Coloca la bandera en el punto **(−3, 2)**.","hint":"x = −3: tres a la izquierda. y = 2: dos hacia arriba.","explain":"El punto (−3, 2) está en el cuadrante II: izquierda y arriba.","type":"coordinate-map","props":{"range":{"xmin":-5,"xmax":5,"ymin":-5,"ymax":5},"task":{"kind":"place","x":-3,"y":2,"emoji":"🚩","label":"Bandera"}},"id":"s05-mat-3-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.5.3"],"prompt":"En el mapa de la aldea, ¿qué lugar está en el punto **(−2, −3)**? Tócalo.","explain":"Dos a la izquierda y tres hacia abajo: ahí está la iglesia.","type":"coordinate-map","props":{"range":{"xmin":-5,"xmax":5,"ymin":-5,"ymax":5},"markers":[{"id":"esc","label":"Escuela","emoji":"🏫","x":2,"y":3},{"id":"mer","label":"Mercado","emoji":"🧺","x":-3,"y":2},{"id":"igl","label":"Iglesia","emoji":"⛪","x":-2,"y":-3},{"id":"can","label":"Cancha","emoji":"⚽","x":4,"y":-1},{"id":"poz","label":"Pozo","emoji":"💧","x":0,"y":-2}],"task":{"kind":"identify","markerId":"igl"}},"id":"s05-mat-3-8"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.5.3"],"prompt":"Pedro dice: \\"(2, 5) y (5, 2) son el mismo punto, porque tienen los mismos números\\". ¿Tiene razón?","explain":"No. (2, 5) está 2 a la derecha y 5 arriba; (5, 2) está 5 a la derecha y 2 arriba. El **orden** cambia el lugar.","type":"choice","props":{"options":[{"id":"a","text":"Sí, el orden no importa","feedback":"Prueba ubicarlos: quedan en lugares distintos."},{"id":"b","text":"No, el orden importa: primero x y después y"}],"correct":["b"]},"id":"s05-mat-3-9"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.5.3"],"prompt":"Van a sembrar un árbol en el punto **(4, −2)**. Colócalo.","explain":"Cuatro a la derecha y dos hacia abajo: cuadrante IV.","type":"coordinate-map","props":{"range":{"xmin":-5,"xmax":5,"ymin":-5,"ymax":5},"task":{"kind":"place","x":4,"y":-2,"emoji":"🌳","label":"Árbol"}},"id":"s05-mat-3-10"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.5.3"],"prompt":"¿En qué cuadrante está el punto **(−4, −3)**?","type":"choice","props":{"options":[{"id":"i","text":"Cuadrante I (+, +)"},{"id":"ii","text":"Cuadrante II (−, +)"},{"id":"iii","text":"Cuadrante III (−, −)"},{"id":"iv","text":"Cuadrante IV (+, −)"}],"correct":["iii"]},"id":"s05-mat-3-11"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.5.3"],"prompt":"¿Qué lugar está en el punto **(4, −1)**? Tócalo.","type":"coordinate-map","props":{"range":{"xmin":-5,"xmax":5,"ymin":-5,"ymax":5},"markers":[{"id":"esc","label":"Escuela","emoji":"🏫","x":2,"y":3},{"id":"mer","label":"Mercado","emoji":"🧺","x":-3,"y":2},{"id":"igl","label":"Iglesia","emoji":"⛪","x":-2,"y":-3},{"id":"can","label":"Cancha","emoji":"⚽","x":4,"y":-1},{"id":"poz","label":"Pozo","emoji":"💧","x":0,"y":-2}],"task":{"kind":"identify","markerId":"can"}},"id":"s05-mat-3-12"}],"kind":"materia","area":"mat","day":3}},{"missionId":"s05","version":"cnb-sexto-25fd9a4d384aad13","lesson":{"id":"s05-ef-1","title":"Pasar y recibir en movimiento","icon":"Users","minutes":15,"gancho":"Si le lanzas la pelota a tu compañera justo donde está ahora, pero ella va corriendo, ¿dónde estará cuando llegue la pelota?","objetivos":["Aplicar recepción, pase adelantado y desmarque durante el movimiento"],"resumen":["Recepción: mira la pelota, brazos adelante, manos abiertas formando una \\"W\\" con pulgares e índices casi juntos; al tocarla, dobla los codos y llévala al pecho para amortiguar.","Pase adelantado: si tu compañero se mueve, lanza al espacio donde estará cuando llegue la pelota, un poco delante de él.","\\"Pasa y muévete\\": después de pasar, desplázate a un espacio libre para volver a recibir. Así el equipo avanza.","Para pasar en movimiento: mira a tu compañero, usa un pase de pecho o por arriba del hombro según la distancia, y comunícate con la voz o con la mano."],"media":{"id":"s05-ef-1-pase-adelantado","kind":"animation","title":"El pase adelantado","aspect":"16:9","duration":40,"alt":"Vista desde arriba: una niña corre en línea recta; su compañera le lanza la pelota a un punto marcado delante de ella, y la pelota y la niña llegan juntas a ese punto.","brief":"Animación 2D cenital de 40 s sobre cancha verde. (1) Error: la pasadora lanza directo a donde está la receptora que corre; la pelota llega detrás de ella (X roja). (2) Acierto: se marca un punto \\"X\\" delante de la receptora; la pelota y la receptora llegan al mismo tiempo (check verde). (3) Tras pasar, la pasadora corre a un espacio libre: rótulo \\"pasa y muévete\\". (4) Primer plano de las manos en \\"W\\" recibiendo y llevando la pelota al pecho. Rótulos grandes, sin narración obligatoria (subtítulos opcionales)."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"conocer","prompt":"Coordina mirada, desplazamiento y pase para jugar con seguridad.","type":"explain","props":{"icon":"CircleDotDashed","body":"Quien recibe muestra las manos y mira el balón; quien pasa apunta al espacio hacia donde avanza su compañero. La distancia y la fuerza se ajustan para evitar choques."},"id":"s05-ef-1-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"conocer","prompt":"Tu compañera corre hacia adelante. ¿A dónde le lanzas la pelota?","explain":"Un poco **delante** de ella: al lugar donde estará cuando llegue la pelota. Se llama **pase adelantado**.","type":"choice","props":{"options":[{"id":"a","text":"Justo donde está ahora","icon":"CircleDot","feedback":"Cuando la pelota llegue, ella ya habrá avanzado: la pelota quedará detrás."},{"id":"b","text":"Un poco delante de ella, a donde va","icon":"ArrowRight"},{"id":"c","text":"Detrás de ella, para que se regrese","icon":"ArrowLeft","feedback":"La obligarías a frenar y regresar: el equipo pierde velocidad."}],"correct":["b"]},"id":"s05-ef-1-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"hacer","title":"Recibir con seguridad","prompt":"Un buen pase necesita una buena **recepción**. Toca cada paso y practícalo con una pelota imaginaria.","type":"explain","props":{"icon":"Hand","body":"Las manos forman una **\\"W\\"**: pulgares e índices casi se tocan detrás de la pelota. Así no se escapa ni te lastima los dedos.","reveal":[{"icon":"Eye","front":"1. Mira la pelota","back":"Sigue la pelota con la vista **hasta que toque tus manos**."},{"icon":"Hand","front":"2. Manos en \\"W\\"","back":"Brazos adelante, dedos abiertos y relajados, pulgares e índices formando una **W**. Si la pelota viene baja, las manos apuntan hacia abajo."},{"icon":"ArrowDown","front":"3. Amortigua","back":"Al tocarla, **dobla los codos** y lleva la pelota al pecho, como si atraparas un huevo."},{"icon":"Shield","front":"4. Protege","back":"Sujétala con firmeza y gira el cuerpo para alejarla de los defensores."}]},"id":"s05-ef-1-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"hacer","title":"Pasar en movimiento","prompt":"En un juego casi nadie está quieto. Mira la animación y toca cada tarjeta.","type":"explain","props":{"icon":"Route","body":"Pasar en movimiento combina **desplazarse**, **lanzar** y **recibir**: es una habilidad genérica como las de la semana 2.","reveal":[{"icon":"ArrowRight","front":"Pase adelantado","back":"Lanza **al espacio** donde estará tu compañero, un poco delante de él y a la altura del pecho."},{"icon":"Route","front":"Pasa y muévete","back":"Después de pasar, **no te quedes quieto**: corre a un espacio libre donde puedas volver a recibir."},{"icon":"MessageCircle","front":"Comunícate","back":"Pide la pelota con la **voz** (\\"¡aquí!\\") o levantando la mano. Llama por su nombre a quien le pasas."},{"icon":"Gauge","front":"Fuerza justa","back":"Si tu compañero está cerca, pase suave de pecho; si está lejos, por arriba del hombro. Una pelota demasiado fuerte es difícil de recibir."}]},"id":"s05-ef-1-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"hacer","title":"Ejemplo resuelto: el pase en la carrera","prompt":"Mira cómo Diego y Rosa avanzan por la cancha pasándose la pelota.","type":"worked-example","props":{"icon":"Users","problem":"Diego y Rosa corren en paralelo, separados por 4 pasos, de una línea a otra de la cancha. Deben llegar al final sin que la pelota caiga.","steps":[{"text":"Diego tiene la pelota. **Mira** a Rosa y ve que va un poco adelantada."},{"text":"Lanza un **pase de pecho** suave, **un paso delante** de Rosa, a la altura de su pecho.","why":"Es el pase adelantado: la pelota y Rosa llegan juntas."},{"text":"Rosa recibe con las manos en **\\"W\\"** y amortigua llevando la pelota al pecho, sin dejar de trotar (máximo 3 pasos con la pelota, como verás el viernes)."},{"text":"Diego, que ya pasó, **acelera** para ponerse otra vez a la par y pedir la pelota: \\"¡Rosa!\\".","why":"\\"Pasa y muévete\\": así siempre hay a quién pasar."}],"answer":"Con **pases adelantados**, **recepción en W** y **pasa y muévete**, avanzan sin que caiga la pelota.","tip":"Empiecen caminando, luego trotando y al final corriendo."},"id":"s05-ef-1-5"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"hacer","prompt":"Ordena los pasos para **recibir** bien la pelota.","hint":"Primero los ojos, luego las manos, después los codos.","explain":"Mirar la pelota → manos en W → tocar y doblar los codos → llevarla al pecho y protegerla.","type":"order","props":{"items":[{"id":"a","text":"Mirar la pelota hasta que llegue"},{"id":"b","text":"Poner los brazos adelante con las manos en \\"W\\""},{"id":"c","text":"Doblar los codos al tocarla para amortiguar"},{"id":"d","text":"Llevarla al pecho y protegerla"}],"labels":{"start":"Primero","end":"Al final"}},"id":"s05-ef-1-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"hacer","prompt":"Usen una pelota suave y cuatro marcas separadas. **Calentamiento breve:** caminen, movilicen hombros y muñecas y ensayen la recepción en W sin pelota. **Prueba bilateral y recorrido cooperativo:** en parejas completen **6 pases adelantados totales** entre las marcas: 3 caminando y 3 trotando. Repartan las recepciones de forma bilateral; después de cada pase, quien lanzó se mueve a la siguiente marca libre. Trabajen sin defensa ni tanteo: si la pelota cae, recuperen el control y continúen desde la marca anterior. Ajusten distancia, velocidad y tamaño de pelota para que ambas personas participen con seguridad. **Vuelta a la calma:** caminen, respiren y relajen brazos.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después de caminar","exercise":{"name":"Recepción y pase bilateral","icon":"Users","seconds":60}},{"label":"Después del recorrido","exercise":{"name":"Circuito cooperativo: pasa y muévete","icon":"Route","seconds":90}}]},"id":"s05-ef-1-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"hacer","prompt":"En un recorrido cooperativo, Juan pasa la pelota y se queda quieto mirando. Su pareja llega a la siguiente marca sin una opción libre. ¿Qué debió hacer Juan?","explain":"Después de pasar hay que **moverse a un espacio libre** para ofrecer una nueva opción de pase.","type":"choice","props":{"options":[{"id":"a","text":"Moverse a un espacio libre y pedir la pelota"},{"id":"b","text":"Pararse junto a quien tiene la pelota","feedback":"Si está pegado, el defensor cubre a los dos a la vez."},{"id":"c","text":"Quedarse quieto para no cansarse","feedback":"Sin movimiento no hay opciones de pase."}],"correct":["a"]},"id":"s05-ef-1-8"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"hacer","prompt":"Cuando recibe, a Sara la pelota le \\"rebota\\" en las manos y se le cae. Tiene los brazos rígidos y los dedos juntos. ¿Qué le aconsejas?","explain":"Dedos abiertos en \\"W\\" y codos que se doblan al tocar la pelota: así la frena poco a poco, como un colchón.","type":"choice","props":{"options":[{"id":"a","text":"Abrir los dedos en \\"W\\" y doblar los codos al recibir"},{"id":"b","text":"Recibir con los brazos todavía más duros","feedback":"Los brazos rígidos hacen que la pelota rebote."},{"id":"c","text":"Cerrar los ojos al recibir","feedback":"Hay que mirar la pelota hasta que llegue a las manos."}],"correct":["a"]},"id":"s05-ef-1-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:2.1.5"],"prompt":"Clasifica cada acción al pasar y recibir en movimiento: ¿es **correcta** o un **error**?","type":"sort","props":{"buckets":[{"id":"ok","label":"Correcta","icon":"Check","color":"var(--c-ok)"},{"id":"no","label":"Error","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"y1","text":"Lanzar un paso delante de un compañero que corre","bucket":"ok"},{"id":"y2","text":"Lanzar justo a donde está ahora un compañero que corre","bucket":"no"},{"id":"y3","text":"Recibir con los brazos rígidos y los dedos juntos","bucket":"no"},{"id":"y4","text":"Doblar los codos al tocar la pelota","bucket":"ok"}]},"id":"s05-ef-1-10"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:2.1.5"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Después de pasar la pelota conviene moverse a un espacio libre.","answer":true},{"text":"Para recibir, las manos forman una \\"W\\" y los codos se doblan para amortiguar.","answer":true},{"text":"Un pase muy fuerte a alguien que está cerca es más fácil de recibir.","answer":false,"why":"De cerca se usa un pase suave; uno muy fuerte es difícil de controlar."}]},"id":"s05-ef-1-11"}],"kind":"materia","area":"ef","day":2}},{"missionId":"s05","version":"cnb-sexto-e8c2212bb934791d","lesson":{"id":"s05-fc-1","title":"Participar en casa, en la escuela y en la comunidad","icon":"Hand","minutes":14,"gancho":"¿Alguna vez te preguntaron tu opinión para decidir algo en tu familia? ¿Cómo te sentiste?","objetivos":["Aplicar un proceso de participación informada, respetuosa e inclusiva"],"resumen":["Participar es tomar parte en las decisiones y acciones de un grupo: informarse, opinar, proponer, actuar y evaluar.","La niñez tiene derecho a opinar y ser escuchada en lo que le afecta (Convención sobre los Derechos del Niño). Participar también es una responsabilidad: cumplir lo que se acuerda.","En la familia se participa compartiendo tareas y opinando en las decisiones; en la escuela, en comisiones y asambleas; en la comunidad, en jornadas de limpieza, reforestación, festivales y consultas.","Una buena participación es voluntaria, informada y respetuosa, e incluye a todas las personas."],"media":{"id":"s05-fc-1-tres-espacios","kind":"image","title":"Tres espacios para participar","aspect":"16:9","alt":"Tres escenas: una familia que decide junta en la mesa, una asamblea de grado que vota a mano alzada y una jornada comunitaria de reforestación.","brief":"Ilustración en tres paneles, estilo plano y colores cálidos. (1) \\"En la familia\\": una familia guatemalteca alrededor de la mesa con tortillas; la niña habla y los adultos escuchan; al fondo, un cartel de tareas del hogar repartidas entre todos (niños, niñas y adultos). (2) \\"En la escuela\\": asamblea de grado votando a mano alzada, una estudiante anota en el pizarrón. (3) \\"En la comunidad\\": vecinos de todas las edades siembran arbolitos en una ladera, un joven con carretilla, una abuela con pala. Sin textos adicionales ni logotipos. Dimensiones: 1600x900."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":["fc:3.2.1"],"ambito":"conocer","prompt":"Reconoce la participación como una acción informada y compartida.","type":"explain","props":{"icon":"UsersRound","body":"Participar no es decidir por otras personas: implica informarse, expresar ideas, escuchar experiencias distintas y colaborar. Para identificar barreras escolares, se consulta a quienes recorren esos espacios."},"id":"s05-fc-1-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.1"],"ambito":"convivir","prompt":"En tu familia van a decidir qué hacer el domingo. ¿Qué acción es **participar**?","explain":"Participar no es solo estar presente: es **tomar parte** en las decisiones y en las acciones. Opinar con respeto y ayudar a organizar es participar.","type":"choice","props":{"options":[{"id":"a","text":"Dar tu idea con respeto y ayudar a preparar lo que se decida","icon":"Hand"},{"id":"b","text":"Quedarte callado y quejarte después","icon":"VolumeX","feedback":"Si no opinas en el momento, tu idea no se toma en cuenta. Quejarse después no ayuda a decidir."},{"id":"c","text":"Exigir que se haga solo lo que tú quieres","icon":"Megaphone","feedback":"Participar es aportar tu idea y escuchar las de los demás, no imponer."}],"correct":["a"]},"id":"s05-fc-1-2"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.1"],"ambito":"conocer","title":"¿Qué es participar?","prompt":"**Participar** es tomar parte en las decisiones y acciones del grupo al que perteneces. Toca cada tarjeta.","type":"explain","props":{"icon":"Hand","body":"Participar es un **derecho** (tu voz cuenta) y una **responsabilidad** (cumplir lo que el grupo acuerda).","reveal":[{"icon":"MessageCircle","front":"Un derecho","back":"La **Convención sobre los Derechos del Niño** dice que las niñas y los niños tienen derecho a **opinar y ser escuchados** en los asuntos que les afectan."},{"icon":"ListChecks","front":"Una responsabilidad","back":"Si participas en un acuerdo, te comprometes a **cumplirlo**: llegar a la jornada, hacer tu parte, respetar el resultado de una votación."},{"icon":"Users","front":"Voluntaria e incluyente","back":"Nadie debe ser obligado ni excluido. Una buena participación invita a **todas** las personas: niñas, niños, jóvenes, adultos y ancianos."},{"icon":"Brain","front":"Informada y respetuosa","back":"Antes de opinar, **infórmate**. Al opinar, **respeta** a quien piensa distinto."}]},"id":"s05-fc-1-3"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.1"],"prompt":"La participación sigue un camino. Ordena los **pasos de la participación** de un grupo que quiere mejorar algo.","hint":"No se puede opinar bien sin saber qué pasa, ni evaluar algo que aún no se ha hecho.","explain":"Informarse → opinar → proponer → decidir y actuar → evaluar. Evaluar permite empezar de nuevo, mejorando.","type":"order","props":{"labels":{"start":"Primero","end":"Al final"},"items":[{"id":"p1","text":"Informarse: ¿qué problema hay y por qué?","icon":"Search"},{"id":"p2","text":"Opinar: escuchar lo que piensa cada persona","icon":"MessageCircle"},{"id":"p3","text":"Proponer: presentar ideas de solución","icon":"Lightbulb"},{"id":"p4","text":"Decidir y actuar: elegir una idea y hacer cada quien su parte","icon":"Hammer"},{"id":"p5","text":"Evaluar: ¿funcionó?, ¿qué mejoramos?","icon":"ClipboardCheck"}]},"id":"s05-fc-1-4"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.1"],"ambito":"conocer","title":"Tres espacios para participar","prompt":"Participas en más lugares de los que crees. Toca cada espacio.","type":"explain","props":{"icon":"Home","body":"Empieza por lo cercano: la participación en casa y en la escuela te prepara para participar en tu comunidad y en tu país.","reveal":[{"icon":"Home","front":"En la familia","back":"Compartir las **tareas del hogar** entre todos (niñas y niños por igual), opinar en las decisiones familiares y cuidar a quien lo necesita."},{"icon":"School","front":"En la escuela","back":"Participar en **comisiones** (limpieza, deporte, lectura, huerto), en la **asamblea de grado** y en el **gobierno escolar**."},{"icon":"Trees","front":"En la comunidad","back":"Unirse a **jornadas** de limpieza o reforestación, a festivales culturales y a consultas del COCODE o la municipalidad."}]},"id":"s05-fc-1-5"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.1"],"prompt":"¿En qué espacio ocurre cada forma de participar?","hint":"Piensa dónde sucede: dentro de la casa, dentro de la escuela o en la aldea, barrio o municipio.","explain":"La participación empieza en la familia, sigue en la escuela y se extiende a la comunidad.","type":"sort","props":{"buckets":[{"id":"fam","label":"Familia","icon":"Home","color":"var(--c-maiz-strong)"},{"id":"esc","label":"Escuela","icon":"School","color":"var(--area-fc)"},{"id":"com","label":"Comunidad","icon":"Trees","color":"var(--c-ok)"}],"items":[{"id":"e1","text":"Turnarse para lavar los trastos después de la cena","bucket":"fam"},{"id":"e2","text":"Ser parte de la comisión de lectura del grado","bucket":"esc"},{"id":"e3","text":"Sembrar árboles en la jornada de la aldea","bucket":"com"},{"id":"e4","text":"Opinar a dónde ir de paseo con tus papás","bucket":"fam"},{"id":"e5","text":"Votar en la asamblea de grado","bucket":"esc"},{"id":"e6","text":"Responder una consulta del COCODE sobre el parque infantil","bucket":"com"}]},"id":"s05-fc-1-6"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.1"],"ambito":"hacer","title":"Ejemplo resuelto: participar para mejorar algo","prompt":"Mira cómo un grupo de niñas y niños usó los pasos de la participación.","type":"worked-example","props":{"icon":"Trash2","problem":"En la calle que lleva a la escuela de San Andrés hay basura tirada todos los días. Un grupo de 6.º grado decide hacer algo.","steps":[{"text":"**Informarse:** durante una semana anotan dónde se acumula la basura: casi toda está junto a la tienda y la parada de buses."},{"text":"**Opinar:** en la asamblea de grado cada quien da su idea; escuchan también a la señora de la tienda."},{"text":"**Proponer:** tres ideas: poner un basurero, hacer carteles y pedir a la municipalidad que pase el camión."},{"text":"**Decidir y actuar:** votan por el basurero y los carteles; la señora de la tienda se compromete a vaciarlo. Cada quien tiene una tarea.","why":"Incluir a la vecina hizo que la solución fuera de todos, no solo del grado."},{"text":"**Evaluar:** un mes después cuentan: hay mucha menos basura. Deciden pedir otro basurero en la parada."}],"answer":"Con los **cinco pasos**, el grado participó de forma **informada, incluyente y responsable**, y logró un cambio real.","tip":"Pequeñas acciones bien organizadas también transforman la comunidad."},"id":"s05-fc-1-7"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:3.2.1"],"prompt":"En una asamblea de la comunidad, el presidente dice: \\"Los jóvenes y las niñas no opinan aquí\\". ¿Qué principio de la buena participación **no** se está cumpliendo?","explain":"La participación debe ser **incluyente**: todas las personas tienen derecho a opinar sobre lo que les afecta, también la niñez y la juventud.","type":"choice","props":{"options":[{"id":"a","text":"Que sea incluyente","icon":"Users"},{"id":"b","text":"Que sea en un salón grande","icon":"Building","feedback":"El lugar no es lo importante. Fíjate en a quién se deja fuera."},{"id":"c","text":"Que sea rápida","icon":"Timer","feedback":"La rapidez no es un principio de la participación. El problema es la exclusión."}],"correct":["a"]},"id":"s05-fc-1-8"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:3.2.1"],"ambito":"convivir","prompt":"¿Qué harías tú?","type":"dilemma","props":{"scene":{"icon":"Trees","text":"El sábado hay una **jornada de reforestación** en tu aldea. Te comprometiste a ir, pero tus amigos te invitan a jugar a la misma hora."},"options":[{"id":"a","icon":"Trophy","text":"Ir a jugar sin avisar a nadie","consequence":"En la jornada faltó una persona para la tarea que te tocaba y otros tuvieron que hacerla. Tu palabra pierde valor.","values":["Irresponsabilidad"],"constructive":false},{"id":"b","icon":"Sprout","text":"Cumplir tu compromiso e invitar a tus amigos a la jornada; juegan después","consequence":"Siembran más árboles que nunca y luego juegan juntos. Tus amigos quieren volver el próximo año.","values":["Responsabilidad","Participación"],"constructive":true},{"id":"c","icon":"MessageCircle","text":"Si de verdad no puedes ir, avisar con tiempo y proponer otra forma de ayudar","consequence":"Los organizadores buscan quién te reemplace y tú ayudas a regar los arbolitos el lunes.","values":["Honestidad","Responsabilidad"],"constructive":true}]},"id":"s05-fc-1-9"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:3.2.1"],"prompt":"¿Cuál es un ejemplo de **participación social en la comunidad**?","type":"choice","props":{"options":[{"id":"a","text":"Unirse a una jornada de limpieza del río de la aldea"},{"id":"b","text":"Ver televisión toda la tarde"},{"id":"c","text":"Tirar basura en la calle"}],"correct":["a"]},"id":"s05-fc-1-10"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:3.2.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Las niñas y los niños tienen derecho a opinar sobre lo que les afecta.","answer":true},{"text":"Participar es solo estar presente en una reunión.","answer":false,"why":"Participar es tomar parte: opinar, proponer, actuar y evaluar."},{"text":"Compartir las tareas del hogar es una forma de participar en la familia.","answer":true},{"text":"El último paso de la participación es evaluar si funcionó.","answer":true}]},"id":"s05-fc-1-11"}],"kind":"materia","area":"fc","day":2}},{"missionId":"s05","version":"cnb-sexto-6d8b8911623c0039","lesson":{"id":"s05-ef-1","title":"Pasar y recibir en movimiento","icon":"Users","minutes":15,"gancho":"Si le lanzas la pelota a tu compañera justo donde está ahora, pero ella va corriendo, ¿dónde estará cuando llegue la pelota?","objetivos":["Aplicar recepción, pase adelantado y desmarque durante el movimiento"],"resumen":["Recepción: mira la pelota, brazos adelante, manos abiertas formando una \\"W\\" con pulgares e índices casi juntos; al tocarla, dobla los codos y llévala al pecho para amortiguar.","Pase adelantado: si tu compañero se mueve, lanza al espacio donde estará cuando llegue la pelota, un poco delante de él.","\\"Pasa y muévete\\": después de pasar, desplázate a un espacio libre para volver a recibir. Así el equipo avanza.","Para pasar en movimiento: mira a tu compañero, usa un pase de pecho o por arriba del hombro según la distancia, y comunícate con la voz o con la mano."],"media":{"id":"s05-ef-1-pase-adelantado","kind":"animation","title":"El pase adelantado","aspect":"16:9","duration":40,"alt":"Vista desde arriba: una niña corre en línea recta; su compañera le lanza la pelota a un punto marcado delante de ella, y la pelota y la niña llegan juntas a ese punto.","brief":"Animación 2D cenital de 40 s sobre cancha verde. (1) Error: la pasadora lanza directo a donde está la receptora que corre; la pelota llega detrás de ella (X roja). (2) Acierto: se marca un punto \\"X\\" delante de la receptora; la pelota y la receptora llegan al mismo tiempo (check verde). (3) Tras pasar, la pasadora corre a un espacio libre: rótulo \\"pasa y muévete\\". (4) Primer plano de las manos en \\"W\\" recibiendo y llevando la pelota al pecho. Rótulos grandes, sin narración obligatoria (subtítulos opcionales)."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"conocer","prompt":"Coordina mirada, desplazamiento y pase para jugar con seguridad.","type":"explain","props":{"icon":"CircleDotDashed","body":"Quien recibe muestra las manos y mira el balón; quien pasa apunta al espacio hacia donde avanza su compañero. La distancia y la fuerza se ajustan para evitar choques."},"id":"s05-ef-1-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"conocer","prompt":"Tu compañera corre hacia adelante. ¿A dónde le lanzas la pelota?","explain":"Un poco **delante** de ella: al lugar donde estará cuando llegue la pelota. Se llama **pase adelantado**.","type":"choice","props":{"options":[{"id":"a","text":"Justo donde está ahora","icon":"CircleDot","feedback":"Cuando la pelota llegue, ella ya habrá avanzado: la pelota quedará detrás."},{"id":"b","text":"Un poco delante de ella, a donde va","icon":"ArrowRight"},{"id":"c","text":"Detrás de ella, para que se regrese","icon":"ArrowLeft","feedback":"La obligarías a frenar y regresar: el equipo pierde velocidad."}],"correct":["b"]},"id":"s05-ef-1-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"hacer","title":"Recibir con seguridad","prompt":"Un buen pase necesita una buena **recepción**. Toca cada paso y practícalo con una pelota imaginaria.","type":"explain","props":{"icon":"Hand","body":"Las manos forman una **\\"W\\"**: pulgares e índices casi se tocan detrás de la pelota. Así no se escapa ni te lastima los dedos.","reveal":[{"icon":"Eye","front":"1. Mira la pelota","back":"Sigue la pelota con la vista **hasta que toque tus manos**."},{"icon":"Hand","front":"2. Manos en \\"W\\"","back":"Brazos adelante, dedos abiertos y relajados, pulgares e índices formando una **W**. Si la pelota viene baja, las manos apuntan hacia abajo."},{"icon":"ArrowDown","front":"3. Amortigua","back":"Al tocarla, **dobla los codos** y lleva la pelota al pecho, como si atraparas un huevo."},{"icon":"Shield","front":"4. Protege","back":"Sujétala con firmeza y gira el cuerpo para alejarla de los defensores."}]},"id":"s05-ef-1-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"hacer","title":"Pasar en movimiento","prompt":"En un juego casi nadie está quieto. Mira la animación y toca cada tarjeta.","type":"explain","props":{"icon":"Route","body":"Pasar en movimiento combina **desplazarse**, **lanzar** y **recibir**: es una habilidad genérica como las de la semana 2.","reveal":[{"icon":"ArrowRight","front":"Pase adelantado","back":"Lanza **al espacio** donde estará tu compañero, un poco delante de él y a la altura del pecho."},{"icon":"Route","front":"Pasa y muévete","back":"Después de pasar, **no te detengas**: corre a un espacio libre donde puedas volver a recibir."},{"icon":"MessageCircle","front":"Comunícate","back":"Pide la pelota con la **voz** (\\"¡aquí!\\") o levantando la mano. Llama por su nombre a quien le pasas."},{"icon":"Gauge","front":"Fuerza justa","back":"Si tu compañero está cerca, pase suave de pecho; si está lejos, por arriba del hombro. Una pelota demasiado fuerte es difícil de recibir."}]},"id":"s05-ef-1-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"hacer","title":"Ejemplo resuelto: el pase en la carrera","prompt":"Mira cómo Diego y Rosa avanzan por la cancha pasándose la pelota.","type":"worked-example","props":{"icon":"Users","problem":"Diego y Rosa corren en paralelo, separados por 4 pasos, de una línea a otra de la cancha. Deben llegar al final sin que la pelota caiga.","steps":[{"text":"Diego tiene la pelota. **Mira** a Rosa y ve que va un poco adelantada."},{"text":"Lanza un **pase de pecho** suave, **un paso delante** de Rosa, a la altura de su pecho.","why":"Es el pase adelantado: la pelota y Rosa llegan juntas."},{"text":"Rosa recibe con las manos en **\\"W\\"** y amortigua llevando la pelota al pecho, sin dejar de trotar (máximo 3 pasos con la pelota, como verás el viernes)."},{"text":"Diego, que ya pasó, **acelera** para ponerse otra vez a la par y pedir la pelota: \\"¡Rosa!\\".","why":"\\"Pasa y muévete\\": así siempre hay a quién pasar."}],"answer":"Con **pases adelantados**, **recepción en W** y **pasa y muévete**, avanzan sin que caiga la pelota.","tip":"Empiecen caminando, luego trotando y al final corriendo."},"id":"s05-ef-1-5"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"hacer","prompt":"Ordena los pasos para **recibir** bien la pelota.","hint":"Primero los ojos, luego las manos, después los codos.","explain":"Mirar la pelota → manos en W → tocar y doblar los codos → llevarla al pecho y protegerla.","type":"order","props":{"items":[{"id":"a","text":"Mirar la pelota hasta que llegue"},{"id":"b","text":"Poner los brazos adelante con las manos en \\"W\\""},{"id":"c","text":"Doblar los codos al tocarla para amortiguar"},{"id":"d","text":"Llevarla al pecho y protegerla"}],"labels":{"start":"Primero","end":"Al final"}},"id":"s05-ef-1-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"hacer","prompt":"Usen una pelota suave y cuatro marcas separadas. **Calentamiento breve:** caminen, movilicen hombros y muñecas y ensayen la recepción en W sin pelota. **Prueba bilateral y recorrido cooperativo:** en parejas completen **6 pases adelantados totales** entre las marcas: 3 caminando y 3 trotando. Repartan las recepciones de forma bilateral; después de cada pase, quien lanzó se mueve a la siguiente marca libre. Trabajen sin defensa ni tanteo: si la pelota cae, recuperen el control y continúen desde la marca anterior. Ajusten distancia, velocidad y tamaño de pelota para que ambas personas participen con seguridad. **Vuelta a la calma:** caminen, respiren y relajen brazos.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después de caminar","exercise":{"name":"Recepción y pase bilateral","icon":"Users","seconds":60}},{"label":"Después del recorrido","exercise":{"name":"Circuito cooperativo: pasa y muévete","icon":"Route","seconds":90}}]},"id":"s05-ef-1-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"hacer","prompt":"En un recorrido cooperativo, Juan pasa la pelota y se queda quieto mirando. Su pareja llega a la siguiente marca sin una opción libre. ¿Qué debió hacer Juan?","explain":"Después de pasar hay que **moverse a un espacio libre** para ofrecer una nueva opción de pase.","type":"choice","props":{"options":[{"id":"a","text":"Moverse a un espacio libre y pedir la pelota"},{"id":"b","text":"Pararse junto a quien tiene la pelota","feedback":"Si está pegado, el defensor cubre a los dos a la vez."},{"id":"c","text":"Quedarse quieto para no cansarse","feedback":"Sin movimiento no hay opciones de pase."}],"correct":["a"]},"id":"s05-ef-1-8"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:2.1.5"],"ambito":"hacer","prompt":"Cuando recibe, a Sara la pelota le \\"rebota\\" en las manos y se le cae. Tiene los brazos rígidos y los dedos juntos. ¿Qué le aconsejas?","explain":"Dedos abiertos en \\"W\\" y codos que se doblan al tocar la pelota: así la frena poco a poco, como un colchón.","type":"choice","props":{"options":[{"id":"a","text":"Abrir los dedos en \\"W\\" y doblar los codos al recibir"},{"id":"b","text":"Recibir con los brazos todavía más duros","feedback":"Los brazos rígidos hacen que la pelota rebote."},{"id":"c","text":"Cerrar los ojos al recibir","feedback":"Hay que mirar la pelota hasta que llegue a las manos."}],"correct":["a"]},"id":"s05-ef-1-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:2.1.5"],"prompt":"Clasifica cada acción al pasar y recibir en movimiento: ¿es **correcta** o un **error**?","type":"sort","props":{"buckets":[{"id":"ok","label":"Correcta","icon":"Check","color":"var(--c-ok)"},{"id":"no","label":"Error","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"y1","text":"Lanzar un paso delante de un compañero que corre","bucket":"ok"},{"id":"y2","text":"Lanzar justo a donde está ahora un compañero que corre","bucket":"no"},{"id":"y3","text":"Recibir con los brazos rígidos y los dedos juntos","bucket":"no"},{"id":"y4","text":"Doblar los codos al tocar la pelota","bucket":"ok"}]},"id":"s05-ef-1-10"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:2.1.5"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Después de pasar la pelota conviene moverse a un espacio libre.","answer":true},{"text":"Para recibir, las manos forman una \\"W\\" y los codos se doblan para amortiguar.","answer":true},{"text":"Un pase muy fuerte a alguien que está cerca es más fácil de recibir.","answer":false,"why":"De cerca se usa un pase suave; uno muy fuerte es difícil de controlar."}]},"id":"s05-ef-1-11"}],"kind":"materia","area":"ef","day":2}},{"missionId":"s05","version":"cnb-sexto-6be4ef1a7a20131b","lesson":{"id":"s05-l2-1","title":"Contamos un cuento con el cuerpo","icon":"Drama","minutes":15,"gancho":"Sin decir una sola palabra, ¿podrías hacer que tu familia adivine que eres un abuelito que camina contra el viento?","objetivos":["Representar corporalmente un cuento con una secuencia narrativa clara"],"resumen":["Para representar sin palabras usamos: postura (cómo está el cuerpo), expresión de la cara, gestos, desplazamientos y ritmo o danza.","Cada personaje tiene su forma de moverse: un anciano camina lento; un niño corre y salta; el viento se mueve con giros.","Una representación sigue el orden del cuento: inicio, nudo (problema) y desenlace (solución).","En una dramatización hay muchos papeles (actores, narrador, música, escenografía). Participar es voluntario y todos pueden aportar desde el papel que elijan."],"media":{"id":"s05-l2-1-mimo","kind":"video","title":"El sombrero de don Chepe, sin palabras","aspect":"16:9","duration":60,"alt":"Tres estudiantes representan sin palabras un cuento: un anciano pierde su sombrero con el viento, una niña lo rescata del río y todos bailan al final.","brief":"Video de 60 s en un patio escolar o salón comunal. Tres estudiantes (dos niñas y un niño) representan sin hablar \\"El sombrero de don Chepe\\". Inicio: el niño, encorvado y con bastón, camina lento y feliz tocándose un sombrero de palma. Nudo: una niña hace de viento (giros con los brazos abiertos, pasos rápidos); el sombrero \\"vuela\\" (se lo quita y lo pasa); don Chepe lo persigue con cara de angustia; el sombrero cae al río (tela azul en el suelo). Desenlace: otra niña con una vara lo pesca y se lo devuelve; los tres bailan unos pasos sencillos de son al ritmo de una marimba suave (música sin derechos o grabada para el proyecto). Cámara fija, plano general, subtítulos \\"Inicio – Nudo – Desenlace\\"."},"steps":[{"fase":"explorar","areas":["l2"],"cnb":["l2:2.2.5"],"ambito":"conocer","prompt":"Lee postura, gesto y movimiento como partes de un relato.","type":"explain","props":{"icon":"PersonStanding","body":"El lenguaje corporal comunica sin palabras: la postura muestra actitud, el gesto expresa emoción y el movimiento organiza acciones. Una secuencia clara permite reconocer inicio, problema y desenlace."},"id":"s05-l2-1-1"},{"fase":"construir","areas":["l2"],"cnb":["l2:2.2.5"],"ambito":"conocer","prompt":"Sin palabras, quieres mostrar que eres un **abuelito cansado**. ¿Qué harías con tu cuerpo?","explain":"La **postura** (encorvado) y el **ritmo** (lento) bastan para que todos entiendan quién eres. Hoy aprenderás a contar un cuento completo con el cuerpo.","type":"choice","props":{"options":[{"id":"a","text":"Caminar lento, un poco encorvado, apoyado en un bastón imaginario","icon":"PersonStanding"},{"id":"b","text":"Correr y saltar por todo el espacio","icon":"Rabbit","feedback":"Así se movería un personaje joven y lleno de energía."},{"id":"c","text":"Quedarme de pie sin moverme","icon":"User","feedback":"Sin movimiento, el público no tiene pistas sobre el personaje."}],"correct":["a"]},"id":"s05-l2-1-2"},{"fase":"construir","areas":["l2"],"cnb":["l2:2.2.5"],"ambito":"conocer","title":"Herramientas del lenguaje corporal","prompt":"Cuando representamos un cuento **sin palabras** o con pocas palabras, el cuerpo se vuelve el narrador. Toca cada herramienta.","type":"explain","props":{"icon":"PersonStanding","body":"Exagera un poco los movimientos: el público debe verlos desde lejos.","reveal":[{"icon":"PersonStanding","front":"Postura","back":"Cómo se para o se sienta el personaje: **erguido** (seguro, orgulloso), **encorvado** (cansado, anciano), **encogido** (miedo, frío)."},{"icon":"Smile","front":"Expresión","back":"La cara muestra lo que siente: alegría, susto, tristeza, sorpresa."},{"icon":"Hand","front":"Gestos","back":"Acciones con las manos: agarrar, buscar, llamar, señalar."},{"icon":"Footprints","front":"Desplazamientos","back":"Cómo y hacia dónde se mueve: lento, rápido, en círculo, de puntillas."},{"icon":"Music","front":"Ritmo y danza","back":"Movimientos con música que muestran un ambiente: una fiesta, una tormenta, la alegría del final."}]},"id":"s05-l2-1-3"},{"fase":"construir","areas":["l2"],"cnb":["l2:2.2.5"],"ambito":"conocer","title":"Lectura","prompt":"Lee el cuento que vamos a representar. Mientras lees, imagina cómo se movería cada personaje.","type":"reading","props":{"genre":"Cuento","heading":"El sombrero de don Chepe","passage":"Don Chepe tenía ochenta años y un sombrero de palma que cuidaba como un tesoro. Cada domingo caminaba despacio hacia el mercado, con su bastón en una mano y la otra en el ala del sombrero.\\n\\nUn domingo sopló un viento terrible. ¡Fuuu! El sombrero salió volando, dio tres vueltas en el aire y cayó en el río. Don Chepe corrió como pudo, con los ojos muy abiertos y las manos estiradas, pero el agua se llevaba su tesoro.\\n\\nEntonces apareció Maribel, una niña que pescaba en la orilla. Con su vara larga alcanzó el sombrero y se lo devolvió, mojado pero entero. Don Chepe se lo puso, sonrió y, de pura alegría, se puso a bailar un son. Maribel bailó con él.","questions":[{"q":"¿Qué **postura** y **ritmo** conviene para don Chepe al inicio?","options":[{"id":"a","text":"Un poco encorvado y lento, con bastón"},{"id":"b","text":"Erguido, corriendo y saltando"},{"id":"c","text":"Sentado todo el tiempo"}],"correct":"a","why":"Tiene ochenta años y \\"caminaba despacio\\": la postura y el ritmo lo muestran."},{"q":"¿Cómo se representaría el **viento** sin palabras?","options":[{"id":"a","text":"Con giros rápidos, brazos abiertos y soplidos"},{"id":"b","text":"Quedándose quieto en una esquina"},{"id":"c","text":"Leyendo la palabra \\"viento\\" en un cartel"}],"correct":"a","why":"Los desplazamientos rápidos y en círculo imitan el viento. El cuento dice que el sombrero \\"dio tres vueltas\\"."},{"q":"¿Qué parte del cuento es el **desenlace**?","options":[{"id":"a","text":"Maribel rescata el sombrero y bailan de alegría"},{"id":"b","text":"Don Chepe camina al mercado"},{"id":"c","text":"El viento se lleva el sombrero"}],"correct":"a","why":"El desenlace es la solución del problema. La danza final expresa la alegría."}]},"id":"s05-l2-1-4"},{"fase":"construir","areas":["l2"],"cnb":["l2:2.2.5"],"ambito":"hacer","prompt":"Ahora tú, con ayuda: une cada momento del cuento con el lenguaje corporal que lo representa.","hint":"Piensa qué siente o hace el personaje en cada momento: ¿alegría, angustia, esfuerzo?","explain":"Cada momento tiene su emoción y su movimiento. Así el público sigue la historia sin palabras.","type":"match","props":{"leftTitle":"Momento","rightTitle":"Lenguaje corporal","pairs":[{"id":"k1","left":"El sombrero sale volando","leftIcon":"Wind","right":"Mirar hacia arriba, boca abierta, manos estiradas"},{"id":"k2","left":"Don Chepe persigue su sombrero","leftIcon":"Footprints","right":"Pasos rápidos pero torpes, cara de angustia"},{"id":"k3","left":"Maribel alcanza el sombrero","leftIcon":"Fish","right":"Estirarse con la vara, esfuerzo y luego una sonrisa"},{"id":"k4","left":"Final feliz","leftIcon":"Music","right":"Bailar un son con pasos alegres"}]},"id":"s05-l2-1-5"},{"fase":"construir","areas":["l2"],"cnb":["l2:2.2.5"],"ambito":"hacer","title":"Ejemplo resuelto","prompt":"Mira cómo un grupo de sexto planifica la representación en solo 10 minutos.","type":"worked-example","props":{"icon":"ClipboardList","problem":"El grupo de Ixchel debe representar \\"El sombrero de don Chepe\\" sin palabras, en 2 minutos. ¿Cómo se organizan?","steps":[{"text":"Dividen el cuento en **tres escenas**: inicio (don Chepe camina), nudo (el viento y el río) y desenlace (el rescate y el baile).","why":"Si el orden está claro, el público entiende la historia."},{"text":"Reparten papeles: don Chepe, el viento, Maribel. Una compañera que prefiere no actuar **toca la música** con una botella con semillas."},{"text":"Eligen el movimiento clave de cada personaje: bastón y pasos lentos; giros y soplidos; la vara que pesca."},{"text":"Ensayan dos veces: la primera, despacio; la segunda, con música y exagerando un poco los gestos."}],"answer":"Organizaron **escenas**, **papeles** y **movimientos clave**, y ensayaron antes de presentar.","tip":"Una representación sin palabras necesita movimientos claros y un orden fácil de seguir."},"id":"s05-l2-1-6"},{"fase":"construir","areas":["l2"],"cnb":["l2:2.2.3"],"ambito":"convivir","title":"Todos podemos participar","prompt":"Participar en una dramatización es **voluntario**: nadie debe ser obligado ni burlado. Hay un papel para cada quien. Toca cada tarjeta.","type":"explain","props":{"icon":"Users","body":"Sentir nervios es normal, incluso para actores con experiencia. Respirar hondo y ensayar ayuda mucho.","reveal":[{"icon":"Drama","front":"Actor o actriz","back":"Representa a un personaje con su cuerpo y su voz."},{"icon":"Mic","front":"Narrador","back":"Cuenta en voz alta lo que pasa, si la obra lleva palabras."},{"icon":"Drum","front":"Música y sonidos","back":"Crea el ambiente: lluvia con semillas, viento con la voz, marimba o tambor."},{"icon":"Palette","front":"Escenografía","back":"Prepara los objetos: la tela azul del río, el sombrero, la vara."},{"icon":"Heart","front":"Público respetuoso","back":"Mira con atención, no se burla y aplaude al final. ¡También es participar!"}]},"id":"s05-l2-1-7"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:2.2.5"],"ambito":"hacer","prompt":"Para representar el cuento, las escenas deben ir en orden. Ordénalas.","explain":"Inicio → nudo (problema) → desenlace (solución). Si cambias el orden, el público se confunde.","type":"order","props":{"labels":{"start":"Inicio","end":"Desenlace"},"items":[{"id":"c1","text":"Don Chepe camina despacio al mercado con su sombrero","icon":"PersonStanding"},{"id":"c2","text":"El viento sopla y se lleva el sombrero","icon":"Wind"},{"id":"c3","text":"El sombrero cae al río y don Chepe lo persigue","icon":"Waves"},{"id":"c4","text":"Maribel lo pesca con su vara y se lo devuelve","icon":"Fish"},{"id":"c5","text":"Don Chepe y Maribel bailan un son de alegría","icon":"Music"}]},"id":"s05-l2-1-8"},{"fase":"aplicar","areas":["l2","fc"],"cnb":["l2:2.2.3"],"ambito":"convivir","prompt":"¿Qué harías tú?","type":"dilemma","props":{"scene":{"icon":"Drama","text":"Tu grupo prepara la dramatización. Tomás, que es tímido, dice que no quiere actuar. Otro compañero dice: \\"Entonces que no haga nada, o que actúe a la fuerza\\"."},"options":[{"id":"a","icon":"Megaphone","text":"Obligar a Tomás a actuar frente a todos","consequence":"Tomás se pone muy nervioso y la pasa mal. Participar debe ser voluntario.","values":["Presión"],"constructive":false},{"id":"b","icon":"HeartHandshake","text":"Preguntarle a Tomás qué le gustaría hacer: música, escenografía o narrar","consequence":"Tomás elige hacer la música con semillas y lo hace muy bien. Todos aportan desde el papel que eligieron.","values":["Respeto","Inclusión","Trabajo en equipo"],"constructive":true},{"id":"c","icon":"EyeOff","text":"Dejarlo fuera del grupo sin preguntarle nada","consequence":"Tomás se siente excluido. Siempre hay una forma de participar.","values":["Exclusión"],"constructive":false}]},"id":"s05-l2-1-9"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:2.2.5"],"ambito":"hacer","prompt":"En otra obra, un personaje recibe una **noticia muy triste**. ¿Qué lenguaje corporal la representa mejor sin palabras?","explain":"Hombros caídos, cabeza baja y movimientos lentos comunican tristeza con claridad.","type":"choice","props":{"options":[{"id":"a","text":"Bajar los hombros y la cabeza, cubrirse la cara con las manos y caminar lento"},{"id":"b","text":"Saltar y aplaudir","feedback":"Saltar y aplaudir comunica alegría, lo contrario."},{"id":"c","text":"Pararse muy erguido y sonreír","feedback":"La postura erguida y la sonrisa comunican seguridad o alegría."}],"correct":["a"]},"id":"s05-l2-1-10"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:2.2.5"],"prompt":"Boleto de salida: en una secuencia de lenguaje corporal sin palabras, ¿qué muestra que un personaje tiene **mucho frío**?","type":"choice","props":{"options":[{"id":"a","text":"Encogerse, abrazarse y temblar"},{"id":"b","text":"Abanicarse la cara"},{"id":"c","text":"Estirarse y bostezar"}],"correct":["a"]},"id":"s05-l2-1-11"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:2.2.3","l2:2.2.5"],"prompt":"Comprueba la secuencia narrativa y el lenguaje corporal: ¿verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Solo participa en una dramatización quien actúa frente al público.","answer":false,"why":"La música, la escenografía y la narración también son formas de participar."},{"text":"La danza puede expresar la alegría del final de un cuento.","answer":true},{"text":"Una representación debe seguir el orden: inicio, nudo y desenlace.","answer":true}]},"id":"s05-l2-1-12"}],"kind":"materia","area":"l2","day":2}},{"missionId":"s05","version":"cnb-sexto-134b83d23a5ce3c4","lesson":{"id":"s05-l1-4","title":"El género de las palabras: masculino y femenino","icon":"Users","minutes":14,"gancho":"Se dice \\"el mapa\\" aunque termina en -a, y \\"la mano\\" aunque termina en -o. ¿Entonces cómo sabemos el género de una palabra?","objetivos":["Aplicar la concordancia de género entre artículo, sustantivo y adjetivo"],"resumen":["Todo sustantivo en español tiene género: masculino (el, un) o femenino (la, una). El artículo es la mejor pista: el mapa, la mano.","El femenino se forma cambiando la terminación (niño/niña, doctor/doctora, alcalde/alcaldesa, rey/reina), con una palabra distinta (padre/madre, caballo/yegua) o solo cambiando el artículo (el estudiante/la estudiante).","Concordancia de género: el artículo y los adjetivos toman el mismo género que el sustantivo: la mano derecha, el mapa antiguo.","Palabras femeninas que empiezan con \\"a\\" tónica llevan \\"el\\" en singular, pero siguen siendo femeninas: el agua fría, el águila blanca."],"media":{"id":"s05-l1-4-genero","kind":"diagram","title":"Cuatro formas de hacer el femenino","aspect":"16:9","alt":"Cuadro de cuatro columnas con ejemplos: cambia la terminación (niño-niña, profesor-profesora), terminación especial (alcalde-alcaldesa, actor-actriz, gallo-gallina), palabra distinta (padre-madre, toro-vaca) y solo cambia el artículo (el estudiante-la estudiante).","brief":"Infografía horizontal en cuatro columnas de colores, cada una con un título y dos o tres pares de dibujos sencillos con su palabra: 1) \\"Cambia la terminación\\": niño/niña, profesor/profesora. 2) \\"Terminación especial\\": alcalde/alcaldesa, actor/actriz, gallo/gallina. 3) \\"Palabra distinta\\": padre/madre, toro/vaca. 4) \\"Solo cambia el artículo\\": el estudiante/la estudiante, el artista/la artista. Personajes diversos (maya, garífuna, ladino), sin estereotipos. Letra grande. Dimensiones: 1600x900."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:7.1.2"],"ambito":"conocer","prompt":"Observa cómo el género se expresa en sustantivos y palabras relacionadas.","type":"explain","props":{"icon":"Languages","body":"El género gramatical puede ser masculino o femenino y se refleja en la concordancia: el maestro atento, la maestra atenta. No describe por sí solo las capacidades de una persona."},"id":"s05-l1-4-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:7.1.2"],"ambito":"conocer","prompt":"¿Cuál expresión está **bien dicha**?","explain":"\\"Mapa\\" es masculino aunque termine en -a: se dice **el mapa antiguo**. La terminación no siempre indica el género; el artículo sí.","type":"choice","props":{"options":[{"id":"a","text":"el mapa antiguo","icon":"Map"},{"id":"b","text":"la mapa antigua","icon":"Map","feedback":"Suena raro, ¿verdad? \\"Mapa\\" es masculino: el mapa."},{"id":"c","text":"el mapa antigua","icon":"Map","feedback":"El artículo y el adjetivo deben tener el mismo género: el mapa antigu**o**."}],"correct":["a"]},"id":"s05-l1-4-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:7.1.2"],"ambito":"conocer","title":"¿Qué es el género?","prompt":"En español, **todos los sustantivos** tienen género: **masculino** o **femenino**. Toca cada tarjeta.","type":"explain","props":{"icon":"Users","body":"En las cosas, el género es una marca **de la palabra**, no del objeto: la mesa no es \\"mujer\\" ni el lápiz es \\"hombre\\".","reveal":[{"icon":"Type","front":"La pista del artículo","back":"Pon **el** o **la** delante: _el sombrero, la milpa, el día, la mano_. El artículo que suena bien te dice el género."},{"icon":"AlertTriangle","front":"Terminaciones engañosas","back":"Muchas palabras en **-o** son masculinas y en **-a** femeninas, pero no todas: _el mapa, el día, el problema, el tema, la mano, la radio_."},{"icon":"Droplet","front":"El agua, el águila","back":"Las palabras femeninas que empiezan con **a** o **ha** tónica usan **el** en singular para que suene mejor: _el agua, el águila, el hacha_. Pero siguen siendo **femeninas**: el agua **fría**, las aguas **limpias**."}]},"id":"s05-l1-4-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:7.1.2"],"ambito":"conocer","title":"Cómo se forma el femenino","prompt":"Cuando un sustantivo nombra personas o animales, suele tener forma masculina y femenina. Observa el diagrama y toca cada tarjeta.","type":"explain","props":{"icon":"Shuffle","body":"Hay cuatro caminos. Si dudas, consulta el diccionario.","reveal":[{"icon":"RefreshCw","front":"Cambia la terminación","back":"-o → -a: _niño/niña, abuelo/abuela_. Consonante + a: _profesor/profesora, doctor/doctora_. También _presidente/presidenta_."},{"icon":"Sparkles","front":"Terminación especial","back":"_alcalde/alcaldesa, actor/actriz, rey/reina, gallo/gallina, héroe/heroína_."},{"icon":"Repeat","front":"Palabra distinta","back":"_padre/madre, hombre/mujer, yerno/nuera, caballo/yegua, toro/vaca_."},{"icon":"Type","front":"Solo cambia el artículo","back":"_el/la estudiante, el/la artista, el/la joven, el/la guía_. La palabra es igual; el artículo y los adjetivos muestran el género: \\"la estudiante aplicad**a**\\"."}]},"id":"s05-l1-4-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:7.1.2"],"ambito":"hacer","title":"Ejemplo resuelto: cambiar una oración a femenino","prompt":"Cuando cambias el género de un sustantivo, **todo lo que lo acompaña** debe cambiar también. Míralo.","type":"worked-example","props":{"icon":"RefreshCw","problem":"Cambia a femenino: \\"**El nuevo alcalde** saludó a **los artistas invitados**.\\" (Todos los artistas invitados son mujeres).","steps":[{"text":"_alcalde_ tiene terminación especial → **alcaldesa**."},{"text":"Lo que acompaña a alcaldesa cambia: _el nuevo_ → **la nueva**.","why":"El artículo y el adjetivo concuerdan con el sustantivo."},{"text":"_artistas_ no cambia de forma (solo el artículo): **las artistas**."},{"text":"El adjetivo concuerda: _invitados_ → **invitadas**."}],"answer":"\\"**La nueva alcaldesa** saludó a **las artistas invitadas**.\\"","tip":"Busca el sustantivo y luego revisa su \\"familia\\": artículo, adjetivos y participios (invitado, elegido…)."},"id":"s05-l1-4-5"},{"fase":"construir","areas":["l1"],"cnb":["l1:7.1.2"],"ambito":"hacer","prompt":"Une cada masculino con su femenino.","hint":"Algunos cambian la terminación y otros son palabras distintas.","explain":"Comprueba cada pareja y observa si cambia la terminación, toda la palabra o solo el artículo.","type":"match","props":{"leftTitle":"Masculino","rightTitle":"Femenino","pairs":[{"id":"g1","left":"el yerno","right":"la nuera"},{"id":"g2","left":"el actor","right":"la actriz"},{"id":"g3","left":"el gallo","right":"la gallina"},{"id":"g4","left":"el caballo","right":"la yegua"},{"id":"g5","left":"el héroe","right":"la heroína"},{"id":"g6","left":"el tejedor","right":"la tejedora"}]},"id":"s05-l1-4-6"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:7.1.2"],"ambito":"hacer","prompt":"¿Cómo se forma el femenino de cada palabra?","explain":"Guía y testigo no cambian: solo el artículo. Padre y toro cambian de palabra. Maestro y señor cambian la terminación.","type":"sort","props":{"buckets":[{"id":"term","label":"Cambia la terminación","icon":"RefreshCw","color":"var(--area-l1)"},{"id":"dist","label":"Palabra distinta","icon":"Repeat","color":"var(--c-maiz-strong)"},{"id":"art","label":"Solo cambia el artículo","icon":"Type","color":"var(--c-ok)"}],"items":[{"id":"s1","text":"maestro","bucket":"term"},{"id":"s2","text":"padre","bucket":"dist"},{"id":"s3","text":"guía","bucket":"art"},{"id":"s4","text":"señor","bucket":"term"},{"id":"s5","text":"toro","bucket":"dist"},{"id":"s6","text":"testigo","bucket":"art","feedback":"Se dice \\"el testigo\\" y \\"la testigo\\": solo cambia el artículo."}]},"id":"s05-l1-4-7"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:7.1.2"],"ambito":"hacer","prompt":"Completa el texto con la forma que **concuerda en género** con el sustantivo.","explain":"El agua es femenina: \\"fría\\". La mano es femenina: \\"arrugada\\". El mapa y el día son masculinos: \\"viejo\\", \\"soleado\\". La guía (mujer): \\"amable\\".","type":"fill-blank","props":{"text":"Mi abuela lava el maíz con el agua [[fría]] del nacimiento. Con la mano [[arrugada]] me muestra un mapa [[viejo]] de la aldea. Era un día [[soleado]] y la guía del grupo, muy [[amable]], nos esperaba.","distractors":["frío","arrugado","vieja","soleada"]},"id":"s05-l1-4-8"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:7.1.2"],"ambito":"hacer","prompt":"Una de estas oraciones tiene un **error de concordancia de género**. ¿Cuál?","explain":"\\"Problema\\" es masculino: se dice \\"**un** problema **serio**\\". Las otras oraciones concuerdan bien.","type":"choice","props":{"options":[{"id":"a","text":"Tenemos una problema seria con el agua."},{"id":"b","text":"El águila blanca voló sobre el cerro.","feedback":"Está bien: \\"águila\\" es femenina aunque lleve \\"el\\"; por eso \\"blanca\\"."},{"id":"c","text":"La joven artista pintó un mural.","feedback":"Está bien: \\"joven\\" y \\"artista\\" usan el artículo para marcar el femenino."}],"correct":["a"]},"id":"s05-l1-4-9"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:7.1.2"],"prompt":"Para mantener la concordancia de género, ¿cuál es el femenino de \\"**el rey**\\"?","type":"choice","props":{"options":[{"id":"a","text":"la reina"},{"id":"b","text":"la reya"},{"id":"c","text":"la rey"}],"correct":["a"]},"id":"s05-l1-4-10"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:7.1.2"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"\\"El día\\" es masculino aunque termine en -a.","answer":true},{"text":"Se escribe \\"el agua frío\\" porque el artículo es \\"el\\".","answer":false,"why":"\\"Agua\\" es femenina: el agua fría."},{"text":"En \\"la estudiante\\", el género se nota por el artículo.","answer":true}]},"id":"s05-l1-4-11"}],"kind":"materia","area":"l1","day":4}},{"missionId":"s05","version":"cnb-sexto-1510ee1ca016a26d","lesson":{"id":"s05-l3-2","title":"How is it? How do you do it? Adjectives and adverbs","icon":"Palette","minutes":15,"gancho":"En español decimos \\"una casa grande\\". En inglés, ¿será \\"a house big\\" o \\"a big house\\"?","objetivos":["Construir oraciones en inglés con adjetivos y adverbios en orden correcto"],"resumen":["El adjetivo describe al sustantivo y va ANTES de él: a red backpack, a tall volcano. Nunca lleva plural: two big dogs.","El adjetivo también va después de is / are: The house is big.","El adverbio dice CÓMO se hace la acción. Muchos se forman con -ly: slow → slowly, quiet → quietly, careful → carefully.","Algunos adverbios son especiales: fast (rápido) y well (bien). El adverbio suele ir al final: She sings beautifully."],"media":{"id":"s05-l3-2-turtle","kind":"animation","title":"The fast rabbit and the slow turtle","aspect":"16:9","duration":45,"alt":"Un conejo café corre rápido y una tortuga verde camina despacio; aparecen oraciones con adjetivos y adverbios.","brief":"Animación 2D de 45 s en un camino de tierra junto a una milpa. Un conejo café pequeño y una tortuga verde grande. Aparece el texto \\"a small brown rabbit\\" con \\"small\\" y \\"brown\\" subrayados en verde (adjetivos, antes del sustantivo). Luego el conejo corre: \\"The rabbit runs fast.\\" con \\"fast\\" en morado (adverbio). La tortuga avanza: \\"The turtle walks slowly.\\" con \\"slowly\\" en morado. Cierre: la tortuga llega con calma: \\"The turtle walks carefully.\\" Narración en inglés lento con subtítulos en español."},"steps":[{"fase":"explorar","areas":["l3"],"cnb":["l3:2.2.3"],"ambito":"conocer","prompt":"Choose whether a word describes a noun or an action.","type":"explain","props":{"icon":"Gauge","body":"An adjective describes a noun: a clear sign. An adverb describes how an action happens: read carefully. Many English adverbs end in -ly, but some, such as fast, do not."},"id":"s05-l3-2-1"},{"fase":"construir","areas":["l3"],"cnb":["l3:2.2.3"],"ambito":"conocer","prompt":"¿Cómo se dice **\\"una casa grande\\"** en inglés?","explain":"En inglés el adjetivo va **antes** del sustantivo: **a big house**. Es al revés que en español. Hoy aprenderás dónde van los adjetivos y los adverbios.","type":"choice","props":{"options":[{"id":"a","text":"a house big","icon":"Home","feedback":"Así lo diríamos en español. En inglés el adjetivo va antes."},{"id":"b","text":"a big house","icon":"Home"},{"id":"c","text":"a bigs house","icon":"Home","feedback":"En inglés los adjetivos nunca llevan -s."}],"correct":["b"]},"id":"s05-l3-2-2"},{"fase":"construir","areas":["l3"],"cnb":["l3:2.2.3"],"ambito":"conocer","title":"Adjectives","prompt":"Los **adjetivos** dicen **cómo es** algo. Toca cada tarjeta.","type":"explain","props":{"icon":"Palette","body":"Adjetivos útiles: big, small, tall, red, blue, green, happy, beautiful, delicious, old, new.","reveal":[{"icon":"ArrowRight","front":"Antes del sustantivo","back":"a **red** backpack (una mochila roja) · a **tall** volcano (un volcán alto) · **delicious** tamales."},{"icon":"Minus","front":"Sin plural","back":"Español: dos perros grande**s**. Inglés: two **big** dogs. El adjetivo **no cambia**."},{"icon":"Equal","front":"Después de is / are","back":"The volcano **is tall**. The tamales **are delicious**."}]},"id":"s05-l3-2-3"},{"fase":"construir","areas":["l3"],"cnb":["l3:2.2.3"],"ambito":"conocer","title":"Adverbs","prompt":"Los **adverbios** dicen **cómo se hace una acción**. Mira la animación de la lección y toca cada tarjeta.","type":"explain","props":{"icon":"Zap","body":"El adjetivo acompaña a una **cosa**; el adverbio acompaña a una **acción**. Compara: _a **slow** turtle_ (adjetivo) / _it walks **slowly**_ (adverbio).","reveal":[{"icon":"Plus","front":"Adjetivo + ly","back":"slow → **slowly** (despacio) · quiet → **quietly** (en silencio) · careful → **carefully** (con cuidado) · beautiful → **beautifully** (hermosamente)"},{"icon":"Rabbit","front":"Especiales","back":"**fast** (rápido) no cambia: _He runs **fast**._ · good → **well** (bien): _She sings **well**._"},{"icon":"ListOrdered","front":"¿Dónde va?","back":"Casi siempre **al final**, después del verbo o de la cosa: _She sings **beautifully**._ · _He reads the book **slowly**._"}]},"id":"s05-l3-2-4"},{"fase":"construir","areas":["l3"],"cnb":["l3:2.2.3"],"ambito":"hacer","title":"Worked example","prompt":"Mira cómo se arma una oración con todas las piezas.","type":"worked-example","props":{"icon":"Blocks","problem":"¿Cómo se dice: \\"Mi abuela hace tamales deliciosos con cuidado\\"?","steps":[{"text":"Quién: **My grandmother** (she)."},{"text":"Qué hace: make → **makes** (con -s, porque es \\"she\\")."},{"text":"Qué cosa, con su adjetivo **antes**: **delicious tamales**.","why":"El adjetivo va antes del sustantivo y no lleva plural."},{"text":"Cómo lo hace: careful + ly → **carefully**, al final."}],"answer":"**My grandmother makes delicious tamales carefully.**","tip":"Quién + verbo + (adjetivo + sustantivo) + adverbio."},"id":"s05-l3-2-5"},{"fase":"construir","areas":["l3"],"cnb":["l3:2.2.3"],"ambito":"hacer","prompt":"Ahora tú, con ayuda: ¿es un **adjetivo** (cómo es algo) o un **adverbio** (cómo se hace)?","hint":"Muchos adverbios terminan en -ly. Recuerda también los especiales: fast y well.","explain":"Adjectives: big, happy, red, slow. Adverbs: slowly, quietly, well.","type":"sort","props":{"buckets":[{"id":"adj","label":"Adjective","icon":"Palette"},{"id":"adv","label":"Adverb","icon":"Zap"}],"items":[{"id":"x1","text":"big","bucket":"adj"},{"id":"x2","text":"slowly","bucket":"adv"},{"id":"x3","text":"happy","bucket":"adj"},{"id":"x4","text":"quietly","bucket":"adv"},{"id":"x5","text":"red","bucket":"adj"},{"id":"x6","text":"well","bucket":"adv","feedback":"\\"Well\\" es el adverbio de \\"good\\": She sings well."},{"id":"x7","text":"slow","bucket":"adj","feedback":"Sin -ly describe a una cosa: a slow turtle."}]},"id":"s05-l3-2-6"},{"fase":"construir","areas":["l3"],"cnb":["l3:2.2.3"],"ambito":"hacer","prompt":"Ordena las palabras para decir: \\"Ella tiene una mochila roja\\".","hint":"Quién + verbo + a + adjetivo + sustantivo.","explain":"She (quién) + has (verbo) + a + red (adjetivo) + backpack (sustantivo).","type":"order","props":{"labels":{"start":"Primera","end":"Última"},"items":[{"id":"o1","text":"She"},{"id":"o2","text":"has"},{"id":"o3","text":"a"},{"id":"o4","text":"red"},{"id":"o5","text":"backpack."}]},"id":"s05-l3-2-7"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:2.2.3"],"ambito":"hacer","prompt":"¿Adjetivo o adverbio? Elige la palabra correcta.","explain":"Quiet (adjetivo) describe la biblioteca. Quietly (adverbio) dice cómo leemos. Careful describe a la conductora; carefully dice cómo maneja.","type":"fill-blank","props":{"text":"The library is [[quiet]]. We read [[quietly]]. My aunt is a [[careful]] driver. She drives [[carefully]]."},"id":"s05-l3-2-8"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:2.2.3"],"ambito":"hacer","prompt":"Describe lo que hacen los niños en el recreo: juegan felizmente en el patio grande.","explain":"**The children play happily in the big yard.** Adjetivo antes del sustantivo (big yard) y adverbio después del verbo (play happily).","type":"choice","props":{"options":[{"id":"a","text":"The children play happily in the big yard."},{"id":"b","text":"The children play happy in the yard big.","feedback":"Dos errores: la acción necesita adverbio (happily) y el adjetivo va antes (big yard)."},{"id":"c","text":"Happily the children the big yard play.","feedback":"El orden está mezclado: quién + verbo + cómo + dónde."}],"correct":["a"]},"id":"s05-l3-2-9"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:2.2.3"],"ambito":"hacer","prompt":"Ordena las palabras para decir: \\"Mi hermano toca el tambor fuerte (con fuerza)\\".","explain":"My brother (quién) + plays (verbo con -s) + the drum (qué cosa) + loudly (cómo).","type":"order","props":{"labels":{"start":"Primera","end":"Última"},"items":[{"id":"o1","text":"My"},{"id":"o2","text":"brother"},{"id":"o3","text":"plays"},{"id":"o4","text":"the"},{"id":"o5","text":"drum"},{"id":"o6","text":"loudly."}]},"id":"s05-l3-2-10"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:2.2.3"],"ambito":"hacer","prompt":"Escribe **dos oraciones en inglés** sobre tu familia: una con un **adjetivo antes de un sustantivo** y otra con un **adverbio** que diga cómo alguien hace algo.","type":"short-answer","props":{"minWords":10,"placeholder":"My mom has a… My brother runs…","model":"My grandfather has a small farm. My sister sings beautifully.","rubric":["Escribí dos oraciones en inglés","Usé un adjetivo antes de un sustantivo (a small farm)","Usé un adverbio después del verbo (sings beautifully)","Usé la -s con he o she cuando tocaba"]},"id":"s05-l3-2-11"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:2.2.3"],"prompt":"Boleto de salida: ¿qué oración está bien escrita?","type":"choice","props":{"options":[{"id":"a","text":"I have two dogs bigs."},{"id":"b","text":"I have two big dogs."},{"id":"c","text":"I have two bigs dogs."}],"correct":["b"]},"id":"s05-l3-2-12"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:2.2.3"],"prompt":"Completa: \\"La tortuga camina despacio. El conejo corre rápido.\\"","type":"fill-blank","props":{"text":"The turtle walks [[slowly]]. The rabbit runs [[fast]].","distractors":["slow","fastly"]},"id":"s05-l3-2-13"},{"fase":"reflexionar","areas":["l3"],"cnb":[],"ambito":"ser","prompt":"How was your week? ¿Cómo te fue?","type":"reflection","props":{"statements":["Uso los pronombres I, you, he, she, it, we, they","Ordeno oraciones: quién + verbo + cosa","Pongo el adjetivo antes del sustantivo","Uso adverbios como slowly, fast y well"],"commitments":["Describiré en inglés tres cosas de mi casa con adjetivos","Diré en inglés cómo hace algo cada persona de mi familia","Revisaré la -s de he y she cuando escriba"]},"id":"s05-l3-2-14"}],"kind":"materia","area":"l3","day":4}},{"missionId":"s05","version":"cnb-sexto-7f751385b4f04533","lesson":{"id":"s05-l2-2","title":"Convencer con razones","icon":"MessagesSquare","minutes":15,"gancho":"Dos compañeros piden un huerto escolar. Uno dice \\"¡Porque sí!\\". La otra da tres razones. ¿A quién le hará caso la directora?","objetivos":["Construir un mensaje argumentativo con razones verificables"],"resumen":["Los mensajes tienen intenciones: informar (dar datos), explicar (decir cómo o por qué) y argumentar (convencer).","Un mensaje argumentativo tiene: una opinión clara, razones que la apoyan y un cierre que invita a actuar.","Justificar es apoyar la opinión con información: datos comprobables, ejemplos o lo que dice una fuente confiable (centro de salud, libro, persona experta).","No justifica: \\"porque sí\\", \\"todos lo dicen\\" o información que no tiene que ver con el tema."],"media":{"id":"s05-l2-2-balanza","kind":"animation","title":"La balanza de las razones","aspect":"16:9","duration":45,"alt":"Una balanza: de un lado la frase \\"¡Porque sí!\\", que casi no pesa; del otro, tres bloques con razones y datos que la inclinan con fuerza.","brief":"Animación 2D de 45 s. Una niña y un niño frente a la directora de una escuela guatemalteca (sin logotipos). El niño dice \\"¡Queremos un huerto porque sí!\\" y su frase cae como una pluma en un plato de una balanza, que casi no se mueve. La niña dice \\"Queremos un huerto\\" y deja caer tres bloques: \\"Aprenderíamos ciencias haciendo\\", \\"Tendríamos hierbas para la refacción\\", \\"El terreno de atrás está sin usar\\". La balanza se inclina hacia su lado. Texto final: \\"Opinión + razones + cierre\\". Narración en español de Guatemala, subtítulos."},"steps":[{"fase":"explorar","areas":["l2"],"cnb":["l2:3.3.4"],"ambito":"conocer","prompt":"Distingue una opinión de las razones que pueden sostenerla.","type":"explain","props":{"icon":"Scale","body":"Un mensaje persuasivo presenta una postura y razones pertinentes. Para proponer una mejora escolar, conviene explicar qué barrera existe, a quién afecta y cómo la propuesta ayudaría."},"id":"s05-l2-2-1"},{"fase":"construir","areas":["l2"],"cnb":["l2:3.3.4"],"ambito":"conocer","prompt":"Dos compañeros le piden a la directora un huerto escolar. ¿Qué mensaje la **convencerá** más?","explain":"Las **razones** dan fuerza a una opinión. Hoy aprenderás a construir mensajes que convencen y a justificar lo que dices.","type":"choice","props":{"options":[{"id":"a","text":"\\"¡Queremos un huerto porque sí!\\"","icon":"Megaphone","feedback":"\\"Porque sí\\" no es una razón: la directora no sabe por qué sería bueno."},{"id":"b","text":"\\"Queremos un huerto: aprenderíamos ciencias haciendo, tendríamos hierbas para la refacción y el terreno de atrás está sin usar.\\"","icon":"Sprout"}],"correct":["b"]},"id":"s05-l2-2-2"},{"fase":"construir","areas":["l2"],"cnb":["l2:3.3.4"],"ambito":"conocer","title":"Tres intenciones de un mensaje","prompt":"Antes de hablar o escribir, pregúntate: **¿para qué es mi mensaje?** Toca cada intención.","type":"explain","props":{"icon":"Target","body":"La intención decide qué incluyes: datos, pasos y causas, o razones.","reveal":[{"icon":"Newspaper","front":"Informar","back":"Dar a conocer **hechos o datos**: qué, quién, cuándo, dónde. Ejemplo: \\"El jueves habrá vacunación en el puesto de salud, de 8 a 12\\"."},{"icon":"Lightbulb","front":"Explicar (exponer)","back":"Decir **cómo funciona o por qué** pasa algo, con orden. Ejemplo: una exposición sobre cómo se forma la lluvia."},{"icon":"Scale","front":"Argumentar","back":"**Convencer** con una opinión y razones. Ejemplo: \\"Debemos cuidar el río, porque de él toma agua la comunidad\\"."}]},"id":"s05-l2-2-3"},{"fase":"construir","areas":["l2"],"cnb":["l2:3.3.4"],"ambito":"hacer","prompt":"Ahora tú, con ayuda: ¿cuál es la intención de cada mensaje?","hint":"¿Da datos? → informa. ¿Dice cómo o por qué? → explica. ¿Quiere que pienses o hagas algo? → argumenta.","explain":"Reconocer la intención te ayuda a escuchar con atención y a no dejarte convencer sin razones.","type":"sort","props":{"buckets":[{"id":"inf","label":"Informar","icon":"Newspaper","color":"var(--area-l2)"},{"id":"exp","label":"Explicar","icon":"Lightbulb","color":"var(--c-ok)"},{"id":"arg","label":"Argumentar","icon":"Scale","color":"var(--c-maiz-strong)"}],"items":[{"id":"i1","text":"La feria del pueblo será del 10 al 15 de agosto.","bucket":"inf"},{"id":"i2","text":"El agua del río se evapora con el calor del sol, forma nubes y vuelve a caer como lluvia.","bucket":"exp"},{"id":"i3","text":"Debemos apagar las luces al salir, porque así ahorramos energía y dinero.","bucket":"arg"},{"id":"i4","text":"Mañana no habrá clases por reunión de maestros.","bucket":"inf"},{"id":"i5","text":"Te propongo leer este libro: es emocionante y aprenderás sobre los volcanes.","bucket":"arg"},{"id":"i6","text":"Las abejas llevan el polen de una flor a otra, y así las plantas pueden formar frutos.","bucket":"exp"}]},"id":"s05-l2-2-4"},{"fase":"construir","areas":["l2"],"cnb":["l2:3.3.4"],"ambito":"conocer","title":"Cómo se construye un mensaje que convence","prompt":"Un **mensaje argumentativo** tiene tres partes. Lo más importante son las razones y la **información que las justifica**.","type":"explain","props":{"icon":"Blocks","body":"Justificar = mostrar **en qué te basas**. Una buena justificación viene de información **relacionada con el tema**, **comprobable** y de una **fuente confiable**.","reveal":[{"icon":"Flag","front":"1. Opinión","back":"Lo que piensas, dicho con claridad: \\"Creo que la escuela necesita un huerto\\"."},{"icon":"Layers","front":"2. Razones que justifican","back":"Por qué lo piensas, apoyado en información: un dato, un ejemplo o lo que dice una persona experta. Usa **porque, ya que, además**."},{"icon":"Megaphone","front":"3. Cierre","back":"Una invitación a actuar: \\"Por eso les pedimos…\\", \\"Hagámoslo juntos\\"."},{"icon":"X","front":"No justifica","back":"\\"Porque sí\\", \\"todo el mundo lo dice\\", insultos o datos que no tienen que ver con el tema."}]},"id":"s05-l2-2-5"},{"fase":"construir","areas":["l2"],"cnb":["l2:3.3.4"],"ambito":"hacer","title":"Ejemplo resuelto","prompt":"Mira cómo Rosa **selecciona** la información que justifica su opinión.","type":"worked-example","props":{"icon":"Search","problem":"Rosa quiere convencer a su grado de **llevar agua pura en botella reutilizable**. Encontró cuatro datos. ¿Cuáles usa?","steps":[{"text":"Dato A: \\"El centro de salud recomienda tomar agua segura (hervida o clorada) para prevenir enfermedades del estómago\\". → **Sí**: está relacionado y viene de una fuente confiable."},{"text":"Dato B: \\"Una botella reutilizable evita comprar muchas botellas plásticas\\". → **Sí**: es comprobable y apoya su idea."},{"text":"Dato C: \\"A mi prima le gusta el color azul\\". → **No**: no tiene relación con el tema.","why":"La información debe apoyar la opinión, no solo ser verdadera."},{"text":"Dato D: \\"Todos dicen que es lo mejor\\". → **No**: no dice quién ni por qué; no es una razón."}],"answer":"Rosa escribe: \\"Llevemos agua pura en botella reutilizable, **porque** el centro de salud recomienda tomar agua segura para prevenir enfermedades **y además** así evitamos comprar muchas botellas plásticas. ¡Empecemos el lunes!\\"","tip":"Pregunta a cada dato: ¿tiene que ver con mi opinión? ¿se puede comprobar? ¿de dónde viene?"},"id":"s05-l2-2-6"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:3.3.4"],"ambito":"hacer","prompt":"Quieres convencer a tu grado de que **hacer ejercicio mejora el ánimo**. ¿Qué información **justifica** mejor tu opinión?","explain":"Lo que explica una persona experta en salud está relacionado con el tema y es una fuente confiable.","type":"choice","props":{"options":[{"id":"a","text":"La doctora del centro de salud explicó que moverse cada día ayuda a sentirse con más energía y mejor ánimo."},{"id":"b","text":"Mi equipo favorito tiene un uniforme muy bonito.","feedback":"Es una opinión y no tiene relación con el ánimo."},{"id":"c","text":"Porque sí, todos lo saben.","feedback":"\\"Porque sí\\" y \\"todos lo saben\\" no son razones: no dicen en qué te basas."}],"correct":["a"]},"id":"s05-l2-2-7"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:3.3.4"],"ambito":"hacer","title":"Lectura","prompt":"Lee la carta que el grado de sexto escribió a la directora y responde.","type":"reading","props":{"genre":"Carta","heading":"Carta a la directora","passage":"Estimada Licda. Tzul:\\n\\nLos estudiantes de sexto grado creemos que la escuela necesita botes para separar la basura.\\n\\nDurante una semana contamos lo que quedaba en el patio después del recreo: encontramos 120 botellas plásticas y muchas bolsas de golosinas. Además, en Ciencias Naturales aprendimos que el plástico tarda muchísimos años en descomponerse. Por último, don Julio, el señor que recoge la basura, nos contó que separar los materiales le ayuda a trabajar más rápido.\\n\\nPor eso le pedimos que nos permita colocar tres botes con rótulos: orgánico, plástico y papel. Nosotros podemos pintarlos.\\n\\nAtentamente,\\nEstudiantes de sexto grado","questions":[{"q":"¿Cuál es la **intención** de la carta?","options":[{"id":"a","text":"Convencer a la directora de colocar botes para separar la basura"},{"id":"b","text":"Explicar cómo se fabrica el plástico"},{"id":"c","text":"Informar la fecha de la feria escolar"}],"correct":"a","why":"Tiene una opinión, razones y un pedido: es un mensaje argumentativo."},{"q":"¿Qué información justifica la opinión con un **dato que ellos mismos comprobaron**?","options":[{"id":"a","text":"Que contaron 120 botellas plásticas en una semana"},{"id":"b","text":"Que ellos pueden pintar los botes"},{"id":"c","text":"Que la carta termina con \\"Atentamente\\""}],"correct":"a","why":"Contaron durante una semana: es información comprobable y relacionada con el problema."},{"q":"¿Por qué incluir lo que dijo don Julio hace la carta más convincente?","options":[{"id":"a","text":"Porque es una persona que conoce el tema por su trabajo"},{"id":"b","text":"Porque es un señor muy simpático"},{"id":"c","text":"Porque así la carta es más larga"}],"correct":"a","why":"Una fuente que conoce el tema de primera mano fortalece la justificación."}]},"id":"s05-l2-2-8"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:3.3.4"],"ambito":"hacer","prompt":"Imagina que te postulas para el gobierno escolar. Escribe **una propuesta** para mejorar tu escuela: tu **opinión**, **dos razones** con información que las justifique y un **cierre**.","type":"short-answer","props":{"minWords":35,"placeholder":"Propongo que… porque…","model":"Propongo que abramos un rincón de lectura en el corredor. Primero, porque en la biblioteca solo caben diez estudiantes a la vez, y así más compañeros podrían leer en el recreo. Además, la maestra de Comunicación nos explicó que leer un rato cada día mejora la comprensión. ¡Votemos por un recreo con libros!","rubric":["Escribí una opinión clara","Di dos razones","Cada razón se apoya en información relacionada y comprobable","Terminé con un cierre que invita a actuar"]},"id":"s05-l2-2-9"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:3.3.4"],"prompt":"Boleto de salida: _\\"Debemos sembrar árboles en la orilla del río, porque sus raíces sostienen la tierra y evitan derrumbes.\\"_ ¿Qué intención tiene este mensaje?","type":"choice","props":{"options":[{"id":"a","text":"Argumentar: convencer con una razón"},{"id":"b","text":"Informar una fecha"},{"id":"c","text":"Dar instrucciones para sembrar"}],"correct":["a"]},"id":"s05-l2-2-10"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:3.3.4"],"prompt":"Quieres convencer a tu familia de **lavarse las manos antes de comer**. ¿Qué mensaje argumentativo justifica mejor tu opinión?","type":"choice","props":{"options":[{"id":"a","text":"El personal de salud explica que lavarse las manos con agua y jabón elimina microbios que causan enfermedades."},{"id":"b","text":"Porque me dijeron que sí."},{"id":"c","text":"El jabón de mi casa huele a limón."}],"correct":["a"]},"id":"s05-l2-2-11"},{"fase":"reflexionar","areas":["l2"],"cnb":[],"ambito":"ser","prompt":"¿Cómo te fue esta semana?","type":"reflection","props":{"statements":["Represento un cuento con postura, gestos y movimientos","Distingo si un mensaje informa, explica o argumenta","Justifico mi opinión con información confiable"],"commitments":["Participaré en una dramatización con el papel que elija","Cuando dé mi opinión, diré al menos una razón","Preguntaré \\"¿en qué te basas?\\" antes de creer un mensaje"]},"id":"s05-l2-2-12"}],"kind":"materia","area":"l2","day":4}},{"missionId":"s05","version":"cnb-sexto-58100f16150e2389","lesson":{"id":"s05-fc-2","title":"El gobierno escolar: elegir, proponer y servir","icon":"Vote","minutes":15,"gancho":"Imagina que tu escuela va a elegir a su gobierno escolar mañana. ¿Por quién votarías: por el más popular o por quien tenga las mejores propuestas?","objetivos":["Evaluar la participación y las propuestas del gobierno escolar"],"resumen":["El gobierno escolar es una organización de estudiantes elegida por voto que representa a sus compañeros, organiza proyectos y trabaja con docentes y dirección. En cada grado también puede haber una directiva de aula.","Cargos frecuentes: presidencia, vicepresidencia, secretaría, tesorería y vocales. Las comisiones (limpieza, deporte, cultura, lectura, huerto) organizan el trabajo.","Una elección democrática sigue pasos: convocatoria, inscripción de planillas, campaña con propuestas, votación secreta, conteo público, toma de posesión y rendición de cuentas.","Una buena propuesta responde a un problema real, es posible con los recursos de la escuela, dice cómo se hará y se puede comprobar si se cumplió."],"media":{"id":"s05-fc-2-eleccion","kind":"video","title":"Así elegimos a nuestro gobierno escolar","aspect":"16:9","duration":75,"alt":"Video animado que muestra una elección en una escuela guatemalteca: planillas con carteles, estudiantes votando detrás de una mampara, conteo en voz alta y juramentación.","brief":"Video animado de 75 s. Escenas: (1) Cartel de convocatoria en el corredor. (2) Tres planillas mixtas (niñas y niños) presentan propuestas en carteles: \\"Rincón de lectura\\", \\"Torneo con equipos mixtos\\", \\"Huerto escolar\\". (3) Día de votación: mesa electoral con estudiantes, papeleta sencilla, mampara de cartón, urna transparente, dedo marcado con tinta. (4) Conteo en voz alta frente a todos, rayitas en el pizarrón. (5) Toma de posesión y, meses después, la planilla ganadora presenta su informe en el periódico mural. Narración en español, subtítulos. Sin logotipos de partidos ni nombres reales."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":["fc:3.2.2"],"ambito":"conocer","prompt":"Relaciona representación estudiantil, propuestas y bien común.","type":"explain","props":{"icon":"Vote","body":"El gobierno escolar representa al estudiantado mediante elección y servicio. Una propuesta responsable parte de una necesidad comprobada, consulta a las personas afectadas y plantea acciones posibles."},"id":"s05-fc-2-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.2"],"ambito":"convivir","prompt":"Hay elección de gobierno escolar. ¿En qué te fijarías **más** para decidir tu voto?","explain":"Lo más importante son las **propuestas**: ¿resuelven un problema real? ¿se pueden cumplir? Un voto responsable mira ideas, no popularidad ni regalos.","type":"choice","props":{"options":[{"id":"a","text":"En sus propuestas y en si se pueden cumplir","icon":"ClipboardList"},{"id":"b","text":"En quién regala más dulces","icon":"Gift","feedback":"Un regalo dura un momento; un mal gobierno escolar dura todo el año. Fíjate en las propuestas."},{"id":"c","text":"En quién es mi mejor amigo","icon":"Heart","feedback":"La amistad es valiosa, pero para gobernar importan las ideas y la responsabilidad."}],"correct":["a"]},"id":"s05-fc-2-2"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.2"],"ambito":"conocer","title":"¿Qué es el gobierno escolar?","prompt":"El **gobierno escolar** es una organización de estudiantes **elegida por voto** que representa a sus compañeros y organiza proyectos para mejorar la escuela. Toca cada tarjeta.","type":"explain","props":{"icon":"School","body":"Gobernar la escuela es **servir**: escuchar a los compañeros, trabajar con docentes y dirección, y rendir cuentas.","reveal":[{"icon":"Users","front":"Cargos","back":"**Presidencia** (coordina), **vicepresidencia** (apoya y reemplaza), **secretaría** (escribe actas), **tesorería** (cuida y reporta el dinero) y **vocales** (apoyan comisiones)."},{"icon":"ClipboardList","front":"Comisiones","back":"Grupos de trabajo: limpieza y ambiente, deporte, cultura, lectura, huerto, disciplina y convivencia."},{"icon":"LayoutGrid","front":"Gobierno del aula","back":"En cada grado, una **directiva de aula** organiza tareas, turnos y acuerdos del grado."},{"icon":"FileText","front":"Actas","back":"Documento donde la secretaría anota lo que se **acordó** en cada reunión, con fecha y firmas."}]},"id":"s05-fc-2-3"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.2"],"prompt":"Une cada cargo con su función principal.","hint":"Recuerda las tarjetas: la secretaría escribe las actas y la tesorería cuida el dinero (el \\"tesoro\\") del grupo.","explain":"Cada cargo tiene una responsabilidad clara; así el trabajo se reparte y nadie decide solo.","type":"match","props":{"leftTitle":"Cargo","rightTitle":"Función","pairs":[{"id":"c1","left":"Presidencia","leftIcon":"Crown","right":"Coordina las reuniones y representa al grupo"},{"id":"c2","left":"Secretaría","leftIcon":"PenLine","right":"Escribe las actas de los acuerdos"},{"id":"c3","left":"Tesorería","leftIcon":"Coins","right":"Cuida el dinero e informa cómo se usa"},{"id":"c4","left":"Vocales","leftIcon":"Users","right":"Apoyan y coordinan las comisiones"}]},"id":"s05-fc-2-4"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.2"],"prompt":"Ordena los pasos de una **elección escolar democrática**.","hint":"Primero se anuncia la elección; lo último es informar lo que se hizo en el año.","explain":"Convocatoria → planillas → campaña → votación secreta → conteo público → toma de posesión → rendición de cuentas.","type":"order","props":{"labels":{"start":"Inicio","end":"Final"},"items":[{"id":"o1","text":"Se publica la convocatoria con fechas y reglas","icon":"Megaphone"},{"id":"o2","text":"Se inscriben las planillas con sus candidatos","icon":"Users"},{"id":"o3","text":"Cada planilla presenta sus propuestas en la campaña","icon":"ClipboardList"},{"id":"o4","text":"Los estudiantes votan en secreto","icon":"Vote"},{"id":"o5","text":"Se cuentan los votos frente a todos","icon":"ListOrdered"},{"id":"o6","text":"La planilla ganadora toma posesión","icon":"Award"},{"id":"o7","text":"El gobierno escolar rinde cuentas de su trabajo","icon":"FileText"}]},"id":"s05-fc-2-5"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.2"],"ambito":"hacer","title":"Ejemplo resuelto: ¿es una buena propuesta?","prompt":"Las propuestas se evalúan con **cuatro preguntas**. Mira cómo se comparan dos propuestas.","type":"worked-example","props":{"icon":"Lightbulb","problem":"Planilla Verde propone: **\\"Vamos a construir una piscina.\\"** Planilla Azul propone: **\\"Crearemos un rincón de lectura en el corredor con libros donados y cajas recicladas, abierto en el recreo; cada mes contaremos cuántos libros se prestaron.\\"**","steps":[{"text":"**¿Responde a un problema real?** Verde: no dice qué problema resuelve. Azul: sí, la biblioteca está cerrada en el recreo."},{"text":"**¿Es posible con los recursos de la escuela?** Verde: no, una piscina cuesta muchísimo. Azul: sí, usa donaciones y material reciclado.","why":"Prometer lo imposible engaña a los votantes."},{"text":"**¿Dice cómo se hará?** Verde: no. Azul: sí (libros donados, cajas, horario de recreo)."},{"text":"**¿Se puede comprobar si se cumplió?** Verde: no dice cómo. Azul: sí, contarán los préstamos cada mes."}],"answer":"La propuesta de la **Planilla Azul** es buena: real, posible, explica cómo y se puede comprobar. La de la Verde es una **promesa imposible**.","tip":"Problema real → posible → cómo → se puede comprobar."},"id":"s05-fc-2-6"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.2"],"prompt":"Clasifica estas propuestas de campaña: ¿**realista y útil** o **promesa vacía**?","hint":"Usa las cuatro preguntas: problema real, posible, cómo, comprobable.","explain":"Las propuestas realistas se pueden cumplir con los recursos de la escuela y dicen cómo; las promesas vacías suenan bonito pero no se pueden cumplir o no dicen nada concreto.","type":"sort","props":{"buckets":[{"id":"ok","label":"Realista y útil","icon":"Check","color":"var(--c-ok)"},{"id":"va","label":"Promesa vacía","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"q1","text":"Organizar turnos por grado para limpiar el patio cada viernes","bucket":"ok"},{"id":"q2","text":"\\"Haremos la mejor escuela del mundo\\"","bucket":"va","feedback":"Suena bonito, pero no dice qué problema resuelve ni cómo."},{"id":"q3","text":"Quitar todas las tareas para siempre","bucket":"va"},{"id":"q4","text":"Un torneo de fútbol y básquetbol con equipos mixtos en el recreo","bucket":"ok"},{"id":"q5","text":"Sembrar un huerto con semillas donadas por las familias","bucket":"ok"}]},"id":"s05-fc-2-7"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:3.2.2"],"ambito":"convivir","prompt":"Un candidato te ofrece una bolsa de dulces a cambio de tu voto. ¿Qué decisión permite evaluar las propuestas y proteger una elección libre?","type":"choice","props":{"options":[{"id":"a","text":"Aceptar los dulces y votar por quien los regaló"},{"id":"b","text":"Rechazar el regalo, comparar las propuestas y reportar la oferta a la comisión electoral"},{"id":"c","text":"Aceptar los dulces y votar al azar para que nadie se entere"}],"correct":["b"]},"id":"s05-fc-2-8"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:3.2.2"],"ambito":"emprender","prompt":"Imagina que te postulas al gobierno escolar. Escribe **una propuesta** que pase las cuatro preguntas: ¿qué problema real resuelve?, ¿con qué recursos?, ¿cómo lo harás? y ¿cómo se comprobará que cumpliste?","type":"short-answer","props":{"minWords":40,"placeholder":"Mi propuesta es… porque en mi escuela…","model":"Mi propuesta es poner dos toneles para recolectar agua de lluvia junto al huerto, porque en época seca las plantas se mueren y el chorro de la escuela no alcanza. Pediremos los toneles usados a las familias y la comisión de ambiente los limpiará y pondrá una canaleta del techo. Cada viernes anotaremos cuántas cubetas de agua usamos del tonel; así todos podrán comprobar si funciona.","rubric":["Nombré un problema real de mi escuela","Mi propuesta es posible con recursos de la escuela o la comunidad","Expliqué cómo se hará y quién lo hará","Dije cómo se comprobará que se cumplió"]},"id":"s05-fc-2-9"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:3.2.2"],"prompt":"¿Qué oración describe una **participación democrática** en el gobierno escolar?","type":"choice","props":{"options":[{"id":"a","text":"Las planillas presentaron propuestas y los estudiantes votaron en secreto."},{"id":"b","text":"El director eligió solo al presidente, sin votación."},{"id":"c","text":"Ganó la planilla que regaló más refacciones."}],"correct":["a"]},"id":"s05-fc-2-10"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:3.2.2"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"La tesorería del gobierno escolar cuida el dinero e informa cómo se usa.","answer":true},{"text":"Los votos se deben contar frente a todos para que haya transparencia.","answer":true},{"text":"\\"Construiremos un estadio\\" es una propuesta realista para un gobierno escolar.","answer":false,"why":"Es una promesa imposible con los recursos de una escuela."},{"text":"Después de ganar, el gobierno escolar ya no tiene que informar nada.","answer":false,"why":"Debe rendir cuentas de su trabajo a todos los estudiantes."}]},"id":"s05-fc-2-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["fc"],"cnb":["fc:3.2.1","fc:3.2.2"],"type":"reflection","props":{"statements":["Explico qué es participar y dónde puedo hacerlo","Conozco los cargos y los pasos de la elección del gobierno escolar","Distingo una propuesta realista de una promesa vacía"],"commitments":["Votaré por propuestas y no por regalos","Me uniré a una comisión de mi grado o escuela","Propondré en casa repartir las tareas del hogar entre todos"]},"id":"s05-fc-2-12"}],"kind":"materia","area":"fc","day":5}},{"missionId":"s05","version":"cnb-sexto-411c631a8d5fb3db","lesson":{"id":"s05-d5-taller","kind":"taller","day":5,"title":"Mapa táctil para toda la escuela","icon":"Map","minutes":18,"objetivos":["Aplicar coordenadas, textura, participación y manejo seguro de materiales para construir, probar y revisar un plano táctil escolar"],"resumen":["El producto es un plano táctil con coordenadas, una leyenda y una ruta accesible propuesta.","La prueba entre pares revisa claridad con los ojos abiertos; la consulta especializada con personas con discapacidad o especialistas queda pendiente.","El mapa orienta, pero no sustituye la eliminación de barreras físicas, comunicativas, sensoriales y actitudinales."],"media":{"id":"s05-taller-kit-tactil","kind":"image","title":"Kit reutilizable de plano táctil","aspect":"4:3","alt":"Bandeja rotulada con base cuadriculada, piezas lavables de tres texturas, tiras corrugadas para la ruta, etiquetas grandes, cierres removibles y un rodillo manual redondeado.","brief":"Activo físico de alta preparación pendiente. Reemplazo durable: 8 kits reutilizables para grupos de 3 o 4, cada uno en bandeja rotulada, con base rígida lavable cuadriculada de 40 por 40 cm, ejes y coordenadas de alto contraste, piezas grandes precortadas de EVA lisa para aprendizaje y corcho rugoso para servicios, tiras continuas de plástico corrugado para circulación, cierres de gancho y felpa ya instalados, etiquetas impresas grandes, tres muestras para la clave y un rodillo manual redondeado de goma de baja fuerza. Todas las esquinas deben estar redondeadas y las piezas deben llegar firmes y listas para reutilizar. Preparación central: fabricar y probar una vez, registrar piezas, comprobar que cada rodillo gire sin daño y guardar cada kit completo. Preparación docente normal, máximo 2 minutos: distribuir una bandeja por grupo y comprobar con la lista base, ruta corrugada, zonas, tres muestras y rodillo. Alternativa de baja tecnología: cartón corrugado y retazos limpios preparados por una persona adulta fuera del tiempo de clase, con cierres removibles ya colocados. Toda fabricación permanente ocurre en la preparación central, fuera de la sesión habitual. Dimensiones: 1200x900."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":["fc:3.2.1"],"ambito":"convivir","title":"1 min · Encargo y límites","prompt":"**1 min.** La escuela pide un plano táctil. Hoy usarán criterios publicados y un caso ficticio, no evidencia de una consulta local.","type":"explain","props":{"icon":"MessageCircleQuestion","body":"La prueba entre pares permite revisar claridad, pero no sustituye la participación de personas con discapacidad. Registren **consulta especializada pendiente** y no atribuyan opiniones no expresadas. Un plano puede apoyar la orientación, pero **no garantiza acceso para todas las personas** ni elimina todas las barreras físicas, de comunicación, sensoriales y actitudinales."},"id":"s05-d5-taller-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.2.1","fc:3.2.2"],"ambito":"convivir","title":"1 min · Lean el caso ficticio","prompt":"**1 min.** Lean un brief ficticio compuesto a partir de criterios publicados de accesibilidad y anoten dos requisitos de diseño.","type":"project","props":{"goal":"Convertir una referencia claramente etiquetada en requisitos verificables, sin presentarla como consulta local.","steps":[{"title":"Caso ficticio","detail":"El encargo propone conectar entrada, dirección, aula de sexto y baños."},{"title":"Criterios publicados","detail":"La referencia recomienda una ruta continua en relieve, rótulos grandes y texturas contrastantes."}],"evidence":"Dos requisitos escritos en la hoja del equipo.","rubric":["Identificamos la fuente como ficticia y publicada","No afirmamos haber consultado a una persona local"]},"id":"s05-d5-taller-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.5.3"],"ambito":"hacer","title":"1 min · Verifiquen una coordenada","prompt":"**1 min.** Con la entrada como origen, coloquen la dirección en **(−3, 2)**.","hint":"Primero x: 3 a la izquierda. Después y: 2 hacia arriba.","explain":"(−3, 2) queda a la izquierda y arriba del origen.","type":"coordinate-map","props":{"range":{"xmin":-5,"xmax":5,"ymin":-5,"ymax":5},"task":{"kind":"place","x":-3,"y":2,"emoji":"🏫","label":"Dirección"}},"id":"s05-d5-taller-3"},{"fase":"aplicar","areas":["mat","fc"],"cnb":["mat:1.5.3","fc:3.2.1"],"ambito":"hacer","title":"2 min · Armen la base","prompt":"**2 min.** Usen el kit preparado. Definan el origen y ubiquen cuatro destinos según el brief ficticio.","type":"project","props":{"goal":"Construir la base coordenada del plano.","steps":[{"title":"Origen","detail":"Marquen la entrada principal como (0, 0) y mantengan visibles los ejes x e y."},{"title":"Cuatro destinos","detail":"Coloquen dirección (−3, 2), aula (2, 3), baños (4, −2) y bebedero (1, −3)."}],"evidence":"Base con origen, ejes, coordenadas y cuatro lugares rotulados.","rubric":["Leímos cada par como x y luego y","Los cuatro destinos coinciden con sus coordenadas"]},"id":"s05-d5-taller-4"},{"fase":"aplicar","areas":["mat","art"],"cnb":["mat:1.5.3","art:3.2.1"],"ambito":"hacer","title":"1 min · Alineen símbolos y datos","prompt":"**1 min.** Antes de fijar las piezas, unan cada destino con su coordenada y textura acordada.","type":"match","props":{"leftTitle":"Destino","rightTitle":"Dato del plano","pairs":[{"id":"a","left":"Dirección","right":"(−3, 2) · corcho rugoso"},{"id":"b","left":"Aula","right":"(2, 3) · EVA lisa"},{"id":"c","left":"Baños","right":"(4, −2) · corcho rugoso"},{"id":"d","left":"Bebedero","right":"(1, −3) · corcho rugoso"}]},"id":"s05-d5-taller-5"},{"fase":"aplicar","areas":["art"],"cnb":["art:3.2.1"],"ambito":"hacer","title":"2 min · Construyan la leyenda","prompt":"**2 min.** Usen las tres muestras preparadas del kit para crear una clave táctil y visual concisa.","type":"project","props":{"goal":"Crear una leyenda táctil y visual consistente.","steps":[{"title":"Tres muestras","detail":"Asignen EVA lisa a aprendizaje (aula), corcho rugoso a servicios (Dirección, baños y bebedero) y plástico corrugado a circulación (ruta)."},{"title":"Clave","detail":"Fijen una muestra de cada textura junto a su nombre en letra grande y alto contraste."}],"evidence":"Clave con tres muestras seguras y sus significados.","rubric":["Las tres texturas se distinguen entre sí","Aula usa EVA, los tres servicios usan corcho y la ruta usa plástico corrugado"]},"id":"s05-d5-taller-6"},{"fase":"aplicar","areas":["mat","art","pyd"],"cnb":["mat:1.5.3","art:3.2.1","pyd:3.2.3","pyd:3.2.4"],"ambito":"hacer","title":"3 min · Marquen y fijen la ruta","prompt":"**3 min.** Unan entrada, dirección, aula y baños con las tiras continuas de plástico corrugado para circulación; después usen el rodillo manual redondeado para presionar sus cierres removibles.","type":"project","props":{"goal":"Representar y fijar al producto una ruta accesible propuesta mediante la técnica segura ya practicada.","steps":[{"title":"Ruta de circulación","detail":"Fijen las tiras de plástico corrugado sin cruces ni extremos sueltos y dejen libres las etiquetas."},{"title":"Rodillo seguro","detail":"Revisen mango, rueda y eje; apoyen la base en una mesa estable, mantengan los dedos fuera de la trayectoria y hagan una pasada con presión controlada. Si está flojo, dañado o trabado, no lo usen y repórtenlo."},{"title":"Comprobación física","detail":"Comparen la propuesta con el pasillo real: ancho, escalones, pendientes, puertas y objetos que obstruyen requieren revisión de la escuela."}],"evidence":"Ruta corrugada firme con cuatro paradas coordenadas, lista de barreras por verificar y marcas de herramienta revisada, dedos fuera de la trayectoria y presión controlada.","rubric":["La ruta de circulación conserva el plástico corrugado de la clave","La técnica segura quedó comprobada en el producto","No presentamos como accesible un tramo que no fue verificado"]},"id":"s05-d5-taller-7"},{"fase":"aplicar","areas":["fc","art"],"cnb":["fc:3.2.1","art:3.2.1"],"ambito":"convivir","title":"2 min · Prueba de claridad entre pares","prompt":"**2 min.** Un compañero, con los ojos abiertos y participando como él mismo, localiza los baños desde la entrada. Registra qué símbolo le resultó claro o confuso y una sugerencia. Identifica la fuente como **prueba entre pares**; la consulta especializada permanece pendiente.","type":"short-answer","props":{"minWords":8,"placeholder":"Prueba entre pares: el símbolo...; sugerencia...","model":"Formato de registro, no evidencia: \\"Prueba entre pares: [símbolo claro o confuso]. La sugerencia expresada fue [comentario real].\\"","rubric":["Registré retroalimentación real de la prueba","No la presenté como consulta especializada"]},"id":"s05-d5-taller-8"},{"fase":"aplicar","areas":["mat","art","pyd"],"cnb":["mat:1.5.3","art:3.2.1","pyd:3.2.3"],"ambito":"hacer","title":"2 min · Revisión dirigida","prompt":"**2 min.** Corrijan una dificultad observada y vuelvan a comprobar coordenadas, leyenda, ruta y seguridad.","type":"project","props":{"goal":"Mejorar el producto con evidencia.","steps":[{"title":"Una corrección","detail":"Muevan una pieza, separen elementos o reparen una tira de la ruta según la retroalimentación entre pares, sin cambiar el código de la clave."},{"title":"Lista final","detail":"Verifiquen cuatro coordenadas y la misma clave en todo el producto: aula con EVA lisa; Dirección, baños y bebedero con corcho rugoso; ruta con plástico corrugado."}],"evidence":"Plano revisado y nota breve que relaciona observación, cambio y nueva comprobación de lugares, ruta y clave.","rubric":["El cambio responde a evidencia de la prueba","Lugares, ruta y clave conservan la misma correspondencia de texturas"]},"id":"s05-d5-taller-9"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:3.2.1"],"title":"1 min · Salida de participación","prompt":"**1 min.** En un caso ficticio, una futura consultora indica que dos texturas se confunden. ¿Qué acción respetaría su participación?","type":"choice","props":{"options":[{"id":"a","text":"Pedirle que compare alternativas y cambiar la clave según la prueba"},{"id":"b","text":"Explicarle que el equipo ya decidió y conservar el diseño"},{"id":"c","text":"Hablar por ella ante la dirección sin volver a consultarla"}],"correct":["a"]},"id":"s05-d5-taller-10"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:3.2.4"],"title":"1 min · Salida de seguridad","prompt":"**1 min.** Al revisar el kit aparece una pieza con una esquina cortante. ¿Qué corresponde?","type":"choice","props":{"options":[{"id":"a","text":"Retirarla, reportarla y usar una pieza segura de reemplazo"},{"id":"b","text":"Cubrirla con la mano durante la prueba"},{"id":"c","text":"Dejarla porque la actividad dura pocos minutos"}],"correct":["a"]},"id":"s05-d5-taller-11"},{"fase":"reflexionar","areas":["mat","art","fc","pyd"],"cnb":["mat:1.5.3","art:3.2.1","fc:3.2.1","pyd:3.2.4"],"ambito":"ser","title":"1 min · Reflexión","prompt":"**1 min.** Revisa la evidencia del equipo y elige un compromiso realista.","type":"reflection","props":{"statements":["Usé coordenadas coherentes entre el plano y la ruta","Hice coincidir texturas y clave","Registré la retroalimentación de la prueba entre pares sin presentarla como consulta especializada","Anoté el estado honesto: consulta especializada pendiente","Reconozco barreras que el mapa no resuelve"],"commitments":["Presentaré la lista de barreras al gobierno escolar","Como próximo paso, solicitaré a la dirección una consulta con personas con discapacidad o especialistas antes de fabricar una versión permanente","Guardaré el kit completo para que otro grupo pueda revisarlo"]},"id":"s05-d5-taller-12"}]}}]'),o={mission:a,lessons:e};export{o as default,e as lessons,a as mission};
